-- Generated by tools/import-forever-audio.js from CatQuest_Voices subtitles.
-- Source: Cathey (daniilcathey), https://t.me/catheyco. Includes Classic overlaps.
WowVoiceQuestTexts = { schemaVersion = 1, sourceVersion = "0.3.0", entries = {
    ["2a"] = { common = "Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы. Сенани Громосерд на заставе Расщеплённого Древа несомненно пожелает увидеть этот трофей – доказательство ваших деяний." },
    ["2c"] = { male = "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте! Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Дерева. Несомненно, скоро разойдётся весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!", female = "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте! Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Дерева. Несомненно, скоро разойдётся весть, что именно ты прикончила чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" },
    ["5a"] = { common = "Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за неё хорошо заплачу. Устрой мне пир, и не пожалеешь. Говорят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные тёмные пирожки с крабами..." },
    ["5c"] = { common = "Значит, тебе нужны пирожки с крабами? Что ж, могу испечь..." },
    ["6a"] = { male = "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесёшь мне голову этого негодяя – получишь награду! Но будь осторожен. Гаррик собрал разбойничью шайку. До него непросто будет добраться.", female = "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесёшь мне голову этого негодяя – получишь награду! Но будь осторожна. Гаррик собрал разбойничью шайку. До него непросто будет добраться." },
    ["6c"] = { male = "Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!", female = "Ха! Ты его прикончила! Ты оказала большую услугу Элвину и заслуживаешь хорошей награды!" },
    ["7a"] = { common = "Первое твоё задание, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья." },
    ["7c"] = { common = "Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна. Примите мою благодарность за хорошую работу." },
    ["8a"] = { male = "Эй, приятель! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия! Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и сам сможешь там отдохнуть, если захочешь. По крайней мере, ты должен туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.", female = "Эй, подруга! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия! Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и сама сможешь там отдохнуть, если захочешь. По крайней мере, ты должна туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу." },
    ["8c"] = { common = "Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... Что? Слишком фальшивлю? Не купился? Ну так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! Возвращайся, когда будет что потратить... бродяга. И вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости." },
    ["9a"] = { common = "Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей. Если вы готовы поработать, я попросил бы вас пойти и убить двадцать таких големов. Возвращайтесь за оплатой, когда всё будет сделано. Когда расправитесь с теми, что обитают на моём поле, зачистите поля и моих соседей тоже." },
    ["9c"] = { common = "Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветёт." },
    ["11a"] = { common = "На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов. Армия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов." },
    ["11c"] = { common = "О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность." },
    ["12a"] = { common = "У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путём кровопролития. Один из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалёку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей пятнадцать звероловов и пятнадцать контрабандистов из Братства Справедливости, а затем возвращайся ко мне." },
    ["12c"] = { common = "Отличная работа. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело." },
    ["13a"] = { male = "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света. Золотой карьер находится неподалёку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты убил пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости.", female = "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света. Золотой карьер находится неподалёку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты убила пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." },
    ["13c"] = { common = "Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями." },
    ["14a"] = { common = "Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения." },
    ["14c"] = { common = "Я покинул разорённые земли Лордерона, вернувшись на свою родину... и застал её в столь же ужасном состоянии. Но для Западного Края ещё есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!" },
    ["15a"] = { common = "Мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда. Отправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка десяток, посмотри, сколько ещё осталось, и доложи мне." },
    ["15c"] = { male = "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда. Когда будешь готов, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку...", female = "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда. Когда будешь готова, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку..." },
    ["18a"] = { common = "Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке. Не знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие." },
    ["18c"] = { male = "Ага, вижу, ты вернулся не с пустыми руками. Армия Штормграда ценит твою помощь.", female = "Ага, вижу, ты вернулась не с пустыми руками. Армия Штормграда ценит твою помощь." },
    ["19a"] = { common = "Вестники и отступники из клана Чёрной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил'зун. Он уже натворил достаточно дел. Принеси мне его голову!" },
    ["19c"] = { common = "Тарил'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда." },
    ["20a"] = { common = "К нам явились орки Чёрной Горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озёр, и жители тех земель бежали в город, набились в него, словно сельди в бочку. Помоги Приозерью избавиться от этой угрозы. Перебей орков Чёрной Горы и принеси в доказательство десять иззубренных топоров. Хотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний." },
    ["20c"] = { common = "Что ж, чем меньше орков, тем лучше. Большое тебе спасибо." },
    ["21a"] = { common = "Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. Время дорого. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье." },
    ["21c"] = { male = "Ты снова заслужил мою похвалу и благодарность армии Штормграда. В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения.", female = "Ты снова заслужила мою похвалу и благодарность армии Штормграда. В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения." },
    ["22a"] = { common = "Лук очищен. Чеснок раздавлен. Розмарин измельчён. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Всё, что мне ещё нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!" },
    ["22c"] = { male = "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. Не допускаешь же ты мысли, что герой вроде тебя останется без угощения, а?", female = "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. Не допускаешь же ты мысли, что героиня вроде тебя останется без угощения, а?" },
    ["23a"] = { common = "Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты. На лапе есть маленький знак – месяц. Смысл этого знака покрыт тайной. Эту лапу надо отнести Сенани Громовое Сердце на заставу Расщеплённого Древа, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты." },
    ["23c"] = { male = "О, лапа Топтыжня! Твои навыки меня впечатлили, герой. Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!", female = "О, лапа Топтыжня! Твои навыки меня впечатлили, героиня. Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!" },
    ["24a"] = { common = "Некогда стремительный Тенумбра лежит у ваших ног. Вы победили. Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты. Сенани Громосерд на заставе Расщеплённого Древа захочет увидеть ваш трофей и наградить вас за этот этап охоты." },
    ["24c"] = { common = "Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки. Дикий нрав Тенумбры был хорошо известен на заставе. Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным. Благодаря тебе этой угрозы больше не существует." },
    ["26a"] = { male = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником.", female = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." },
    ["26c"] = { common = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, её надо заслужить. Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." },
    ["27a"] = { male = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником.", female = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." },
    ["27c"] = { common = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, её надо заслужить. Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." },
    ["28a"] = { common = "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны. На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха. Удачи тебе." },
    ["28c"] = { common = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту." },
    ["29a"] = { common = "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны. На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха. Удачи тебе." },
    ["29c"] = { common = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту." },
    ["30a"] = { common = "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика. Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звёзд." },
    ["30c"] = { common = "Ты прошёл испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." },
    ["31a"] = { male = "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс. Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единым с водой. Доброго тебе пути, юный друид. Мы ещё встретимся.", female = "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс. Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единой с водой. Доброго тебе пути, юный друид. Мы ещё встретимся." },
    ["31c"] = { common = "Великолепно. Твои предки могут гордиться твоими успехами! Ты готов прининять водный облик, и я с радостью научу тебя этому. Прими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." },
    ["33a"] = { common = "Ненавижу этих мерзких лесных волков! Но я бы не прочь полакомиться бифштексами из волчатины... Принеси мне жёсткой волчатины, и в обмен я предложу тебе что-нибудь полезное. Убей несколько лесных волков и молодых волков, что водятся в североземских лесах, и принеси мне их мясо." },
    ["33c"] = { male = "Ну, ты на славу постарался! Прямо не терпится поджарить волчатинки... У меня есть кое-что интересное для тебя – выбирай!", female = "Ну, ты на славу постаралась! Прямо не терпится поджарить волчатинки... У меня есть кое-что интересное для тебя – выбирай!" },
    ["34a"] = { common = "Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом. Теперь мне долго не удастся посадить нарциссы. Они загублены! И во всём виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасётся в полях на юго-западе от Озёр, но порой заходит и сюда, в мой сад." },
    ["34c"] = { common = "Наконец-то моему саду ничего не грозит! Спасибо тебе, ты оказал мне большую услугу. Теперь мой сад расцветёт с небывалой пышностью!" },
    ["35a"] = { common = "Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несёт стражу у моста и должен знать, что там происходит на самом деле. Принеси мне его отчёт." },
    ["35c"] = { common = "Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса. Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны." },
    ["36a"] = { common = "Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь. Может быть, ты окажешь мне услугу? Я напишу рецепт похлёбки Западного Края, а ты отнесёшь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги." },
    ["36c"] = { common = "Эта Верна всегда была такой милой девушкой. Нам будет её не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для неё. Ладно, хватит сплетничать! Начнём же готовить похлёбку Западного Края!" },
    ["37a"] = { common = "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчёт, мне нужно выяснить, что с ними случилось. Отправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки." },
    ["37c"] = { common = "Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\"." },
    ["38a"] = { common = "Помоги мне сварить похлёбку Западного Края! Мне нужны для неё следующие ингредиенты: Три куска жилистого мяса стервятника Три рыла жутеклыка Три глаза мурлока Три окры" },
    ["38c"] = { common = "Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла кровоклыка. И вот всё готово! За оказанную помощь, я предлагаю тебе отведать первую порцию похлёбки Западного Края." },
    ["39a"] = { common = "Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками. Я знаю, лишних солдат у нас нет, но, может, Дугхан пришлёт хоть какую-то помощь..." },
    ["39c"] = { common = "Да, вести невесёлые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко. Если положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье..." },
    ["40a"] = { common = "В Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей. Я предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчёт. Я прошу тебя, поговори с Дугханом и постарайся убедить его послать отряд на восток!" },
    ["40c"] = { common = "Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчёты о появлении мурлоков на востоке крайне недостоверны. Я понимаю твою тревогу, но пока не будут получены надёжные сведения о мурлоках, никаких войск на восток я посылать не стану." },
    ["45a"] = { common = "При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков. Возможно, именно здесь и окончил свой путь Рольф..." },
    ["45c"] = { common = "На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\"." },
    ["46a"] = { common = "Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков. Убей их и принеси мне их плавники: армия хорошо за это заплатит. Мурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; ещё одно селение расположено на юге – там, где русло реки разделяется надвое." },
    ["46c"] = { common = "Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса. Он будет рад узнать, что ситуация под контролем. Твоя помощь в этом деле была просто неоценимой." },
    ["47a"] = { common = "Кобольды в этих местах иногда носят с собой Золотую пыль. Достань мне этой пыли, и я дам за неё лучшую цену в городе! Лучшую цену в городе! Кобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой." },
    ["47c"] = { common = "Благодарю за пыль. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится." },
    ["52a"] = { common = "Приветствую. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи. Хочешь нам помочь?" },
    ["52c"] = { common = "Я так тебе благодарен!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас. Что бы там ни было, хотел бы я, чтобы оно не покидало леса..." },
    ["54a"] = { male = "Ты – герой, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса. Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.", female = "Ты – героиня, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса. Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами." },
    ["54c"] = { male = "Что же, тут говорится, что ты был назначен полномочным представителем маршалов Штормграда. Прими мои поздравления. И удачи тебе... Охранять Элвинн - это непростая работа. Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки! В наши мрачные времена политика - дело тёмное...", female = "Что же, тут говорится, что ты была назначена полномочным представителем маршалов Штормграда. Прими мои поздравления. И удачи тебе... Охранять Элвинн - это непростая работа. Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки! В наши мрачные времена политика - дело тёмное..." },
    ["55a"] = { male = "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях… Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию. Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, герой Сумеречного леса.", female = "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях… Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию. Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, героиня Сумеречного леса." },
    ["55c"] = { male = "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему. Ты совершил невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу. Ступай. Быть может, судьба вновь приведёт тебя ко мне...", female = "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему. Ты совершила невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу. Ступай. Быть может, судьба вновь приведёт тебя ко мне..." },
    ["56a"] = { male = "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе. Если ты готов на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!", female = "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе. Если ты готова на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!" },
    ["56c"] = { common = "Великолепно. За верную службу народу Темнолесья тебе полагается награда." },
    ["57a"] = { common = "Я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей пятнадцать скелетов-губителей и пятнадцать ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!" },
    ["57c"] = { common = "Народ Темнолесья благодарит тебя. Ты доказал свою преданность Ночному дозору." },
    ["58a"] = { common = "Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках. У нас не хватает стражей для обеспечения безопасности города. Придётся тебе снова отправиться на Вороний холм и уничтожить двадцать распространителей чумы в восточном мавзолее." },
    ["58c"] = { common = "Я благодарю тебя, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!" },
    ["59a"] = { common = "Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно. Мне хотелось бы надеяться, что новые доспехи помогут тебе, в защите Элвиннского леса от врагов. Лесозаготовки находятся к востоку от сторожевого поста Томаса." },
    ["59c"] = { male = "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен. Желаю удачи, герой! Надеюсь, новый доспех тебе пригодится.", female = "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен. Желаю удачи, героиня! Надеюсь, новый доспех тебе пригодится." },
    ["60a"] = { male = "Приветствую тебя, добрый путник! Не найдётся ли у тебя свободной минутки? Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь? Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?", female = "Приветствую тебя, прекрасная госпожа! Не найдётся ли у тебя свободной минутки? Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь? Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?" },
    ["60c"] = { common = "Ну что, пришлось попотеть? Спасибо за свечи! А вот и твоя награда..." },
    ["61a"] = { common = "В Штормграде мой брат Морган ждёт посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит. Вот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта." },
    ["61c"] = { common = "Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдётся какое-нибудь зелье или безделушка, которые тебе пригодятся..." },
    ["62a"] = { common = "Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды. Нужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчёта. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." },
    ["62c"] = { common = "Скверные вести. И что дальше? Может, драконы?! Похоже, придётся усилить охрану рудника. Спасибо тебе. И подожди, не уходи... возможно, у меня найдётся для тебя ещё одно задание." },
    ["63a"] = { common = "На побережье Серебряного Бора, к западу от Гробницы, находится святилище, осквернённое чумой. Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель. Возьми браслеты элементалей и остатки зелья Брин и помести их в жаровню. Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить. Принеси мне доказательство того, что моё задание выполнено, и в награду я дам тебе тотэм." },
    ["63c"] = { common = "Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин. Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен..." },
    ["64a"] = { common = "Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты её не пропустишь. Если вернёшь мне мои часы, я буду очень признателен!" },
    ["64c"] = { male = "Мои часы! Благодарю тебя, любезный господин! Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности.", female = "Мои часы! Благодарю тебя, любезная госпожа! Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." },
    ["65a"] = { male = "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости. Мне нужно, чтобы ты проник в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан. Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай.", female = "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости. Мне нужно, чтобы ты проникла в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан. Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." },
    ["65c"] = { common = "Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу." },
    ["66a"] = { common = "Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть. Погрузившись в длительный и тяжкий транс, я сумела разгадать эту тёмную тайну. Мне открылось имя: Сталван. Отыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас." },
    ["66c"] = { common = "А, так тебя послала мадам Ева..." },
    ["71a"] = { common = "Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей." },
    ["71c"] = { common = "Увы, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придётся считаться..." },
    ["76a"] = { common = "Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте. Отправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберёшься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту." },
    ["76c"] = { common = "Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут всё хуже и хуже! Конечно, я благодарен тебе за информацию, но лучше бы мы ошибались..." },
    ["83a"] = { common = "В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лён, который мог бы принести мне гораздо большую пользу... и прибыль. Принеси мне красные повязки, а я сделаю из них кое-что полезное для тебя. Лагеря братства разбросаны по всему Элвиннскому лесу." },
    ["83c"] = { common = "Отличные повязки, даром что ткань грубовата... Вот, держи!" },
    ["84a"] = { common = "Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!" },
    ["84c"] = { common = "М-м, вкуснятина! Пирог что надо! Похоже, ко мне возвращается память..." },
    ["85a"] = { common = "Я потеряла ожерелье. Сдаётся мне, его стащил этот беспризорник Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники, это к востоку отсюда. Пожалуйста, разыщи моё ожерелье, порадуй старуху-вдову!" },
    ["85c"] = { common = "Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь! Может, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится." },
    ["86a"] = { common = "Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твоё ожерелье. Кстати... Говорят, у тётушки Бернис получаются отличные пироги со свининой. Я вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог." },
    ["86c"] = { common = "Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!" },
    ["87a"] = { common = "Я играл около рудника Подземных глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Представления не имею, как оно туда попало; я тут ни при чём! В общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике. Если отыщешь этого кобольда, найдёшь и ожерелье, точно тебе говорю!" },
    ["87c"] = { common = "Моё ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо! Вот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил. Если бы только он взял это с собой в последний поход!.." },
    ["88a"] = { common = "У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке – ты только представь себе! – Принцесса. И эта громадная гора сала то и дело пробирается на мой огород! Чтобы пожирать мои овощи! Так вот, прежде чем эта скотина доберётся до полей... словом, Принцесса должна умереть! Принеси мне её ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное. Принцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров. Разберись с ней прежде, чем она проголодается и вернётся сюда!" },
    ["88c"] = { common = "Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна! Взгляни: что-нибудь из этого тебе, надеюсь, подойдёт?" },
    ["89a"] = { common = "Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем. Нам не хватает материалов на ремонт моста. Если ты принесёшь мне пять железных пик и пять железных клепок, я прикажу тебя наградить. За дело!" },
    ["89c"] = { common = "Отличная работа. Мы можем продолжить восстановление моста. Ещё немного, и закончим." },
    ["90a"] = { common = "Моё коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить, но для этого мне понадобятся кое-какие продукты. Раздобудь десять постных волчьих боков. В лесу волков полно, и добыть мясо будет несложно. Кстати, тебе ещё повезло – буквально на днях мне пришёл очередной груз травяных приправ Штормграда, так что от тебя мне понадобится только сама волчатина." },
    ["90c"] = { common = "Отличная работа! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!" },
    ["91a"] = { common = "В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях. Он прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно Закону Озёр, пособничество врагу королевства карается смертью. Гноллов следует уничтожить! Принеси мне десять подвесок Темношкуров и получишь награду." },
    ["91c"] = { common = "Суд Озёр благодарит тебя за помощь правосудию. Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях." },
    ["92a"] = { common = "Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь! Принеси мне пять кусков жёсткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса." },
    ["92c"] = { common = "Молодец. И какие отличные куски! А вот и моё коронное блюдо – гуляш по-красногорски." },
    ["93a"] = { common = "Открою тебе тайну: тёмные пирожки с \"крабами\" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки. Говорят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой." },
    ["93c"] = { common = "О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке… И хотя тёмные пирожки с крабами – моё коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже." },
    ["94a"] = { common = "Мой соперник Моргант – волшебник, наделённый великой силой, но лишённый сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашёл способ следить за ним при помощи Ока Азоры. Однако Око не даёт возможности проникнуть в его мысли. Для такого дела мне потребуется помощь. Если ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней. Если это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта." },
    ["94c"] = { male = "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита: Прими мою благодарность, юный путник. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание.", female = "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита: Прими мою благодарность, юная путница. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." },
    ["95a"] = { common = "Раньше я работал на одной из ферм на юго-востоке... а потом тёмные всадники спустились с перевала Мёртвого Ветра и перебили всю мою семью, пока я был в отлучке! Вернувшись, я увидел неподалёку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал тёмных всадников. Так я и не узнал, что там спрятано. Если ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром." },
    ["95c"] = { common = "Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало." },
    ["96a"] = { common = "Возьми осколок. Возьми его и даруй жизнь. Даруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни. Оберегай и даруй жизнь силой воды." },
    ["96c"] = { common = "А вот и доказательство твоих свершений, как я и просила. Я рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотэм воды. Пусть он служит тебе верой и правдой. Удачи! Следующее испытание ожидает тебя нескоро, поэтому учись хорошенько. Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты. Когда найдёшь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания." },
    ["99a"] = { common = "По мере того, как растёт моё понимание магии Аругала, растёт и моё презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". У меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днём живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунного Гнева. Мне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне шесть заколдованных кандалов из деревни Погребальных Костров." },
    ["99c"] = { common = "Твоя настойчивость весьма похвальна. С помощью информации, которую ты помог мне собрать, Аругал падёт, и вся его безрассудная магия развеется. Браво." },
    ["100a"] = { common = "Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь осквернённые духи вокруг вас уничтожены." },
    ["100c"] = { common = "Спасибо тебе. Спасибо шаманам. Порча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь." },
    ["101a"] = { male = "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите. Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем. Если ты желаешь оградить себя от неё, благородный герой, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда. Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя.", female = "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите. Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем. Если ты желаешь оградить себя от неё, благородная героиня, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда. Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя." },
    ["101c"] = { male = "Ты поступил мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный герой. Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений.", female = "Ты поступил мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный героиня. Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." },
    ["102a"] = { common = "Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя. Твоё задание, если ты за него возьмёшься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мёртвых копей. Принеси мне восемь лап гноллов, и я вознагражу тебя за проявленное мужество." },
    ["102c"] = { common = "Хорошая работа. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то. Пожалуйста, прими эту награду в знак признательности за твои усилия." },
    ["103a"] = { common = "Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вёл нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи. Помогите мне поддержать огонь факела – принесите пять фляг масла, собрав их с сельскохозяйственных големов." },
    ["103c"] = { male = "Хвала тебе, смелый герой. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.", female = "Хвала тебе, смелый героиня. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." },
    ["104a"] = { common = "Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете. Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали. Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним. Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах. Убейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас." },
    ["104c"] = { common = "Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа. Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других. Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию." },
    ["106a"] = { common = "За что мне это наказание? Моё сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу! Пожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда..." },
    ["106c"] = { common = "Я больше не могу жить в разлуке с ней! Я должен увидеть её!" },
    ["107a"] = { common = "Бьюсь об заклад, у Вильяма Песта найдётся зелье, которое поможет соединить наших юных влюблённых! Вот, держи: отнесёшь эту записку Вильяму. Найдёшь его в Златоземье, в таверне \"Гордость льва\"." },
    ["107c"] = { common = "У меня просто сердце разрывается, как подумаю об этих бедных детках, Мейбелл и Томми Джо. Ах, молодость... Весна... Любовь... Думаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать..." },
    ["109a"] = { male = "Похоже, герой, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.", female = "Похоже, героиня, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." },
    ["109c"] = { common = "А, так это мой друг тебя сюда отправил? С его стороны это большая любезность. Что ж... Монархия Штормграда больше не поддерживает нас. Остаётся полагаться на ополчение. Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому." },
    ["111a"] = { common = "Прошу тебя, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она. Бабуля сейчас дома – это к востоку отсюда..." },
    ["111c"] = { common = "Пока наши семьи враждуют, у Томми Джо и Мейбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе. Хм... Что бы придумать..." },
    ["112a"] = { common = "Да, я могу приготовить для Мэйбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус. Эти водоросли растут в океане, и мурлокам иногда удаётся добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдётся нужный компонент. А озеро найти просто: нужно только пойти на восток от Златоземья." },
    ["112c"] = { common = "Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов." },
    ["114a"] = { common = "Отнеси этот напиток невидимости юной Мэйбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо." },
    ["114c"] = { common = "Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми! Благодарю тебя. Как только подвернётся случай, я выпью этот напиток и найду способ пробраться к моему любимому. А в дополнение к словам благодарности прими вот это." },
    ["115a"] = { common = "Орки из клана Чёрной Горы позвали на помощь чародеев, а те принесли с собой источники тёмной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия. Добудь для меня полуночные сферы. Ты найдёшь их у чародеев Чёрной Горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!" },
    ["115c"] = { common = "Благодарю тебя. Я немедленно прикажу уничтожить эту мерзость." },
    ["116a"] = { common = "У меня возникло небольшое затруднение. Ещё немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки. Не хочешь подзаработать? Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу." },
    ["116c"] = { common = "Отличная работа! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков. Завсегдатаи трактира будут счастливы!" },
    ["118a"] = { common = "Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей! Отнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков." },
    ["118c"] = { common = "Так старому Вернеру нужны подковы, да?!" },
    ["119a"] = { common = "Ладно, так и быть, пошлю ему пятьдесят подков… Вот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикреплённую к ящику!" },
    ["119c"] = { male = "Спасибо, ты здорово мне помог. Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь.", female = "Спасибо, ты здорово мне помогла. Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь." },
    ["120a"] = { male = "Тяжёлые настали времена, герой. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!", female = "Тяжёлые настали времена, героиня. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!" },
    ["120c"] = { male = "Вольно, герой. Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию. Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепления, как только получу приказ Его Величества.", female = "Вольно, героиня. Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию. Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепления, как только получу приказ Его Величества." },
    ["121a"] = { male = "Пока я жду ответа от короля, хочу, чтобы ты отнёс это письмо мировому судье Соломону. Свободен, герой!", female = "Пока я жду ответа от короля, хочу, чтобы ты отнесла это письмо мировому судье Соломону. Свободна, героиня!" },
    ["121c"] = { male = "Благодарю тебя, герой. В знак признательности Озёр и Штормграда прими эти деньги. Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны.", female = "Благодарю тебя, героиня. В знак признательности Озёр и Штормграда прими эти деньги. Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны." },
    ["122a"] = { common = "В обмен на подковы Аргус из Златоземья просит брюшную чешую чёрных дракончиков. Если ты добудешь мне шесть лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю. Чёрных дракончиков можно отыскать к югу от Озёр, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю." },
    ["122c"] = { common = "Спасибо! Теперь я смогу расплатиться с Аргусом..." },
    ["123a"] = { common = "На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\". Судя по всему, Вымогатель обосновался неподалёку от тыквенного поля Бреквеллов в восточной части Элвиннского леса. Похоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье." },
    ["123c"] = { common = "Хм... Я слышал об этом \"Собирателе\", вот только не знаю, на кого он работает. Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну..." },
    ["124a"] = { common = "Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей… Если ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны." },
    ["124c"] = { common = "Благодарю тебя за помощь!" },
    ["125a"] = { common = "Мне не помешала бы помощь. Наш город в осаде, и достать припасы и оборудование всё труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили её снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера. Достань его, и я щедро вознагражу тебя." },
    ["125c"] = { common = "Отличная работа! Я уж и не надеялся вновь увидеть свои инструменты." },
    ["126a"] = { common = "Гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь. Стоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу. Соблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост..." },
    ["126c"] = { common = "И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов." },
    ["127a"] = { male = "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу! Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сам не умеешь удить, то... Попытайся отнять рыбу у мурлоков!", female = "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу! Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сама не умеешь удить, то... Попытайся отнять рыбу у мурлоков!" },
    ["127c"] = { common = "Иметь с тобой дело – одно удовольствие, дружище!" },
    ["128a"] = { common = "Мы должны уничтожить клан Чёрной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи. Мировой судья Соломон распорядился перебить этих гнусных тварей. Убей пятнадцать воителей из клана Чёрной Горы и возвращайся ко мне." },
    ["128c"] = { male = "Вижу, ты доблестно сражался с кланом Чёрной Горы, герой. Ты оказал нашему городу неоценимую услугу.", female = "Вижу, ты доблестно сражался с кланом Чёрной Горы, героиня. Ты оказал нашему городу неоценимую услугу." },
    ["129a"] = { common = "Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушёл на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края. Если ты отнесёшь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес." },
    ["129c"] = { common = "Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!" },
    ["130a"] = { common = "Если ты всё равно идёшь к Дарси, не отнесёшь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города. Только когда будешь покупать цветы… не говори травнице Марти, от кого они и кому..." },
    ["130c"] = { male = "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашёл возлюбленную? Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена.", female = "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашла возлюбленного? Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." },
    ["131a"] = { common = "Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!" },
    ["131c"] = { common = "Какая прелесть! Надо поскорее поставить их в воду! Но... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказал, для кого они? Иначе не удивлюсь, если она их отравила. Нет-нет, ты ни в чём не виноват. Большое спасибо! А вот и твой обед." },
    ["132a"] = { common = "То, о чём я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами. Отнеси эту записку Камнегриву. В ней разъясняется всё, что я знаю на эту тему." },
    ["132c"] = { common = "Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа." },
    ["133a"] = { common = "Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!.. Я хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько рёбер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы. Принеси мне рёбра, и я дам тебе несколько монет." },
    ["133c"] = { common = "О, спасибо. Это наверняка сработает!" },
    ["134a"] = { common = "Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами. Прогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалёку от кургана. Прошу тебя, верни мне ящик, без него я как без рук." },
    ["134c"] = { common = "Хвала Нек... то есть ТЕБЕ! Ты более чем заслуживаешь награды. Ага! Как я счастлив! Впереди много радостных ночей!" },
    ["135a"] = { common = "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну. Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе." },
    ["135c"] = { common = "Это дело может оказаться сложнее, чем полагает Камнегрив." },
    ["136a"] = { common = "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что моё сокровище теперь может стать твоим, главное – следуй подсказкам. Сначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдёшь мой сундучок. Загляни внутрь за следующей подсказкой." },
    ["136c"] = { common = "Сундучок медленно, со скрипом, открывается. Кажется, ничего в нём нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!" },
    ["138a"] = { common = "Ключ к поиску сокровища таков: \"Отличная работа, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге. Ищи на обочине дороги развалины старого очага. Там найдёшь старую бочку, в которой и будет следующий ключ\"." },
    ["138c"] = { male = "Отличная работа, охотник за сокровищами!", female = "Отличная работа, охотница за сокровищами!" },
    ["139a"] = { common = "Обыскивая бочку, вы обнаруживаете ещё один кусок пергамента. На нём написано: \"А теперь от этой бочки поверни к северу. Прямо, как ворон летит, иди, пока не наткнёшься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утёсах. Осмотри кувшин внимательно – может, и найдёшь то, что ищешь\"." },
    ["139c"] = { male = "Ты на пути к главному призу, искатель сокровищ!", female = "Ты на пути к главному призу, искательница сокровищ!" },
    ["140a"] = { male = "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашёл мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся! Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!", female = "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашла мой старый кувшин из-под виски, значит, ты близко подобралась к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся! Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!" },
    ["140c"] = { common = "Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище. Поздравляем!" },
    ["141a"] = { common = "Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф. Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны. Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошёлся король, когда восстановление города было завершено. Это могло бы объяснить пару вещей. Я тут расписал всё более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!" },
    ["141c"] = { common = "Эдвин ван Клиф... Мне хорошо известно это имя. Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца. Мне понадобятся дополнительные доказательства, чтобы я поверил в это." },
    ["142a"] = { male = "Нам нужно выяснить местонахождение Убежища Братства Справедливости. путник, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено.", female = "Нам нужно выяснить местонахождение Убежища Братства Справедливости. путница, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." },
    ["142c"] = { common = "Вот явное доказательство того, что ими верховодит ван Клиф. Теперь всё, что нам нужно узнать, – это где прячутся бандиты братства. Нам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена. Он пообещал навести нас на убежище бандитов в обмен на жизнь. Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище. Возвращайтесь ко мне, когда выясните местонахождение убежища." },
    ["143a"] = { common = "Что-то странное происходит в армии Штормграда, подкрепления всё нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном Крае создано народное ополчение. Отнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов." },
    ["143c"] = { male = "Добрый вестник, ты хорошо послужил своему господину.", female = "Добрая вестница, ты хорошо послужила своему господину." },
    ["144a"] = { male = "Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы. Отнеси мой ответ в Красногорье, герой, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.", female = "Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы. Отнеси мой ответ в Красногорье, героиня, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." },
    ["144c"] = { male = "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух. Вот, вестник. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься.", female = "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух. Вот, вестница. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься." },
    ["145a"] = { common = "И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озёр. Надо как можно скорее доставить моё послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги." },
    ["145c"] = { common = "Благодарю за проделанный путь. Вести и верно важные." },
    ["146a"] = { common = "Не знай я мирового судью Соломона лично, решил бы, что он сошёл с ума. Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной дозор, то наш город падёт, едва лишь Дозор доберётся до края леса. Отнеси мой ответ своему господину в Приозерье." },
    ["146c"] = { male = "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так? О, я забыл отблагодарить тебя за услуги, герой. Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути.", female = "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так? О, я забыл отблагодарить тебя за услуги, героиня. Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути." },
    ["147a"] = { common = "Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель... Здесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там." },
    ["147c"] = { common = "Так тебе удалось его найти? Отлично, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах! А это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда. С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках? Непростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ." },
    ["148a"] = { male = "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели. Не мог бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Её можно приобрести у мадам Евы, которая живёт на центральной площади города.", female = "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели. Не могла бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Её можно приобрести у мадам Евы, которая живёт на центральной площади города." },
    ["148c"] = { common = "А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать ещё... Если ты принесёшь мне призрачные волосы." },
    ["149a"] = { male = "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри. Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити. Будь осторожен, рядом с домом бродит множество тёмных тварей.", female = "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри. Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити. Будь осторожна, рядом с домом бродит множество тёмных тварей." },
    ["149c"] = { common = "Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун. Ах, мне бы в зеркало посмотреться..." },
    ["150a"] = { common = "Мурлоки начинают нас беспокоить. Всё больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили всё озеро! Убей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить..." },
    ["150c"] = { common = "Молодец. Надеюсь, тебе не слишком солоно пришлось. Странно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали..." },
    ["151a"] = { male = "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, сэр, если бы вы могли принести ей несколько горстей овса с окрестных полей. Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.", female = "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, леди, если бы вы могли принести ей несколько горстей овса с окрестных полей. Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств." },
    ["151c"] = { common = "Огромное тебе спасибо! Бедная старая Савраска будет просто счастлива!" },
    ["152a"] = { male = "Ты, должно быть, видел все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой... Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя.", female = "Ты, должно быть, видела все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой... Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." },
    ["152c"] = { common = "Хорошая работа. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом." },
    ["153a"] = { common = "В Братстве Справедливости идёт постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам. Принесите мне пятнадцать таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение." },
    ["153c"] = { common = "Хорошая работа. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды." },
    ["154a"] = { common = "НЕТ!!! Убери его, убери от меня этот гребень! Я чудовище, меня больше никто не назовёт прекрасной!" },
    ["154c"] = { common = "Ну, из этого выйдет целая катушка нити из призрачных волос, да ещё и останется несколько прядей. Прими эти монеты в уплату за лишние пряди." },
    ["155a"] = { male = "Так Камнегрив считает, что такой слабый путник сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей. Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить. Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти.", female = "Так Камнегрив считает, что такая слабая путница сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей. Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить. Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." },
    ["155c"] = { male = "Великолепно, сэр путник! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!", female = "Великолепно, сэр путница! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" },
    ["156a"] = { common = "Если ты принесёшь мне несколько цветков гнили, я сделаю для тебя сок зомби. Цветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал! Кладбище Вороньего холма и Безмятежное кладбище кишмя кишат этими скелетами. Заодно ты и нас от них избавишь. Темнолесье будет тебе весьма признательно." },
    ["156c"] = { male = "Отлично, ты сумел добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов. Ночной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех.", female = "Отлично, ты сумела добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов. Ночной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." },
    ["157a"] = { common = "Вот тебе нитки. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы." },
    ["157c"] = { male = "Великолепно! Она прекрасно подойдёт… Вот, дражайший путник, прими это в уплату за благороднейший поступок.", female = "Великолепно! Она прекрасно подойдёт… Вот, дражайший путница, прими это в уплату за благороднейший поступок." },
    ["158a"] = { common = "Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдётся лишняя бутылочка. Торопись. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнём." },
    ["158c"] = { common = "Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают." },
    ["159a"] = { male = "А вот и сок зомби… Будь с ним осторожен. Он такой крепкий, что мёртвого поднимет!", female = "А вот и сок зомби… Будь с ним осторожна. Он такой крепкий, что мёртвого поднимет!" },
    ["159c"] = { common = "Тысяча благодарностей. Твоя глу... то есть твоя доброта согрела сердце старика! Вот, друг, прими это в знак моей благодарности." },
    ["160a"] = { male = "Отнеси эту записку Элло Чернодреву, мэру Темнолесья. Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделал... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!", female = "Отнеси эту записку Элло Чернодреву, мэру Темнолесья. Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделала... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!" },
    ["160c"] = { common = "*Элло рассматривает письмо...* Что это за язык? Похоже, какой-то древний... Не могу его прочитать." },
    ["161a"] = { common = "Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелёгкий и опасный. Пройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться." },
    ["161c"] = { common = "Да, старина Плотина не зря беспокоится." },
    ["163a"] = { common = "Что-то неладно на Вороньем холме. Калор клянётся, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон. Если тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме." },
    ["163c"] = { common = "Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет... не может быть. Всего лишь безвредный Трясунчик." },
    ["164a"] = { common = "Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса. Увы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?" },
    ["164c"] = { common = "Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды." },
    ["165a"] = { common = "Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живёт в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?" },
    ["165c"] = { common = "Илана Карвин? Хе-хе, да, разумеется, Карвин. Нет, со мной всё в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею. Может, ты окажешь старику пару услуг?" },
    ["166a"] = { common = "Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено." },
    ["166c"] = { common = "Вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края. Смерть Эдвина ван Клифа станет началом конца для Братства Справедливости. Надеюсь, недалёк тот прекрасный день, когда мир вновь снизойдёт на эту честную землю." },
    ["167a"] = { common = "Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю. Вдруг тебе повезёт больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги Исследователей. Если ты не найдёшь брата, постарайся найти хотя бы его значок." },
    ["167c"] = { common = "Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определённость лучше загадок, даже если она лишает надежды." },
    ["168a"] = { common = "Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесёт в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдёшь их карточки Союза шахтёров, принеси их мне, я отправлю их семьям погибших." },
    ["168c"] = { common = "Спасибо тебе. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны." },
    ["169a"] = { common = "Розыск! Гат'Илзогг, вождь клана Чёрной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. Гат'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат'Илзогга мировому судье Соломону, будет щедро вознаграждён." },
    ["169c"] = { common = "Великолепная работа! Гат'Илзогг вёл своих громил в бой, и они убивали ни в чём не повинных людей. Мы отомстили ему. Это первый шаг на пути возвращения крепости королевству Штормграда!" },
    ["170a"] = { male = "Надеюсь, ты оказался здесь не случайно, герой. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес. Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замёрзшего озера. Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его! Нам и так воинов не хватает, а тут ещё эти гады... Послушай, приятель, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть...", female = "Надеюсь, ты оказалась здесь не случайно, героиня. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес. Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замёрзшего озера. Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его! Нам и так воинов не хватает, а тут ещё эти гады... Послушай, подруга, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть..." },
    ["170c"] = { common = "Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждёт большая беда! Остаётся надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец." },
    ["172a"] = { common = "Ты хочешь помочь сиротам? Да благословят тебя боги! Твоя помощь во время Детской недели будет очень кстати! Вот, возьми эту свистульку. Действовать она будет недолго – до конца Детской недели. Свистни в неё – и появится сирота, за которым ты обещаешь присматривать. Свистни ещё раз – ребёнок уйдёт. Прошу тебя, пользуйся свистулькой почаще, не забывай своего подопечного! Для детей это так важно..." },
    ["172c"] = { male = "Заг-заг! Меня зовут Грент. Ты теперь мой опекун, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться! А мы теперь будем всё делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старший брат. Вот здорово!", female = "Заг-заг! Меня зовут Грент. Ты теперь моя опекунша, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться! А мы теперь будем всё делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старшая сестра. Вот здорово!" },
    ["174a"] = { common = "Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звёзды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство. Принеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один." },
    ["174c"] = { common = "Великолепно! Первый шаг мы сделали успешно!" },
    ["175a"] = { common = "Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь её и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса." },
    ["175c"] = { common = "Всё верно, у меня некогда было зеркальце." },
    ["176a"] = { common = "Разыскивается: Дробитель В юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось. Армия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить её, необходимо представить маршалу Дугхану доказательства смерти Дробителя." },
    ["176c"] = { common = "Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем! Вот твоя награда, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!" },
    ["177a"] = { common = "Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил моё зеркальце. Говорят, что теперь эта тварь живёт на Безмятежном кладбище." },
    ["177c"] = { common = "Шедеврально! Это непременно сработает. Я глубоко признателен!" },
    ["178a"] = { common = "*До вас доносится бесплотный голос...* Не пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом. Я потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь моё сообщение, значит заклинание сработало. Принеси мне эту подвеску, и я щедро вознагражу тебя." },
    ["178c"] = { common = "Благодарю тебя. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало. Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них. Хочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески. К сожалению, до этого ещё очень далеко." },
    ["179a"] = { common = "Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя всё время мёрзнут руки. Ну, угадал? Я скажу, что тебе нужно: пара хороших тёплых перчаток. Ну да, душа у меня добрая, так что замёрзнуть я тебе не дам. Только вот есть одно условие. Принеси мне волчьего мяса – и мы, считай, в расчёте. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мёрзли. Ну, что скажешь?" },
    ["179c"] = { common = "О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, свою часть сделки я выполню честно. Вот, посмотри, что из этого тебе подойдёт." },
    ["180a"] = { common = "Разыскивается: лейтенант Фангор Глава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведёт приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону." },
    ["180c"] = { male = "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрый герой. Городской совет Приозерья благодарит тебя за помощь.", female = "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрая героиня. Городской совет Приозерья благодарит тебя за помощь." },
    ["181a"] = { common = "Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать. В кургане на юге Сумеречного леса живёт огр по имени Ззарк'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!" },
    ["181c"] = { common = "Наконец-то! Устройство для изучения звёзд готово! Спасибо тебе. Я могу продолжить исследования..." },
    ["182a"] = { common = "Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьёзна эта угроза. Совету хватает хлопот с троггами, лишние проблемы им ни к чему. Насколько я видел, тролли здесь не слишком хорошо закрепились; в основном они живут в южной пещере. Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся. Может, и ты решишь поучаствовать в этом деле? Не за так, конечно: у меня есть что тебе предложить." },
    ["182c"] = { common = "Проклятые тролли! Да не озарит их Извечный Свет! Шумно дышит; немного успокаивается. Эти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь..." },
    ["183a"] = { common = "Нет ничего лучше охоты на диких вепрей, верно? Правда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно... Короче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов." },
    ["183c"] = { common = "Отлично, просто отлично! Теперь я могу спокойно отдох... М-м... Заняться охотой. Благодарю за помощь." },
    ["184a"] = { common = "Вот бумага, дающая право на расширение фермерских владений в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров. На обороте документа торопливо нацарапаны слова: \"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится. С Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\" Наверное, Хмуробровы были бы рады получить этот документ назад..." },
    ["184c"] = { common = "Ты представить не можешь, как мы тебе благодарны! Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землёй. Конечно, многого я предложить не могу, но возьми хотя бы вот это..." },
    ["199a"] = { common = "Вы берёте образец странно пахнущего порошка." },
    ["199c"] = { common = "Это тревожная находка, мягко говоря!" },
    ["214a"] = { common = "Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства. Я рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справитесь с заданием, принесите мне десять красных шёлковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи." },
    ["214c"] = { male = "Отличная работа путник! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу.", female = "Отличная работа путница! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу." },
    ["216a"] = { common = "Эти фурболги Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщеплённого Древа. Это на дороге, что идёт в обход деревни Астранаар. Если мы не будем её контролировать, Альянс получит дополнительный путь для вторжения. Мы должны заткнуть эту дыру! Иди в деревню Колючего Меха да устрой фурболгам прореживание. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!" },
    ["216c"] = { male = "Отлично, герой, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом! Ты заслужил свою награду, герой! Честь и слава тебе!", female = "Отлично, героиня, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом! Ты заслужил свою награду, герой! Честь и слава тебе!" },
    ["217a"] = { male = "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят. Если ты уверен в своих силах, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю.", female = "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят. Если ты уверена в своих силах, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." },
    ["217c"] = { male = "Превосходно! Ты вернул надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель.", female = "Превосходно! Ты вернула надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." },
    ["218a"] = { common = "Мои записи! Они уволокли в свою мерзкую пещеру мои записи! Здоровенный громила, весь разрисованный с головы до ног... Жаль, я не смог разглядеть его получше! Послушай, тебе ведь уже приходилось иметь дело с троллями? Может, ты сумеешь вернуть мои драгоценные записи?.." },
    ["218c"] = { common = "Великолепно! Словами не передать, как я благодарен! Мои записи, наконец-то!.. Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем. Кстати, послушай: я скоро закончу своё донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?" },
    ["219a"] = { common = "Наконец-то, сторонники Альянса! Помогите... Пожалуйста... Последнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен. Мне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда..." },
    ["219c"] = { male = "Ты отлично послужил Королевству, герой. Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды.", female = "Ты отлично послужил Королевству, героиня. Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды." },
    ["220a"] = { common = "Прежде чем дать тебе в награду следующий тотэм, Ислен поручит тебе ещё одно задание. Для этого понадобится фиал с водой, который я дал тебе. Ступай, поговори с ней. Мы ещё встретимся." },
    ["220c"] = { common = "А, фиал с водой, созданной и благословлённой Брин и добытой тобой, ни больше ни меньше. Жидкость в этом фиале необходима для создания сапты, но годится и для других целей. При помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода. Что же до оставшихся капель... о них я расскажу тебе потом. Не боишься долгого пути?" },
    ["224a"] = { male = "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов! Нам нужна твоя помощь, отважный искатель приключений. Ступай и устрани нависшую над нами угрозу. Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся.", female = "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов! Нам нужна твоя помощь, отважная искательница приключений. Ступай и устрани нависшую над нами угрозу. Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." },
    ["224c"] = { male = "Молодчина! Ты проявил немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужил королю Магни. Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне.", female = "Молодчина! Ты проявила немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужила королю Магни. Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне." },
    ["226a"] = { common = "Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант. Мы здесь совсем одни, приходится самим добывать себе еду. Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязывываются лютые волки. Что и говорить, жить здесь опасно! Но если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки." },
    ["226c"] = { male = "О, хорошо. Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном. Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию.", female = "О, хорошо. Ты здорово проредила волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном. Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию." },
    ["230a"] = { common = "Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью. На ней нет заглавия, зато в ней содержатся сведения, необходимые Свену." },
    ["230c"] = { common = "Свен прочитывает несколько страниц и захлопывает книгу. Этот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!" },
    ["233a"] = { male = "Не думаю, что ты горишь желанием мне помочь, парень, но у меня тут целая куча писем, а времени на доставку нет. Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда. Ну что, может, доставишь ему почту?", female = "Не думаю, что ты горишь желанием мне помочь, красотка, но у меня тут целая куча писем, а времени на доставку нет. Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда. Ну что, может, доставишь ему почту?" },
    ["233c"] = { common = "Благодарю тебя, я уже давно ждал этих писем... Конечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалёку живёт, может, зайдёшь к нему?" },
    ["234a"] = { common = "Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда. Не сомневаюсь, он будет рад этому посланию." },
    ["234c"] = { common = "Как здорово! Я уже давно не получал весточки из Стальгорна. Письма моей матушки всегда согревают мне душу. Кстати, и тебе не помешало бы почитать что-нибудь дельное. Вон, возьми любое руководство, которых у нас тут навалом." },
    ["235a"] = { common = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса! Орде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей. Она ждёт желающих принять участие в большой охоте!" },
    ["235c"] = { male = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", female = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." },
    ["237a"] = { male = "Горный пехотинец Кремневик превозносит тебя до небес, путник. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны. Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.", female = "Горный пехотинец Кремневик превозносит тебя до небес, путница. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны. Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся." },
    ["237c"] = { male = "Ты прекрасно справился с заданием, герой! Сам король может гордиться тобой. К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу. Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужен нам как никогда.", female = "Ты прекрасно справилась с заданием, героиня! Сам король может гордиться тобой. К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу. Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужна нам как никогда." },
    ["239a"] = { common = "Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей! Твоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья. Рейнер скажет тебе, что делать. Гарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдёшь через речушку по мосту, сверни направо." },
    ["239c"] = { common = "Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю. У нас тут сложилась, скажем так, напряжённая ситуация. Надеюсь, ты сумеешь нам помочь." },
    ["240a"] = { common = "А вот и пирожки с \"крабами\" а-ля Груал!" },
    ["240c"] = { common = "Ага! Спасибо. Как раз то, что нужно. А вот и твоя плата за услугу!" },
    ["244a"] = { male = "Привет тебе, герой. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов. В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесённые вести. Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье.", female = "Привет тебе, героиня. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов. В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесённые вести. Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье." },
    ["244c"] = { common = "К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель. И тогда не только Приозерье окажется в осаде! Возьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе." },
    ["245a"] = { male = "Привет тебе, герой. Наверное, ты видел пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья. Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов. Мой тебе совет: остерегайся их яда.", female = "Привет тебе, героиня. Наверное, ты видела пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья. Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов. Мой тебе совет: остерегайся их яда." },
    ["245c"] = { male = "А! Ты вернулся. И на первый взгляд – в целости и сохранности. Разумеется, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание своё выполняю. Держи.", female = "А! Ты вернулась. И на первый взгляд – в целости и сохранности. Разумеется, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание своё выполняю. Держи." },
    ["246a"] = { common = "У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать. Поищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги. Сделай это ради армии Штормграда, и получишь награду." },
    ["246c"] = { common = "Заместитель судьи Фелдон слушает ваш отчёт. Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения. Что ж, мы благодарим тебя за помощь. Если ты ещё не беседовал с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним. Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." },
    ["248a"] = { common = "Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны. Возьми ещё один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью. Отыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдёт сундук или кувшин." },
    ["248c"] = { common = "Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи." },
    ["249a"] = { male = "Ценой долгих усилий я раскрыл планы Морганта. Он ищет Косу Элуны... и быть может, уже отыскал её! Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь. Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должен войти в башню Илгалара и бросить ему вызов. Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.", female = "Ценой долгих усилий я раскрыл планы Морганта. Он ищет Косу Элуны... и быть может, уже отыскал её! Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь. Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должна войти в башню Илгалара и бросить ему вызов. Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." },
    ["249c"] = { common = "Ты сделал великое дело. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности. Смиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена. Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." },
    ["250a"] = { male = "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора. Потому-то ты мне и нужен. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы. Разведай обстановку и возвращайся с уликами.", female = "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора. Потому-то ты мне и нужна. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы. Разведай обстановку и возвращайся с уликами." },
    ["250c"] = { common = "В подозрительной бочке содержится странно пахнущий порошок." },
    ["251a"] = { common = "Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он." },
    ["251c"] = { common = "Шира принимается за перевод записки..." },
    ["252a"] = { common = "О небо! Если то, о чём сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое. Отнеси-ка переведённую записку Элло. И поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу..." },
    ["252c"] = { male = "*Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд.* Хотя ты помогал Аберкромби по доброте душевной, именно ты обрёк наш город на гибель. *Элло погружается в раздумья...*", female = "*Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд.* Хотя ты помогала Аберкромби по доброте душевной, именно ты обрекла наш город на гибель. *Элло погружается в раздумья...*" },
    ["253a"] = { common = "Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть её к жизни, он прибег к тёмной магии и даже вложил в грудь мёртвой супруги собственное сердце. Это оживило Элизу... но её сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать её обратно. Всё его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из неё сердце и принеси его мне, пока оно бьётся. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет." },
    ["253c"] = { male = "Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью. Ты совершил подвиг во имя нашего народа. Мы тебя не забудем.", female = "Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью. Ты совершила подвиг во имя нашего народа. Мы тебя не забудем." },
    ["255a"] = { male = "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности. Похоже, у меня нет выбора. Придётся искать наёмников. Как насчёт тебя? На первый взгляд ты подходишь, герой. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?", female = "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности. Похоже, у меня нет выбора. Придётся искать наёмников. Как насчёт тебя? На первый взгляд ты подходишь, героиня. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?" },
    ["255c"] = { common = "Прекрасные новости! Я и народ Телcамара глубоко признательны тебе. Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами." },
    ["256a"] = { common = "По приказу магистрата Телcамара: Чок-сул, обвиняемый в организации нападений на город Телcамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов. Вознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок-сула. В последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан." },
    ["256c"] = { male = "Ой! Что это? И зачем ты притащил её… Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телcамара достаются тебе по праву!", female = "Ой! Что это? И зачем ты притащила её… Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телcамара достаются тебе по праву!" },
    ["257a"] = { common = "Думаешь тягаться с Дэрилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду. Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет. Неподалёку от озера Лок Модан свила гнёзда стая канюков. Почему бы не подстрелить несколько тварей? Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружьё. *Он с презрением осматривает вас.* Всё равно тебе нечего терять." },
    ["257c"] = { common = "Что? Получилось?! Послушай добрый совет, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренёк с луком справился бы с такими... небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом. Что ж, э-э-э... Пусть не говорят, что Дерил Смелый не держит своё слово." },
    ["258a"] = { male = "путник Батькович, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко. А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут. Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься! Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад...", female = "путница Батьковна, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко. А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут. Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься! Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад..." },
    ["258c"] = { male = "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да? Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело. О! Ты умудрился убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?", female = "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да? Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело. О! Ты умудрилась убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?" },
    ["262a"] = { male = "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья! Прошу тебя, помоги мне. Ты не раз творил настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны! Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознаёт её, и мы выясним имя владельца?", female = "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья! Прошу тебя, помоги мне. Ты не раз творила настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны! Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознаёт её, и мы выясним имя владельца?" },
    ["262c"] = { common = "Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести. Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы. Я могу сказать одно: он не из Темнолесья." },
    ["263a"] = { male = "Горные пехотинцы уверяют, что ты силён и отважен. Нам нужен путник вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас появился закалённый в боях герой, то может быть, нам удастся выстоять. Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов.", female = "Горные пехотинцы уверяют, что ты сильна и отважна. Нам нужна путница вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас появилась закалённая в боях героиня, то может быть, нам удастся выстоять. Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." },
    ["263c"] = { male = "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужил королю Магни. Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе.", female = "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужила королю Магни. Теперь, доказав, что ты верная защитница Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе." },
    ["264a"] = { common = "Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\" А как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чёртового долга! И посмотрите, теперь на плоды борьбы за \"справедливость\"! Он мёртв, а на меня обрушилось всё то, чему он пытался помешать! Возьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!" },
    ["264c"] = { common = "Вы кладёте дешёвую безделушку на могилу, и драгоценный камень в ней заметно тускнеет. Когда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мёртвая, в руках вырезанного на надгробной плите изображения. Ваши мысли прерывает порыв холодного ветра, пронёсшегося по Гробнице. На мгновение всё вокруг вас замирает." },
    ["265a"] = { common = "Вот твоя книга, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное. Я же скажу одно: хотя автор этой книги не из нашего города, тетрадь для неё он купил здесь." },
    ["265c"] = { common = "Ах, да. Я продал эту тетрадь одному сомнительному типу. Он не представился, но явно нервничал, дёргался, то и дело оглядывался через плечо. Надеюсь, что смог тебе помочь..." },
    ["266a"] = { common = "Вот твоя книга, желаю удачи в расследовании. Советую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел." },
    ["266c"] = { common = "Ах да, эту книгу я помню. Её владелец снимал комнату на несколько дней и вечерами засиживался в баре, всё писал. Город он покинул в спешке, бормоча под нос, что его преследует... что-то. В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие. Первое, что ему встретится на западе, – это Вороний холм..." },
    ["267a"] = { male = "герой, не знаю, слышал ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов. И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений восемь каменных зубов троггов.", female = "героиня, не знаю, слышала ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов. И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений восемь каменных зубов троггов." },
    ["267c"] = { male = "Отличная работа. Ты оказал всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!", female = "Отличная работа. Ты оказала всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!" },
    ["268a"] = { common = "Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить её на ферме Свена во время поспешного бегства… Вот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме. Хотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!" },
    ["268c"] = { common = "Записи многое проясняют. Теперь мне ясно, что следует искать тёмных всадников! Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы." },
    ["269a"] = { common = "Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну. Хоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас. Тебя ждёт много опасностей... Однако поспеши. С каждым часом в Сумеречном лесу сгущается тьма." },
    ["269c"] = { common = "*Епископ изучает записи...* Зло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя. Но прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться... Некромант Морбент Скверн всегда был необычайно силён, а чтобы стать неуязвимым, наложил на себя могучие чары. Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды." },
    ["270a"] = { common = "Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна. Одно из судов было нагружено светлой сталью. Этот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится. Отправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз ещё можно найти – он сообразит, где нужно искать." },
    ["270c"] = { male = "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких. Ты проделал длинный путь, братишка. Если тебе сильно повезёт, ты можешь найти то, что ищешь. А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь.", female = "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких. Ты проделала длинный путь, сестрёнка. Если тебе сильно повезёт, ты можешь найти то, что ищешь. А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." },
    ["271a"] = { common = "Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет. Год назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да ещё и получил этот уродливый шрам над глазом. Убей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи. Старину Черношкура можно отыскать в логове в холмах над Телcамаром." },
    ["271c"] = { common = "Э... что это? Судя по всему, медвежья голова. Он невольно проводит пальцем по старому шраму. Что ж, интересная добыча. Не тот ли самый медведь... Он умолкает и начинает заметно дрожать. О, скорее убери её! Убери отсюда эту страшную штуку!" },
    ["272a"] = { common = "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика. Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звёзд." },
    ["272c"] = { male = "Ты прошёл испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.", female = "Ты прошла испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." },
    ["273a"] = { common = "Ещё не поздно, ты можешь поискать Хальдора. Вряд ли он ушёл далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро. Они пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера. Найти их будет несложно, если они ещё не добрались до места назначения." },
    ["273c"] = { common = "Хм, жалкой засаде Чёрного Железа не помешать мне доставить товар! Но Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил. Ладно, подумаю об этом позже." },
    ["274a"] = { common = "Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах! Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн! Химическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толчёный кристалл Могроша, слезу кроколиска и нейтрализующий коллоид. Расскажи об этом Плотине, пока не поздно!" },
    ["274c"] = { common = "Нейтрализующий коллоид? Для сефория? О небо!" },
    ["275a"] = { common = "Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить её, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли. Ползуны водятся у водоёмов в Болотине." },
    ["275c"] = { common = "Скоро раны на теле земли затянутся, и лихорадка спадёт. Я благодарю тебя и вручаю небольшой подарок..." },
    ["276a"] = { common = "Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова! Чтобы спасти природу нашего края, придётся истребить часть гноллов. Убей пятнадцать гноллов из стаи Мохошкуров и десять полукровок из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне." },
    ["276c"] = { male = "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, путник, заставил меня задуматься. Спасибо тебе!", female = "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, путница, заставил меня задуматься. Спасибо тебе!" },
    ["277a"] = { common = "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю! Отбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров." },
    ["277c"] = { common = "Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть." },
    ["278a"] = { common = "Немедленно принимайся за сбор материалов для нейтрализации взрывчатки. Паучий яд ты найдёшь у пауков у озера Лок Модан. Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко. Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто. Мы должны разминировать творение Чёрного Железа! Как только соберёшь все материалы, сразу же возвращайся, и я подготовлю состав." },
    ["278c"] = { common = "Наконец-то!" },
    ["279a"] = { common = "Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить. Один из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и все – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмётся их защищать. Жрун промышляет в речном заливе к северу отсюда. Принеси мне его голову, а заодно перебей его сородичей." },
    ["279c"] = { male = "Отлично! Вот твои деньги, ты честно их заработал, выполнив все обязательства.", female = "Отлично! Вот твои деньги, ты честно их заработала, выполнив всё обязательства." },
    ["280a"] = { common = "Я только сегодня видел мятежников Чёрного Железа, которые тащили к Дамбе большую бочку. И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил! Боюсь, они заложили сефорий у основания Дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты. Вот, у меня получилась нейтрализующая смесь. Скорее, возьми смесь и залей её в бочку, пока не поздно. Торопись!" },
    ["280c"] = { common = "Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение." },
    ["281a"] = { common = "Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\". Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила. Её надо вернуть во что бы то ни стало. Обыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – всё, что может быть связано с украденным грузом. Найди статуэтку Менетила и верни её мне." },
    ["281c"] = { common = "Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома. Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому... ...и находите несколько бутылок из красного стекла." },
    ["282a"] = { common = "Я собирался послать своего ученика к брату Сениру с отчётом, но парень он не слишком надёжный, а мне нужен кто-то, на кого действительно можно положиться. Ну, то есть, конечно, если ты не будешь возражать. Хм-м. Чтобы добраться до Караноса, тебе придётся пройти по тоннелю. Перед тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов. Сначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток. Рядом с тоннелем Талос и стоит – найти его будет несложно." },
    ["282c"] = { common = "Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно? С другой стороны, пару советов-то я могу тебе дать..." },
    ["283a"] = { common = "Бочка негромко шипит." },
    ["283c"] = { male = "Огромное спасибо! Ты спас Каменную дамбу. Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважный герой! Дамба снова в безопасности... по крайней мере, пока...", female = "Огромное спасибо! Ты спасла Каменную дамбу. Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважная героиня! Дамба снова в безопасности... по крайней мере, пока..." },
    ["284a"] = { common = "Вы обыскиваете всё поселение мурлоков в этом районе, но статуэтки Менетила здесь нет. Может быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?" },
    ["284c"] = { common = "Эту бочку, похоже, никто не трогал. Вы открываете её... Запах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!" },
    ["285a"] = { common = "Вы обыскиваете ещё несколько жилищ мурлоков. Вот досада – опять ничего! ...Но вы уверены, что всё получится. Статуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу." },
    ["285c"] = { common = "Бочка наполовину утоплена в грязи и мокрой траве..." },
    ["286a"] = { common = "Вы достаёте бочку из грязи, открываете её и видите серебряную статуэтку, укрытую соломой. Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом. Это, должно быть, и есть статуэтка Менетилова! Теперь вам надо вернуть её Карлу Борану в Гавань Менетилов." },
    ["286c"] = { male = "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужил нам хорошую службу и получишь обещанную награду. Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время.", female = "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужила нам хорошую службу и получишь обещанную награду. Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." },
    ["287a"] = { common = "Я не успеваю с донесением, и твоя помощь, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда. Вот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне. Отправляйся из Караноса по северной дороге. Когда перейдёшь через мост, следуй на запад по замёрзшей реке, пока не доберёшься до Заледеневшего озера. На западном берегу обнаружишь Посёлок Пивоваров. Форт Мерзлогривов находится к юго-западу от него." },
    ["287c"] = { common = "А! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно чётки... Дай-ка мне закончить донесение. Он приносит бумагу и что-то быстро на ней пишет. Вот! Ха-ха, теперь это совсем забавно... Думаю, ты не откажешься помочь мне ещё разок?" },
    ["288a"] = { common = "Когда-то я был первым помощником на \"Владычице\", линейном корабле кул-тирасской Третьей флотилии. Обречённой флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки! У нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре. Ох, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу." },
    ["288c"] = { male = "Вот! И голова не болит, и язык развязался. Спасибо, приятель!", female = "Вот! И голова не болит, и язык развязался. Спасибо, подруга!" },
    ["291a"] = { male = "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд. Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы. Кстати, будь добр, не говори о том, как ты мне помогал. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.", female = "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд. Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы. Кстати, будь добра, не говори о том, как ты мне помогала. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." },
    ["291c"] = { common = "Он быстро просматривает донесение. По приказу КОРОЛЯ!? Магни совсем спятил! И ещё этот проклятый Белобород... Значит, взял дела в свои руки? Сенат этому не обрадуется, вовсе не обрадуется. Что, ты ещё здесь? Иди отсюда, пока я охрану не вызвал!" },
    ["294a"] = { common = "Придётся признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а я, Меррин и бедолага геолог оказались в ловушке здесь, наверху. Помоги очистить Болотину от ящеров. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утёса. Убей по десять тварей каждого вида. Это будет началом моей мести." },
    ["294c"] = { common = "Я понимаю, что убийство – грязная и опасная работа. Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой." },
    ["297a"] = { common = "Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков! Отбей идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдёшь у троггов – а их в раскопе более чем достаточно." },
    ["297c"] = { male = "Ты добыл их! Хвалю! И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды.", female = "Ты добыла их! Хвалю! И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадала. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды." },
    ["298a"] = { common = "Мне нужно отправить в Телcамар отчёт о ходе работ и запрос на получение нового груза пороха! Вот мой отчёт. Отнеси его Джерну Шлеморогу, он наш представитель в Телcамаре. Задание не сложное, но достаточно важное." },
    ["298c"] = { common = "Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями... Так или иначе, он будет потрачен не зря! Но вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся." },
    ["299a"] = { male = "Перед самым вторжением я обнаружил табличку с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырёх местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\". Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молод и полон сил. Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!", female = "Перед самым вторжением я обнаружил табличку с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырёх местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\". Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молода и полна сил. Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" },
    ["299c"] = { male = "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудился. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены.", female = "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудилась. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены." },
    ["301a"] = { common = "Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придётся отнести его отчёт в штаб-квартиру Лиги Исследователей. Вот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ. Грозовую Вершину можно найти в Зале исследователей." },
    ["301c"] = { common = "Проклятый Железняк! Я послал ему целый воз пороха ещё неделю назад, но он не потрудился упомянуть об этом в отчёте. Так... куда делся порох?!?" },
    ["302a"] = { male = "Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута. И ещё одно: я хочу, чтобы ты лично проследил за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.", female = "Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута. И ещё одно: я хочу, чтобы ты лично проследила за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." },
    ["302c"] = { male = "Что? Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку? Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно.", female = "Что? Грозовая Вершина хочет, чтобы ты лично проследила за доставкой груза к Железняку? Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно." },
    ["305a"] = { common = "Знаешь... как-то мне неспокойно на сердце. Моя благоверная Меррин работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось! Длинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлёт мне разведчика, который проверит, что стало с экспедицией. Как я понимаю, ты и есть этот разведчик. Разыщи Меррин на раскопе к востоку отсюда!" },
    ["305c"] = { common = "Слава богам, ты нас нашёл!" },
    ["307a"] = { common = "Рудник у Серебряного ручейка давно выработан. Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты! Рано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли всё к демонам. Задача твоя не из простых – помощники тебе не помешают. Оборудование находится в ящиках лиги Рудокопов, разбросанных по всему руднику." },
    ["307c"] = { common = "Там много кобольдов? Жду не дождусь приказа очистить от них рудник. Как подумаю, что они там хозяйничают, аж киплю весь!" },
    ["309a"] = { common = "Что ж, в путь? Для начала надо доставить Железняку порох. Вес немалый, а здесь небезопасно – кто знает, что ещё замышляют дворфы Чёрного Железа. С тобой мне будет куда спокойнее." },
    ["309c"] = { common = "О, слава Свету, вот мой порох. Но новости и верно тревожные. Только подумать, что находятся сторонники Чёрного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов. Но над этим пусть поломает голову кто-нибудь другой и не сегодня. А я найду этому пороху отличное применение." },
    ["310a"] = { common = "Не могу не признать, эти Громовары делают славные напитки. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок... Вот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что моё пиво лучше, чем Громоваров! Если бочонки охраняются, тебе придётся отвлечь стражу..." },
    ["310c"] = { common = "Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля." },
    ["311a"] = { common = "Подсунув бочонок жгучего пива Марлетты в подвал в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства..." },
    ["311c"] = { common = "Неплохо! Тебе, небось, нелегко было проскользнуть мимо их охраны? Да всё равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменевцев!" },
    ["312a"] = { common = "У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Он не смог, однако, взломать ториевый замок. Но я же с голоду помру, если не верну своё мясо! Ты вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь." },
    ["312c"] = { common = "Какая же ты добрая душа! Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури." },
    ["313a"] = { male = "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты способен? Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!", female = "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты способна? Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" },
    ["313c"] = { male = "О, эти гривы мне очень пригодятся! Ты крепкий орешек, герой, бьюсь об заклад, я о тебе ещё услышу!", female = "О, эти гривы мне очень пригодятся! Ты крепкий орешек, героиня, бьюсь об заклад, я о тебе ещё услышу!" },
    ["314a"] = { common = "Мы услышали шум среди ночи. Поутру не досчитались в отаре двух баранов. Эта подлая тварь Вагаш покушается на наше единственное добро! Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша. Может, тебе достанет отваги найти эту тварь и прикончить? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга." },
    ["314c"] = { common = "Отлично! Верон будет так рад этой доброй вести! Убить Вагаша – дело непростое. Сдаётся мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!" },
    ["315a"] = { common = "Я тут по делу, а дело моё – создать самый лучший портер! Я знаю, я смогу – пивоварение у меня в крови. Просто надо составить правильный рецепт... Тролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется. Они используют её в странных ритуалах своего племени. Нам, дворфам, она не особо нужна, но у неё неповторимый вкус... И я хочу поэкспериментировать с ней при варении пива! Добудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами." },
    ["315c"] = { common = "Великолепно! Прямо не терпится испробовать эту травку в одном из моих рецептов. Думаю, вот в этом она особенно хорошо пойдёт..." },
    ["317a"] = { common = "Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока ребята из Стальной Решётки работают с моим танком, не отправишься ли ты на охоту? Мне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова." },
    ["317c"] = { male = "Клянусь бородой Магни, ты славно поохотился! Спасибо тебе.", female = "Клянусь бородой Магни, ты славно поохотилась! Спасибо тебе." },
    ["318a"] = { common = "Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку. Редгольд живёт в Посёлке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути. И... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок." },
    ["318c"] = { common = "Толступузу нужно \"Вечное сияние\"? Ну, ладно." },
    ["319a"] = { male = "У меня есть бочонок \"Вечного сияния\", но... не мог бы ты оказать мне услугу? Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко... Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взял это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение.", female = "У меня есть бочонок \"Вечного сияния\", но... не могла бы ты оказать мне услугу? Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко... Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взяла это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." },
    ["319c"] = { common = "Спасибо тебе. Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!" },
    ["320a"] = { common = "Вот твоя бочка \"Вечного сияния\". И спасибо тебе за охоту." },
    ["320c"] = { common = "Ух ты! Пожалуй, открою-ка я его прямо сейчас да попробую..." },
    ["321a"] = { common = "Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожжённой и потопленной красными драконами во время последней Великой войны. Флотилия вышла из Лордерона, и с ней шёл эльфийский боевой корабль – \"Орлик\". Он вёз груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись... Ладно, краткий исторический экскурс будем считать завершённым. \"Орлик\" затонул к югу от Гавани Менетилов. Если найдёшь светлосталь, принеси её мне." },
    ["321c"] = { common = "Сундук весь размок, его обшивка сломана. На стенках внутри и снаружи видны глубокие следы когтей... как будто в нём шарились мурлоки и унесли все сокровища. Но в самом дальнем углу завалялся один-единственный слиток светлостали. К несчастью, этого мало. Для того чтобы выковать достойное оружие, вам нужно больше." },
    ["322a"] = { male = "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор. Металл, который ты нашёл, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!", female = "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор. Металл, который ты нашла, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" },
    ["322c"] = { common = "Да, занятный рассказ. И светлосталь! Я уже много лет не работал с этим материалом. Для меня это будет великая честь. А когда всё закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом. Но не будем опережать события. Первым делом -оружие, которым ты сокрушишь Морбента Скверна..." },
    ["323a"] = { common = "Морбент Скверн – могущественный некромант и союзник тёмных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу. Храбрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками." },
    ["323c"] = { common = "Без сомнения, в бою тебе нет равных. Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!" },
    ["324a"] = { common = "Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки. Найдите мурлоков-налётчиков у остова \"Орлика\" и отберите у них светлосталь." },
    ["324c"] = { common = "Ага, вот и материал! Ну что, пора бы пустить его в дело, а?" },
    ["325a"] = { male = "Вот оружие против твоего врага. путник, иди и сражайся. Удачи тебе, возвращайся со славой!", female = "Вот оружие против твоего врага. путница, иди и сражайся. Удачи тебе, возвращайся со славой!" },
    ["325c"] = { common = "О, это именно то, что сразит Морбента Скверна! Отлично! Готовься. Скверн теперь – не жилец." },
    ["332a"] = { common = "Если тебя интересует вино, так лучшее вино в Штормграде продаёт семейство Галлина! Это недалеко – в Торговом квартале, неподалёку от городских каналов. Возьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\". Не пожалеешь!" },
    ["332c"] = { male = "Вы знакомы с Ренато? В таком случае - только для вас, мсье... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всём Азероте!", female = "Вы знакомы с Ренато? В таком случае - только для вас, мадам... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всём Азероте!" },
    ["333a"] = { common = "Кажется, мы уже встречались. Наверное, насчёт покупки брони и походной одежды. Кстати, ожидается суровая зима... А сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна ещё одна партия от нашего поставщика. Если ты отнесёшь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика." },
    ["333c"] = { common = "Говорят, бизнес Харлана пошёл в гору. Хорошие новости, хотя… хотелось бы мне знать, для чего вдруг понадобилось столько брони. Неужели где-то поблизости скоро случится война? Благородные господа ничего не говорят нам об этом! Ну что ж, спасибо тебе за помощь. Вот твоя плата, и я надеюсь, что с заказом Харлана всё хорошо." },
    ["334a"] = { male = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, герой вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать... Прошу вас! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.", female = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, героиня вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать... Прошу вас! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." },
    ["334c"] = { common = "Ох, блин покровный! А я так надеялся, что забытые инструменты помогут мне увильнуть от работы. А теперь всё-таки придётся помочь Ларсону с шитьём... Ну, ладно: делу – время, потехе – час..." },
    ["337a"] = { common = "Хотя обложка книги исцарапана и заляпана грязью, на корешке всё ещё можно прочитать заглавие – \"История Штормграда\". Открыв её, вы видите на первой странице печать библиотеки Штормграда. Похоже, кто-то взял почитать эту книгу, да так и не вернул..." },
    ["337c"] = { common = "О небо! Этой книги не видели на полках со времён восстановления Штормграда. Конечно, её придётся реставрировать, она в плохом состоянии, но я с радостью помещу её в нашу коллекцию редких книг. Благодарю вас, господин. Прошу, примите плату за возвращение книги!" },
    ["343a"] = { common = "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать её для меня? Да осенит вас благодать Света! Королевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесёт для вас книгу." },
    ["343c"] = { common = "Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?" },
    ["344a"] = { common = "\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провёл в горах Каз Модана, добывая руду. Отличный парень! Но о чём это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с неё копию для своей коллекции. Уж сколько тому месяцев минуло... Интересно, почему он её задерживает." },
    ["344c"] = { common = "Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил её переписывать, так что мне пока что нужен оригинал!" },
    ["345a"] = { common = "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но... Я пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я ещё не успел закончить работу… и сделать ещё чернил я не могу! Для изготовления чернил мне нужна ретбанская руда из Красногорья. Штейгер Ослоу из Озёр – мой верный поставщик…" },
    ["345c"] = { male = "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь её сам!", female = "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь её сама!" },
    ["346a"] = { common = "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку." },
    ["346c"] = { common = "Это она! Спасибо! Да пребудет над тобой вечный сияющий Свет!" },
    ["347a"] = { common = "Ретбанская руда получила своё название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный тёмный цвет, и многие переписчики используют её для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда. К сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе ещё вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду. Так что если тебе нужна руда... ты знаешь, как добыть её." },
    ["347c"] = { common = "О, благодарю! Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"! Благодарю тебя!" },
    ["350a"] = { common = "Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара... Теперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твоё свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон. Тебе понадобится помощь. Я, увы, оказать её не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале." },
    ["350c"] = { common = "Опять Шоу?! Совести у него нет!.. Братство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите ещё, что Смертокрыл воскрес и напал на город... Ну, ладно, выкладывайте всё по порядку. И не пропускайте ни единой детали. Я хочу знать всё." },
    ["353a"] = { common = "Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утончёнными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие. Заказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьмётесь ли доставить груз? По моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане." },
    ["353c"] = { common = "Ага! Так Гриманд всё-таки закончил мой топор! Мне уже не терпится опробовать его на троггах и кобольдах! Благодарю. Эта посылка проделала такой долгий путь... Вот, примите это в благодарность за ваши услуги." },
    ["354a"] = { common = "Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... ещё до чумы. Когда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными... Из-за гордыни Агамондов мы стали нежитью, а сами они служат Плети! Сослужи Отрёкшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки." },
    ["354c"] = { common = "Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда. Конечно, глупо на это надеяться, но тем не менее." },
    ["355a"] = { male = "Ты принёс мне останки Агамондов и утолил мою жажду мести. Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся. Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.", female = "Ты принесла мне останки Агамондов и утолила мою жажду мести. Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся. Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." },
    ["355c"] = { common = "Коулман хорошо отзывался о тебе, и рассказал о твоём успешном походе на мельницы Агамондов. Отрёкшимся ещё раз нужна твоя помощь..." },
    ["356a"] = { common = "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них. Наш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов. Помоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на ферму Балнира на востоке – там настоящее гнездо Плети." },
    ["356c"] = { common = "Очень хорошо. Благодаря вашим усилиям Плеть ещё долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду." },
    ["357a"] = { common = "На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он - свободный Отрёкшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится. Но раз он Отрёкшийся, он понадобится Королеве. А если он ещё и специалист в некромантии, то его умения нам... весьма пригодятся. Чтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань её, и принеси мне." },
    ["357c"] = { common = "Прекрасно. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужил королеве добрую службу. Бетор открывает книгу и внимательно смотрит на её сияющие страницы… Невероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею! Гюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию. Судя по книге, после смерти он достиг ещё большего могущества. Его искусство могло бы нам очень пригодиться." },
    ["358a"] = { common = "Братские могилы к юго-востоку от фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы. Тела в этих могилах ещё не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо! У тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь." },
    ["358c"] = { common = "Отличная работа! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись. Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, её изучат наши аптекари. Возможно, они откроют какой-то секрет, который поможет нам в войне. Словом, ты отлично справился. Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." },
    ["359a"] = { common = "Мне нужен свежий отчёт с восточной базы наших стражей смерти. Я хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь ещё одну крепость. Иди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у неё есть вся нужная мне информация." },
    ["359c"] = { common = "Севрену нужен отчёт? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них всё же проникает время от времени. Плеть видели к востоку от нашей базы, возле Усадьбы Балнира." },
    ["360a"] = { common = "Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждёт её, так что поспеши. А если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям." },
    ["360c"] = { common = "Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться. Но и мы не уступим. Мы не позволим ему захватить нас снова!" },
    ["361a"] = { common = "Это письмо, написанное Турманом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до неё и не добралось..." },
    ["361c"] = { common = "О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть! Лицо Иветты смягчается. Но стенания – удел слабых. Я Отрёкшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось. Но та жизнь для меня окончена. Навсегда." },
    ["362a"] = { common = "Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Турман был высоким и учтивым, а его младший брат – слабым и острым на язык. Когда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание. Я собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости." },
    ["362c"] = { common = "Спасибо. Кости Девлина станут отличным украшением для моего плаща. Если что-то может согреть моё холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!" },
    ["363a"] = { male = "Ты вовремя пришёл в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не раб Короля-лича. Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.", female = "Ты вовремя пришла в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не рабыня Короля-лича. Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." },
    ["363c"] = { common = "А, ещё один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. Я всё это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. Нас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана. Тёмная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки." },
    ["364a"] = { common = "Мы, Отрёкшиеся, ведём войну против армии Плети, ведомой Королём-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков. Северную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить. Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сёстрами. Падшие – всего лишь рабы Короля-лича." },
    ["364c"] = { common = "Жаль, что нельзя привлечь Плеть на нашу сторону, её несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. Но так как договориться с ними нельзя, нам остаётся лишь уничтожить их." },
    ["365a"] = { male = "Кто это тут? Новенький, да ещё и герой? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся. К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв. Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл.", female = "Кто это тут? Новенькая, да ещё и героиня? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся. К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв. Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." },
    ["365c"] = { male = "Ты хорошо справился с заданием, герой, и тем самым доказал, что достоин примкнуть к армии Тёмной Госпожи.", female = "Ты хорошо справился с заданием, героиня, и тем самым доказал, что достоин примкнуть к армии Тёмной Госпожи." },
    ["366a"] = { common = "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана. Мы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамёна Короля-лича. Я рад, что он остался свободным. Мы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас." },
    ["366c"] = { common = "Моя книга?! Так это ты украл её! Но... что это за новые чары на ней... Бетор? Он в Лордероне? Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." },
    ["367a"] = { common = "Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Тёмная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса. В своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принеси мне пять склянок крови пса тьмы, чтобы я мог провести эксперимент." },
    ["367c"] = { common = "Вы хорошо справились. Благодарю вас за старания." },
    ["368a"] = { male = "Пока ты собирал для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее. Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.", female = "Пока ты собирала для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее. Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу." },
    ["368c"] = { common = "Отличная чешуя. Именно то, что мне нужно для микстуры." },
    ["369a"] = { common = "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов. Принесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах." },
    ["369c"] = { common = "Да, этот яд великолепно подойдёт! Я уже добавил всё остальное в мой состав и вскипятил его. Наконец-то я испытаю эту смертельно опасную смесь!" },
    ["370a"] = { common = "В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми. Убей Перрина, трёх ревнителей и трёх миссионеров, а потом доложи мне о своём успехе." },
    ["370c"] = { male = "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, герой.", female = "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, героиня." },
    ["371a"] = { common = "У нас до сих пор война, а Алый орден набирает силу. В отчёте палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира. Убей Вакона и пять келейников из Алого ордена – это должно нанести ордену сокрушающий удар!" },
    ["371c"] = { common = "Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы." },
    ["372a"] = { common = "Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш. Я даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Тёмной Госпожи." },
    ["372c"] = { male = "Вы отлично справились, герой. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счёт.", female = "Вы отлично справились, героиня. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счёт." },
    ["373a"] = { common = "Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в Ратуша на Соборной Площади\". Оно кажется написанным совсем недавно, и печать ещё свежая…" },
    ["373c"] = { common = "Эдвин ван Клиф, говорите? Я бы скорее ждал письма от своей покойной бабушки... Так это вы его убили? Извините, конечно, но я сильно удивлён. В молодые годы он был просто непревзойдённым бойцом. Ну, дайте-ка взглянуть, что он мне там написал после стольких лет... Барос рассматривает письмо. Эх, Эдвин… годы не изменили тебя ни на каплю. Всё такой же идеалист и романтик. Представляете, ему было всё равно, кому мстить. Месть попросту поглотила его. Но, кажется, я его понимаю…" },
    ["374a"] = { male = "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими. Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден. Помоги нам истребить их, герой. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже.", female = "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими. Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден. Помоги нам истребить их, героиня. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." },
    ["374c"] = { male = "Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, герой.", female = "Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, героиня." },
    ["375a"] = { common = "Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Тёмной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны. Теперь мои руки дрожат от холода. Если ты принесёшь мне пять шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, чтобы я могла и дальше служить нашему делу." },
    ["375c"] = { common = "Спасибо за заботу. Надеюсь, когда-нибудь слух о твоей храбрости дойдёт и до Сильваны..." },
    ["376a"] = { male = "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. Похоже, и ты будешь записан к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.", female = "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. Похоже, и ты будешь записана к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно." },
    ["376c"] = { common = "Спасибо. Держи этот доспех. Надеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…" },
    ["377a"] = { common = "Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева. Вард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И всё же Штормград объявил Варда своим пленником. Убей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу." },
    ["377c"] = { common = "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." },
    ["380a"] = { common = "Одна из наших самых серьёзных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. К северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придётся действовать постепенно. Отправляйся туда – может быть, ты сможешь чем-то помочь нам." },
    ["380c"] = { common = "Ну что же, для начала неплохо. Очистка всей территории займёт несколько недель или даже месяцев. А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину. Ты отлично справился, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." },
    ["381a"] = { male = "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! Будь осторожен, нечестивое рвение делает их опасными противниками.", female = "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! Будь осторожна, нечестивое рвение делает их опасными противниками." },
    ["381c"] = { common = "Если б только они послушались доводов разума, а? Может быть, мы могли бы уговорить их всё серьёзно обсудить... Как же! Идиоты, ослеплённые светом..." },
    ["382a"] = { common = "В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несёт важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! А ты, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти." },
    ["382c"] = { common = "Хмм... Ну-ка, посмотрим, что ты там нашёл... Аррен пробегает глазами документы, принесённые вами. Новости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... \"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы... А это ещё что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать." },
    ["383a"] = { male = "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно помог нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа. Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\".", female = "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно помогла нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа. Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\"." },
    ["383c"] = { common = "О, прекрасно! Ты отлично потрудился, добывая эту информацию. Хмм... Имена офицеров в Тирисфальских лесах… Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убъём всех их лидеров одним стремительным ударом." },
    ["384a"] = { common = "Завсегдатаи моей таверны больше всего любят кабаньи рёбрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу. Может, ты мне поможешь? Если принесёшь мне шесть рёбер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых рёбрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!" },
    ["384c"] = { common = "Сварено пиво, разлито по кружкам, Эй, не деритесь, друзья и подружки! Каждому выделим по половине Вкуснейшей порции рёбрышек в пиве!" },
    ["385a"] = { common = "Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса. Мы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо. Я и сам в своё время..." },
    ["385c"] = { male = "Ты отлично поохотился. За хорошую работу и платят хорошо!", female = "Ты отлично поохотилась. За хорошую работу и платят хорошо!" },
    ["386a"] = { common = "Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто. Положи конец Таргорру Ужасному. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства." },
    ["386c"] = { common = "Наконец-то Таргорр Ужасный получил по заслугам. Я рад, что злодей угодил в лапы Смерти. Молодец. Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутнённого взора политиканов." },
    ["387a"] = { common = "Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда. Наказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдёт в норму." },
    ["387c"] = { common = "Ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен." },
    ["388a"] = { common = "Кровь моя стынет в жилах от ужасного горя... Мой внук Мак… он был такой чудесный мальчик. Всего четырнадцать лет. Когда армия ушла на фронт, он счёл, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключённых из Братства Справедливости. Мак наказал некоторых заключённых за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину. Я хочу мести. Принесите мне десять этих проклятых шерстяных бандан. Они цвета крови..." },
    ["388c"] = { common = "Значит, из-за этих жалких тряпиц они убили моего Мака... Ужасная, нелепая смерть!.. Увы, мне не дано изменить прошлое. Но я благодарна вам, за то что вам удалось воздать по заслугам убийцам моего внука." },
    ["389a"] = { common = "Ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны. Когда мы закончили работу, вельможи отказались платить нам за неё. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить. Его лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме." },
    ["389c"] = { common = "Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает? Базиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!" },
    ["391a"] = { common = "Скажу тебе сразу: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно. Что от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернёшься вовремя, то будешь долго, долго гнить заживо…" },
    ["391c"] = { common = "Без Тредда бунтовщики станут куда более управляемыми. Посмотрим... Должен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся. Думаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчёт деятельности Тредда, которые тебя могут заинтересовать." },
    ["392a"] = { common = "Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен. Но пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке. Согласно документам, звали его Мелик; вот его описание. Не думаю, что он ещё когда-нибудь придёт к Тредду." },
    ["392c"] = { common = "Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать." },
    ["393a"] = { common = "Знаете ли, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки. Если кто-то и знает, о ком речь, то только он." },
    ["393c"] = { common = "Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наёмные убийцы носят много масок, зовутся множеством имён и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним. В общем, он – наёмный убийца, и я о нём довольно много знаю. Марзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда." },
    ["394a"] = { common = "Найдите Шоу в Старом городе. Дайте ему знать, что с Лесковаром покончено, и о вашей причастности к заговору лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть ещё герои. Думаю, он отправит вас на встречу с принцем или другим лордом. Не позволяйте им запудрить вам мозги. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны." },
    ["394c"] = { common = "Значит, мёртв? Ты скор на расправу. Не хотел бы я стать твоим врагом. Смеётся и кладёт руку вам на плечо. Не прими за осуждение. Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это." },
    ["395a"] = { common = "Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости. Позволь дать тебе совет: на твоём месте я бы по первой просьбе рассказал обо всём произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел. А что касается Триаса... ну, не говори о нём. Никогда. Если сможешь." },
    ["395c"] = { common = "Приятно тебя видеть снова. Мне довелось услышать о недавней кончине лорда Грегора Лесковара. Значит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа." },
    ["396a"] = { common = "Я готовлю донесение для короля. Надеюсь, ты сумеешь преподнести его величеству всё в лучшем виде. Не переживай так, король обязательно оценит твоё благородное служение народу Штормграда и достойно наградит тебя. Срок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда." },
    ["396c"] = { male = "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать. Возьмите этот жетон в знак королевской благосклонности, герой.", female = "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать. Возьмите этот жетон в знак королевской благосклонности, героиня." },
    ["398a"] = { common = "Разыскивается: Червеглаз! Ужасное даже по меркам гноллов чудовище – Червеглаз – приговорён к смерти за его преступления против Отрёкшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла. Город Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу. Милосердие – удел слабых." },
    ["398c"] = { common = "Наконец-то Червеглаз получил по заслугам. Пусть твой поступок запомнится всем, кто захочет навредить нашему народу! Благодарю тебя от имени всего города Брилла." },
    ["399a"] = { common = "С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжён. Я спросил у отца о судьбе некоторых моих вещей, например, о моём первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме. Усадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдёшь мой компас?" },
    ["399c"] = { common = "Благодарю вас! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности..." },
    ["400a"] = { common = "Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые! Мы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды. Ты сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работёнка подвернётся." },
    ["400c"] = { male = "У тебя мои инструменты? Отлично, парень, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принёс мне эти инструменты. Вот, возьми эти деньги; спасибо!", female = "У тебя мои инструменты? Отлично, девчушка, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принесла мне эти инструменты. Вот, возьми эти деньги; спасибо!" },
    ["401a"] = { common = "Я почти закончил работу над переводом записки. Она будет готова через несколько минут." },
    ["401c"] = { common = "Ну вот. Готово… Вокруг воцаряется душная тишина, словно на лес опустился тёмный тяжёлый полог..." },
    ["404a"] = { common = "Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста. Отправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти." },
    ["404c"] = { common = "Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!" },
    ["405a"] = { male = "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого. Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело. Приготовься как следует, герой. Не подведи нас. Бетора можно найти в квартале Магов Подгорода.", female = "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого. Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело. Приготовься как следует, героиня. Не подведи нас. Бетора можно найти в квартале Магов Подгорода." },
    ["405c"] = { common = "А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное. Уверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим." },
    ["407a"] = { common = "Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития. Чуть-чуть смекалки, и простая тыква превратится в шпиона Тёмной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом. Вот недавно мы поймали ещё одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\". Иди, отнеси ему эту тыкву." },
    ["407c"] = { common = "Благословенный Свет! Наконец-то еда! Сладенькая тыквочка..." },
    ["408a"] = { male = "Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас. Ты не должен допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков. А заодно принеси мне череп капитана Даргола.", female = "Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас. Ты не должна допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков. А заодно принеси мне череп капитана Даргола." },
    ["408c"] = { common = "Твои действия нанесли Плети ощутимый удар! И твоя победа не будет забыта ни Отрёкшимися, ни врагами. Продолжай бороться вместе с нами, и когда-нибудь мы изгоним Короля-лича из Азерота!" },
    ["409a"] = { male = "Ты говоришь, что неподвластен воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты должен доказать то, что являешься врагом Плети. На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара. Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича.", female = "Ты говоришь, что неподвластна воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты должна доказать то, что являешься врагом Плети. На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара. Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича." },
    ["409c"] = { common = "Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети! Я думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича." },
    ["411a"] = { common = "Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать." },
    ["411c"] = { common = "Ты убедил его присоединиться к нам! Это огромная радость для всех Отрёкшихся. Я доложу об этом Тёмной Госпоже." },
    ["412a"] = { common = "При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов! Мы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – перенаправлятора. Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни. Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!" },
    ["412c"] = { common = "Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления. Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена." },
    ["413a"] = { common = "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан. Может, он и не такой пивовар, как остальные Ячменовары, но своё пиво он любит, и я знаю, что это тоже ему понравится. Не отнесёшь ему вот этот бочонок \"Мерцающего портера\"?" },
    ["413c"] = { common = "Горный пехотинец Ячменовар пробует \"Мерцающий портер\"... Ох-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!" },
    ["414a"] = { common = "Я бы и ещё отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телcамар в озере Лок Модан. Чтобы добраться до Телcамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телcамара. Отдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!" },
    ["414c"] = { common = "Ну-с, попробуем... Клянусь бородой Магни! Аж голова кругом пошла! И в теле лёгкость необыкновенная. Сейчас полечу, как птичка!" },
    ["415a"] = { male = "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя. Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помог. Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо. Может, тебя дармовая выпивка ждёт...", female = "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя. Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помогла. Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо. Может, тебя дармовая выпивка ждёт..." },
    ["415c"] = { male = "путник! Помнишь тот звездолист, что ты принёс мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно! Вот, попробуй и скажи, как пошло...", female = "путница! Помнишь тот звездолист, что ты принесла мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно! Вот, попробуй и скажи, как пошло..." },
    ["416a"] = { common = "К западу отсюда началось настоящее нашествие. Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю! Их необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду. Кобольды-туннельщиков поселились к западу от Телcамара вдоль горных склонов." },
    ["416c"] = { common = "Фу! Когда я просил принести уши, я не подозревал, что они так дурно пахнут! Прими награду. Молодчина." },
    ["417a"] = { common = "Хилдельв пишет в своём журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\". Он отогнал тварь, но та успела страшно изранить его. Судя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его. В журнале Хилдельв записал своё последнее пожелание: \"Отомстить Паршивому Когтю.\"" },
    ["417c"] = { common = "Злая весть. Хилдельв был хорошим другом. Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя! Спасибо тебе. Пилоты Осадной бригады Стальгорна тебя не забудут." },
    ["418a"] = { male = "Едоки в Телcамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовал? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение. Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь всё это, а уж Видра сготовит всё в лучшем виде!", female = "Едоки в Телcамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовала? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение. Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь всё это, а уж Видра сготовит всё в лучшем виде!" },
    ["418c"] = { common = "Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но... Хоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе всё же дам. Бери! Ешь, пока рот свеж!" },
    ["419a"] = { common = "Мой друг и напарник, пилот Осадного орудия Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался! Хилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошёл дальше пешком. Прошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах. Мори – парень-кремень, но мне тревожно. Прошу тебя, найди его." },
    ["419c"] = { common = "Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во всё ещё превосходно сохранившийся жилет бригадира. Эта мрачная сцена показывает, где встретил свой конец пилот Осадной машины." },
    ["420a"] = { common = "Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться. Если тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе. А добраться туда и вовсе просто: пройдёшь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса." },
    ["420c"] = { common = "А что это у нас тут такое? О, донесение от моего братца! Хм-м... Говорил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха! Как бы то ни было, думаю, мне нужно и своё донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Всё этот проклятый холод! Слушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работёнка..." },
    ["421a"] = { common = "Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу. Но этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Тёмного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. Мне нужен кто-то, искушённый в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте пять белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом." },
    ["421c"] = { male = "Вы сослужили мне хорошую службу, герой. Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.", female = "Вы сослужили мне хорошую службу, героиня. Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." },
    ["422a"] = { common = "Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор. Его знания касательно применения заклинаний были просто мыльным пузырём. Сейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать её против него и обеспечить владычество Тёмной Госпожи в Серебряном бору. Вначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\"." },
    ["422c"] = { male = "Да, это именно та книга, которую я искал, герой. Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся.", female = "Да, это именно та книга, которую я искал, героиня. Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." },
    ["423a"] = { common = "Изучив деятельность Аругала я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин Тор в самый трудный час. Идиоты! Для усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйтесь в путь и убивайте обжор Лунной Ярости и тёмных духов Лунной Ярости, пока не наберёте достаточного для моих исследований количества их заколдованных наручей. Эти злобные создания обитают к северу и к востоку отсюда." },
    ["423c"] = { male = "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. Тем не менее, вы отменно проявили себя, собирая эти, герой.", female = "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. Тем не менее, вы отменно проявили себя, собирая эти, героиня." },
    ["424a"] = { common = "Мне потребуется больше времени на раскрытие тёмных тайн чар Аругала,чем я думал. Но тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. Этот рудник стал бы ценным ресурсом для Вариматраса. Я хочу, чтобы вы снесли голову с плеч поражённому скверной старшине рудника Мрачнону Белёсому. После его смерти рудник будет нашим." },
    ["424c"] = { common = "Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту." },
    ["425a"] = { common = "Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. Нам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. Убейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность." },
    ["425c"] = { common = "О, спасибо. Я очень благодарна вам. Я упомяну ваше имя в отчёте, который направлю своему вышестоящему начальству." },
    ["426a"] = { common = "Плеть пытается основать базу на мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале. Поступил приказ уничтожить всю Плеть на мельницах. Отправляйся туда и собери зазубренные рёбра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей. Чтобы добраться до мельниц, иди по дороге на запад. После того как перейдёшь мост, поверни на север, и скоро увидишь ветряные мельницы." },
    ["426c"] = { common = "Твои старания не прошли даром! Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твоё имя!" },
    ["427a"] = { male = "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах. Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом. Докажи мне, что способен служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена.", female = "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах. Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом. Докажи мне, что способна служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." },
    ["427c"] = { male = "Замечательно, герой. Ваши боевые умения не вызывают сомнений.", female = "Замечательно, героиня. Ваши боевые умения не вызывают сомнений." },
    ["428a"] = { common = "Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. Они могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих стражей смерти. Их первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там." },
    ["428c"] = { common = "Вы нашли нас! Ещё чуть-чуть – и было бы уже поздно..." },
    ["429a"] = { common = "Моего брата Квинна серьёзно ранил вурдалак Ивар Нечистый. Боюсь, без алхимической помощи он теперь не исцелится. Я мало что понимаю в лекарском искусстве, но знаю, что наши аптекари умеют варить целительные зелья из обесцвеченных сердец воргов. Добудь такие сердца и отнеси их аптекарю Ренферрелу в гробницу к югу отсюда. Потом возвращайся с зельем. Множество воргов водится на пути к Саду Мальдена, что к востоку." },
    ["429c"] = { common = "Ренферрел берёт у вас сердца. Меня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. Будем надеяться, что таких неудач будет немного. Я сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им её оказать." },
    ["430a"] = { common = "Вот зелье, которое должно помочь Квинну Йорику поправиться. А теперь, простите, мне нужно продолжить одно очень важное дело..." },
    ["430c"] = { common = "Квинн выпивает зелье. Да, я чувствую его действие. Вскоре я снова смогу передвигаться. Вы оказали мне большую услугу." },
    ["432a"] = { common = "Эти проклятые Светом трогги перевернули всё моё рабочее место! Ты только глянь, ещё одну бочку пороха разворотили! Ох, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал! Но здоровье не позволяет, да ещё это потрясение и злость... Они ничего мне не оставили! Я бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!" },
    ["432c"] = { common = "Ох, на душе полегчало... Но я не успокоюсь, пока все трогги не будут уничтожены! Все до единого!" },
    ["433a"] = { common = "Будучи членом Сената и Лиги Исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли. Они ни за что ни про что разнесли карьер Гол'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт. У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе. Если вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени." },
    ["433c"] = { common = "Это только начало. Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района. Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе. Спасибо тебе за помощь." },
    ["434a"] = { male = "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем. Пока ты собирал для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов. Лесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.", female = "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем. Пока ты собирала для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов. Лесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом." },
    ["434c"] = { male = "Сделано? Отлично. путник, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса. Постарайтесь ни во что не вляпаться.", female = "Сделано? Отлично. путница, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса. Постарайтесь ни во что не вляпаться." },
    ["435a"] = { common = "Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. Я должен доложиться своей коллеге, стражу смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков. Пожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья..." },
    ["435c"] = { common = "Спасибо за помощь. Я боялась, что Эрланда погубили опасности Серебряного бора. Но я вижу, что благодаря вашей помощи этого не произошло." },
    ["436a"] = { common = "Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов! Сталекрут – надёжный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать. Отправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведёт отчётность по раскопкам и сможет объяснить, чем вызвана задержка. Чтобы отыскать раскопки, обогни озеро с юга и направляйся на восток." },
    ["436c"] = { common = "Значит, Джерн хочет узнать, чем вызвана задержка? Железняк как раз пишет подробный отчёт о своих последних достижениях, но я буду краток. Дело в троггах!!!" },
    ["437a"] = { common = "Первые отчёты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мёртвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. Мы хотим уничтожить Плеть Ночи. Отправляйтесь на Мёртвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и её. Сущность банши обратится в прах. Принесите мне этот прах в доказательство её смерти." },
    ["437c"] = { common = "Я слышал о вашем успешном набеге на гноллов-гнилошкуров, а эта сущность является доказательством смерти банши Плеть ночи. Сегодня Король-лич потерял ещё одного прислужника. Вы становитесь ещё более ценным союзником в глазах Отрёкшихся." },
    ["438a"] = { common = "Мы обнаружили ещё одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и её патрулируют многочисленные гноллы-гнилошкуры и различная нежить. Полагаю, Плеть захватила это место неспроста. Отправляйтесь к старой переправе и выясните, в чём там дело." },
    ["438c"] = { common = "В лодке находится куча спелёнутых мёртвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. Должно быть, разгадку этой тайны стоит искать на острове." },
    ["439a"] = { common = "Из кучи трупов торчит обнажённая рука. Это рука женщины – тронутая чумой, но относительно свежая. На пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: \"Делии\"." },
    ["439c"] = { common = "Говорите, это кольцо было надето на палец недавно погибшей женщины? Видимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!" },
    ["440a"] = { common = "Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьёй Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезёт, он сможет выяснить, кто такая Делия. Но я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мёртв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии." },
    ["440c"] = { common = "Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, её тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. Стая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги." },
    ["441a"] = { common = "У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. Найти Роли вы можете в Торговом квартале Подгорода." },
    ["441c"] = { common = "Да, это вещица моей жены. Её постигла та же участь, что и всех, кому не удалось пережить эти суровые времена. Меня не трогает её смерть, как не трогает и ваш рассказ о похищении её тела. Подобные чувства давно остыли во мне. Но желание всё ещё клокочет в моём мёртвом сердце. Желание отомстить." },
    ["442a"] = { male = "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. Ты снова должен добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова! Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должен выйти победителем!", female = "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. Ты снова должна добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова! Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должна выйти победительницей!" },
    ["442c"] = { common = "Смерть Тула Когтя Ворона – значимое событие. Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы. Твои действия получили большой резонанс у Отрёкшихся. Твоя ценность в наших глазах растёт." },
    ["443a"] = { common = "Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. Отправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалёку от Гробницы." },
    ["443c"] = { common = "Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чём их слабость... ...если она у них есть..." },
    ["444a"] = { male = "Я выпарил лимфу, которую ты принёс мне, и разложил её на основные компоненты. Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров. Иди же. Бетора ты найдёшь в Квартале Магов Подгорода.", female = "Я выпарил лимфу, которую ты принесла мне, и разложил её на основные компоненты. Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров. Иди же. Бетора ты найдёшь в Квартале Магов Подгорода." },
    ["444c"] = { common = "Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... Секундочку – мне придётся воспользоваться проясняющим заклинанием..." },
    ["445a"] = { male = "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сам понял. Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа. Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.", female = "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сама поняла. Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа. Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." },
    ["445c"] = { male = "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь... Ах, простите. Задержитесь в Серебряном бору чуть подольше, такой герой, как вы, всегда нам пригодится.", female = "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь... Ах, простите. Задержитесь в Серебряном бору чуть подольше, такой героиня, как вы, всегда нам пригодится." },
    ["446a"] = { common = "Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошёл в силу Король-лич, Тул предал своих братьев и перешёл на сторону Плети. Я и не думал, что он всё ещё жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! Я знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья." },
    ["446c"] = { common = "Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса." },
    ["447a"] = { common = "Силы Артаса неисчислимы. Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. Мои исследования показали, что паучья кровь в соединении с токсином, извлечённом из сердца бешеного медведя, даёт смертельно опасный эликсир. Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества." },
    ["447c"] = { common = "Аптекарь Ренферрел правильно сделал, что послал вас ко мне. Эти образцы действительно будут весьма полезны. Я немедленно начну изучить их отравляющие и инфицирующие свойства." },
    ["448a"] = { common = "Прежде чем вы нападёте на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится." },
    ["448c"] = { common = "Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причём разобраться срочно. В качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала..." },
    ["449a"] = { common = "Хотя раны Квинна заживают, я хотела бы доставить наш отчёт верховному палачу Хадрику как можно скорее. В нём содержится информация, которая жизненно важна для захвата Серебряного бора Отрёкшимися." },
    ["449c"] = { common = "Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции. Ваша помощь нашим стражам смерти просто неоценима. Вы заслуживаете похвалы." },
    ["450a"] = { common = "Вы можете ещё послужить Королевскому фармацевтическому обществу. Когда Аругал навёл на лес свою никчёмную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. Раздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу." },
    ["450c"] = { common = "Записи аптекаря Берарда! В смелости вам не откажешь. Теперь давайте посмотрим, чем занимался Берард прежде, чем сошёл с ума..." },
    ["451a"] = { common = "Согласно записям Берарда, мох озёрных тихоходов и озёрных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. Он также упоминает об очень редкой субстанции – твёрдой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. Соберите образцы моха, а также редкую твёрдую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород." },
    ["451c"] = { male = "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи. Мы находимся на пороге чего-то великого путник. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества.", female = "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи. Мы находимся на пороге чего-то великого путница. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества." },
    ["452a"] = { common = "Вы очень вовремя добрались сюда! Совет деревни Погребальных Костров вернётся в любой момент. Аругалу же есть чем заняться в крепости. Он использует совет как марионеток, чтобы держать лишённых разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина. Я не могу справиться со всем в этим в одиночку. Мне нужна ваша помощь. Вместе мы сможем погубить совет, на благо леди Сильваны." },
    ["452c"] = { common = "Вы бились достойно настоящего последователя Тёмной Госпожи. Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Тёмного Клыка. Честь имею!" },
    ["453a"] = { common = "Удачи. Надеюсь, ты найдёшь этого парня, причём живым. Сбежав за пределы Темнолесья, он мог пасть жертвой диких зверей." },
    ["453c"] = { common = "Трясунчик вздыхает... Да, автор этой книги – я. Сумел-таки отыскать меня? Но если ты прочитаешь мои записи, то узнаешь только половину истории!" },
    ["454a"] = { common = "До этого... случая мы всё время таскали туда-сюда бочки с порохом. Теперь придётся поделить работу: Миран понесёт часть бочек, а я присмотрю за остальными. Мне не хочется отпускать Мирана одного. Когда он соберётся в путь, проводи, пожалуйста, его." },
    ["454c"] = { male = "Добрый день, герой. Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа. Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом.", female = "Добрый день, героиня. Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа. Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом." },
    ["455a"] = { common = "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине. Попытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов. Найти Менетилов несложно: пройдёшь через Дун Альгаз, потом – по дороге на север, а на развилке свернёшь на запад. Мы очень надеемся на тебя. Не подведи нас." },
    ["455c"] = { common = "Да, нехорошие новости! Как я понимаю, орки Драконьей Пасти всерьёз вознамерились двинуться на Альгаз. Обычно они сидят у себя на холмах и никуда не суются. Что их сподвигло идти на Альгаз? Для меня это загадка... Спасибо. Может быть, нам понадобится твоя помощь, когда мы пойдём разбираться с орками." },
    ["456a"] = { male = "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают. К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. Юный герой, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.", female = "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают. К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. Юная героиня, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." },
    ["456c"] = { male = "Ты хорошо исполнил свой долг.", female = "Ты хорошо исполнила свой долг." },
    ["457a"] = { common = "Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, однако нужно выполнить ещё некоторую работу. Лесные ресурсы истощатся слишком быстро, если не решить эту проблему. Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия." },
    ["457c"] = { male = "Твои дела доказывают твою преданность природе. Поверь, герой, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее.", female = "Твои дела доказывают твою преданность природе. Поверь, героиня, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." },
    ["458a"] = { male = "Какая отрада, что ты здесь, герой. Шёпот лесных духов донёс до моего слуха странные вести. Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определённо не так, если она вновь появилась в этих землях. Найди Тариндреллу и узнай, что привело её в наши рощи. Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила.", female = "Какая отрада, что ты здесь, героиня. Шёпот лесных духов донёс до моего слуха странные вести. Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определённо не так, если она вновь появилась в этих землях. Найди Тариндреллу и узнай, что привело её в наши рощи. Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." },
    ["458c"] = { male = "Я вижу, тебе удалось найти меня, юный ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда. Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания.", female = "Я вижу, тебе удалось найти меня, юная ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда. Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания." },
    ["459a"] = { common = "Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги. Они покинули свои дома и объединились в племя Кривой Сосны. Лишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения. Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины. Напади на этих бесов, и узнай, действительно ли они подпали под чары зловещего мха Скверны." },
    ["459c"] = { male = "Твоё служение обитателям Тенистой долины достойно награды. Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь. герой, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса.", female = "Твоё служение обитателям Тенистой долины достойно награды. Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь. героиня, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса." },
    ["460a"] = { common = "На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... Меня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! Пожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле." },
    ["460c"] = { common = "Спасибо. Я опасался, что гноллы изуродовали моё тело. Приятно узнать, что это не так." },
    ["461a"] = { common = "Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! Углубление в стене находится в юго-западной башне крепости, позади пыльной полки. Возьмите моё тело, а сапоги оставьте здесь. Они мне всё равно не по ноге..." },
    ["461c"] = { common = "Вот мы и на месте, здесь открыто. Оставь меня здесь. Лучшие дни своей жизни я провёл в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. Хорошенько закрой нишу – я не хочу, чтобы эти гнилошкуры нашли меня. Ах, да, и возьми вот это. Ты это заслуживаешь." },
    ["463a"] = { male = "Ты ведь слышал рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим. Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями. Оставь-ка свои денежки мне – покойникам они всё равно не нужны. Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?", female = "Ты ведь слышала рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим. Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями. Оставь-ка свои денежки мне – покойникам они всё равно не нужны. Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?" },
    ["463c"] = { male = "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришёл с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль. А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.", female = "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришла с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль. А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." },
    ["466a"] = { common = "Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек! Раздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах. Ах да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!" },
    ["466c"] = { common = "Как раз столько, сколько нужно для экспериментов! Молодец, я в тебя верил! Тут же отправлю материал на изучение. Надеюсь, что мой доброволец хотя бы до первых результатов доживёт!" },
    ["467a"] = { common = "Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий. До него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет её. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в посёлке Сталежара в Дун Мороге и спроси, чего он хочет." },
    ["467c"] = { male = "Привет. Ты тут по моему делу, да? Приятно видеть, как молодой путник рвётся на поиски приключений!", female = "Привет. Ты тут по моему делу, да? Приятно видеть, как молодая путница рвётся на поиски приключений!" },
    ["468a"] = { common = "Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину! Если желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней." },
    ["468c"] = { male = "герой, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично! Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже...", female = "героиня, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично! Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." },
    ["469a"] = { male = "Привет тебе, странник! Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок! Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана. Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.", female = "Привет тебе, путешественница! Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок! Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана. Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза." },
    ["469c"] = { common = "Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи! Надо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому..." },
    ["470a"] = { male = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась... Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи! Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласился помочь!", female = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась... Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи! Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласилась помочь!" },
    ["470c"] = { common = "Спасибо большущее! Я-то боялась, что её больше не вернуть! Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку. Хм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится." },
    ["471a"] = { common = "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных. Лекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит! Если у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков." },
    ["471c"] = { common = "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь? Хе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!" },
    ["475a"] = { common = "Ветер тревоги веет над лесом. Гэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе. Но вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звёздного Ветра – мне нужен отчёт Гэроласа, дабы я был спокоен, узнав, что мои братья и сёстры спят спокойно." },
    ["475c"] = { common = "Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлёт помощь." },
    ["476a"] = { male = "Племя Кривой Сосны поражено порчей! Эти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны. Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юный герой. Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!", female = "Племя Кривой Сосны поражено порчей! Эти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны. Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юная героиня. Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" },
    ["476c"] = { common = "Клянусь звёздами! Воистину тревожные вести!" },
    ["477a"] = { common = "Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей. Она держится там в основном за счёт поддержки, которую они получают от волшебников Даларана. Я не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение. Они отправляют повозкой из Хилсбрада сундуки. Многое из привезённого складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне." },
    ["477c"] = { common = "*С любопытством открыв крышку ящика, вы находите в нём множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. Под картами обнаруживается подвеска таинственно-волшебного вида.*" },
    ["478a"] = { common = "*Вы быстро вытаскиваете подвеску из сундука и кладёте крышку на место.*" },
    ["478c"] = { common = "Карты и эта... эта подвеска? Интересно. Очевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остаётся неизвестной. Может быть, Далар сможет выяснить, что они там ищут." },
    ["479a"] = { common = "Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путём... Маги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. Чтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток." },
    ["479c"] = { common = "Далар выяснил, что несмотря на замедление, процесс плетения чар зашёл уже далеко. Некий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить." },
    ["480a"] = { common = "Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. Вам надо пойти и разобраться с ним, быстро. Когда он будет мёртв, принесите мне его посох. Идите немедленно." },
    ["480c"] = { common = "Магия волшебников рассеивается, и энергетические узлы вновь засыпают. Ваши усилия оказались плодотворными, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьёзный удар. Однако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее." },
    ["481a"] = { common = "Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников." },
    ["481c"] = { common = "Интересно – похоже, новые махинации Кирин-Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии. То, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьёзное. Посмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях." },
    ["482a"] = { common = "Конечно! Как же я мог забыть? Янтарная Мельница была одним из мест, отмеченных магами Кирин Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьёзной цели. Мы не можем позволить этому случиться... Чтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. Передайте эту информацию Алистеру, он спланирует дальнейшие действия." },
    ["482c"] = { common = "Вы принесли тревожные вести. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро. Мне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс." },
    ["483a"] = { common = "Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там всё подряд. Спящие друиды никогда не смогут выйти из Изумрудного Cна – они даже не понимают, в какую западню угодили, – если мы только им не поможем. Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения. Отправляйся в обитель и найди талисман Когтя Ворона, Чёрное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения." },
    ["483c"] = { male = "Тебе удалось это сделать, юный герой! Славно! И как раз вовремя.", female = "Тебе удалось это сделать, юная героиня! Славно! И как раз вовремя." },
    ["484a"] = { male = "Ты, наверное, слышал обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру! Уже встречался с Эйнаром? Он – один из охотников, приносящих мне шкуры. В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков. Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом.", female = "Ты, наверное, слышала обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру! Уже встречалась с Эйнаром? Он – один из охотников, приносящих мне шкуры. В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков. Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом." },
    ["484c"] = { common = "Отлично, превосходно! Прекрасные шкуры! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя ещё об одной услуге. Думаю, ты справишься." },
    ["486a"] = { common = "Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, их сон станет вечным. Я подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня всё получилось, тварь, виновная в их злоключениях, должна быть уничтожена. Только тогда ритуал может быть выполнен. Это Урсал Изверг разрушил дело наших братьев, и теперь он должен заплатить за свои злодеяния ради их освобождения. Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его." },
    ["486c"] = { male = "Ты проявил себя как весьма достойный и способный герой. путник, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире. Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия.", female = "Ты проявила себя как весьма достойная и способная героиня. путница, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире. Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." },
    ["487a"] = { male = "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны. Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам. Возьмись же за оружие во имя священного леса, герой. Их логово находится где-то под этим наблюдательным пунктом. Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне.", female = "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны. Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам. Возьмись же за оружие во имя священного леса, героиня. Их логово находится где-то под этим наблюдательным пунктом. Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." },
    ["487c"] = { male = "Ты славно послужил доброму народу Доланаара и Дарнаса, отважный герой. От имени всех часовых Тельдрассила воздаю тебе хвалу.", female = "Ты славно послужила доброму народу Доланаара и Дарнаса, отважная героиня. От имени всех часовых Тельдрассила воздаю тебе хвалу." },
    ["488a"] = { male = "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивному юнцу... вроде тебя. Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь. Мне часто бывают нужны определённые... ингредиенты. Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника. И пусть это всё останется между нами, путник.", female = "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивной девчушке... вроде тебя. Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь. Мне часто бывают нужны определённые... ингредиенты. Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника. И пусть это всё останется между нами, путница." },
    ["488c"] = { male = "Ха-ха! Хорошая работёнка! Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать путник? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!", female = "Ха-ха! Хорошая работёнка! Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать путница? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!" },
    ["489a"] = { male = "Совет Леса узнал, что ты помог Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как путник, должен бы понимать, что оскверняешь лес, убивая созданий Природы! Ты должен искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым. Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.", female = "Совет Леса узнал, что ты помогла Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как путница, должна бы понимать, что оскверняешь лес, убивая созданий Природы! Ты должна искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым. Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое." },
    ["489c"] = { common = "Ну что ты за лапочка! Я знал, что ты мне ещё пригодишься!" },
    ["490a"] = { common = "По приказу часовых я назначаю награду за головы фурболгов из племени Кривой Сосны. Это враги леса. Скверна лишила их рассудка, и теперь они угрожают нашему народу и лесным жителям. Мы отблагодарим всякого, кто защитит Тельдрассил от этой напасти. Только принеси их клыки в качестве доказательства. Больше всего фурболгов собралось в лощине Бен'этиль на западе от Доланаара и с южной стороны от дороги, а также в деревне Звёздного Ветра на востоке." },
    ["491a"] = { common = "Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трёх принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел её, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса. Здесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить." },
    ["491c"] = { common = "... Что это?! У Туле был наш Сплетённый жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу! Должно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал. И хорошо, что Тул не использовал жезл... Это удивительная находка. Я признателен за неё, и вознагражу тебя." },
    ["492a"] = { common = "Страж смерти сообщил, что недавно был захвачен ещё один дворф-горный пехотинец. Стражи смерти обычно сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный приём\". Почему бы вам не пойти и не угостить пленника специальным напитком, который я приготовил? В нём есть небольшая примесь того, что Тёмная Госпожа готовит для всего Азерота." },
    ["492c"] = { common = "Ах, наконец-то питьё! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло." },
    ["493a"] = { common = "Тёмная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. Поэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. Направляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!" },
    ["493c"] = { common = "А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы." },
    ["494a"] = { male = "Молчи и слушай, герой. Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\" Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!", female = "Молчи и слушай, героиня. Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\" Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!" },
    ["494c"] = { common = "Крик ворона на западе манит? Отличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматас будет доволен." },
    ["496a"] = { common = "Ах, ещё один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение. Чем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило. Если ты хочешь принести пользу, добудь для меня следующее: десять языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен." },
    ["496c"] = { male = "Отличные компоненты. Что ж, ты умудрился внести хоть немного радости в мой тоскливый день. Благодарю тебя.", female = "Отличные компоненты. Что ж, ты умудрилась внести хоть немного радости в мой тоскливый день. Благодарю тебя." },
    ["498a"] = { common = "Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат. Мы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать. Дарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог'тара, освободи их." },
    ["498c"] = { common = "Значит, люди собирались поработить наших воинов? Мы ещё им покажем! Похоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он… Когда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе." },
    ["499a"] = { common = "Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания. Вот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир. Посмотрим, достигнут ли желанный эффект. Дай попробовать моему помощнику Ампи то, что Тёмная Госпожа готовит людям и созданиям Плети." },
    ["499c"] = { common = "Квак!" },
    ["501a"] = { common = "О... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесёт в мир заслуженную смерть! Но как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Тёмной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся." },
    ["501c"] = { common = "Отличная работа." },
    ["516a"] = { common = "Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооружённые этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. К сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. Я доверяю вашей изобретательности. Отыщите их и нанесите им поражение." },
    ["516c"] = { common = "Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича." },
    ["527a"] = { male = "Когда говоришь со мной, стой по стойке \"смирно\", герой. Я нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы. По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим. Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.", female = "Когда говоришь со мной, стой по стойке \"смирно\", героиня. Я нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы. По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим. Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца." },
    ["527c"] = { male = "Вольно, герой. Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.", female = "Вольно, героиня. Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде." },
    ["528a"] = { male = "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно. Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели. Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Тёмной Госпожи. Свободен!", female = "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно. Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели. Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Тёмной Госпожи. Свободна!" },
    ["528c"] = { common = "Смерть всё крепче сжимает костлявую руку на горле Хилсбрада. Битва идёт хорошо." },
    ["529a"] = { common = "Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения. Убей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападём на Южнобережье." },
    ["529c"] = { male = "Задание выполнено, герой. И, надо сказать, выполнено на славу.", female = "Задание выполнено, героиня. И, надо сказать, выполнено на славу." },
    ["530a"] = { common = "Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьёшь Валдреда и принесёшь мне его проклятые руки, я тебя награжу. По последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гильнеас." },
    ["530c"] = { common = "А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием. Возьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга." },
    ["531a"] = { common = "Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично! Скорее убери её отсюда! Никому здесь не нужны твои страхолюдные трофеи!" },
    ["531c"] = { male = "Спасибо, что помог мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужил.", female = "Спасибо, что помогла мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужила." },
    ["532a"] = { common = "В Хилсбраде царит паника. Думаю, он скоро падёт. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки. Невзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации." },
    ["532c"] = { male = "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, герой.", female = "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, героиня." },
    ["538a"] = { common = "Доброго дня вам. Если вы не против долгого путешествия, то у меня для вас найдётся задание, которое поможет пополнить библиотеку Штормграда. Вместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить всё, что можем. Южнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги..." },
    ["538c"] = { common = "Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров... И он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения! Теперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры..." },
    ["539a"] = { common = "Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там. Хотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник. Рудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок." },
    ["539c"] = { common = "Тёмная Госпожа будет рада услышать, что у неё появился новый рудник, который поможет вооружить её бойцов." },
    ["540a"] = { common = "Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси всё, что можно! Ступай в руины Альтерака и поищи там манускрипты, украденные ограми. Собери всё, что сможешь и принеси мне. Больше всего меня интересует одна книга – \"Рука Гри'лека\". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака." },
    ["540c"] = { common = "А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри'лека\"." },
    ["541a"] = { male = "Дворфы пришли на помощь людям? Проклятые мелкие твари! Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях. Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, герой. Глава дворфов, капитан Железная Гора, должен умереть.", female = "Дворфы пришли на помощь людям? Проклятые мелкие твари! Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях. Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, героиня. Глава дворфов, капитан Железная Гора, должен умереть." },
    ["541c"] = { common = "Твои подвиги на поле битвы достойны высочайшей хвалы." },
    ["546a"] = { common = "Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую… Пока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен. Может, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы тридцать черепов, принеси мне, и я тебе хорошо заплачу." },
    ["546c"] = { common = "Превосходные черепа! И какие красивые! Вот тебе обещанная плата!" },
    ["549a"] = { common = "По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен. Всем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда." },
    ["549c"] = { male = "Великолепно, герой. Такими темпами мы мигом очистим эти земли от синдикатской швали.", female = "Великолепно, героиня. Такими темпами мы мигом очистим эти земли от синдикатской швали." },
    ["567a"] = { common = "Внимание: вооружены и очень опасны! Следующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы: Клерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма. Горожанин Вилкс. Разыскивается за убийство аптекаря Эли. Шахтёр Хакетт. Разыскивается за убийство стража смерти Фрая. Фермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода. Все перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти." },
    ["567c"] = { male = "Да ты неплохой охотник за головами, герой.", female = "Да ты неплохой охотник за головами, героиня." },
    ["590a"] = { male = "Что? ЧТО?! Денег хочешь? Не должен я тебе никаких денег. Письмо? Какое письмо? Может, ещё и подерёмся? Ну, приятель, давай! Вот ещё, деньги я должен...", female = "Что? ЧТО?! Денег хочешь? Не должен я тебе никаких денег. Письмо? Какое письмо? Может, ещё и подерёмся? Ну, подружка, давай! Вот ещё, деньги я должен..." },
    ["590c"] = { common = "Невероятно! Какое мастерство! А я-то думал, ты будешь лёгкой добычей. Да, хорошенько ты меня отделал. Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." },
    ["729a"] = { common = "Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера. Но геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего. Мы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью. Прошу тебя, отправляйся на юг и посмотри, всё ли в порядке с геологом!" },
    ["729c"] = { male = "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу. Ой, да ты не Холли! Вряд ли ты видел мою щётку для камня... А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли? Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли... И ты кто будешь... правда, это неважно, если ты хочешь помочь. Дай знать, когда сможешь начать поиски.", female = "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу. Ой, да ты не Холли! Вряд ли ты видела мою щётку для камня... А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли? Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли... И ты кто будешь... правда, это неважно, если ты хочешь помочь. Дай знать, когда сможешь начать поиски." },
    ["730a"] = { male = "Приятно видеть! герой, интересующийся великими археологическими чудесами нашего мира! Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора. Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова. Отправляйся в Аубердин и узнай, где они предположительно могут находиться.", female = "Приятно видеть! героиня, интересующаяся великими археологическими чудесами нашего мира! Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора. Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова. Отправляйся в Аубердин и узнай, где они предположительно могут находиться." },
    ["730c"] = { common = "Как же здорово, что главный археолог Седой Ус прислал вас..." },
    ["731a"] = { male = "Итак, Холли... А, да, верно, ты же не Холли. А где Холли? Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь. Дай мне знать, когда будешь готов, и начнём поиски этой щётки... ну, то есть окаменелости! Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готов?", female = "Итак, Холли... А, да, верно, ты же не Холли. А где Холли? Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь. Дай мне знать, когда будешь готова, и начнём поиски этой щётки... ну, то есть окаменелости! Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готова?" },
    ["731c"] = { common = "Слава звёздам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твёрдо хочет остаться там, где рядом повсюду рыщут жуткие твари!" },
    ["741a"] = { common = "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнасс? Мне не хотелось бы уезжать с Тёмных берегов без него. Вот, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс." },
    ["741c"] = { common = "Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!" },
    ["742a"] = { common = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса! Орде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей. Она ждёт желающих принять участие в большой охоте!" },
    ["742c"] = { male = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", female = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." },
    ["743a"] = { male = "Спасибо, что выбрал время поговорить со мной. Я Руул, воин и учитель. Пришло время пройти испытания и покинуть Мулгор. Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги. Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.", female = "Спасибо, что выбрала время поговорить со мной. Я Руул, воин и учитель. Пришло время пройти испытания и покинуть Мулгор. Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги. Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе." },
    ["743c"] = { common = "Молодец. Похоже, ты готов двинуться дальше. Попутного тебе ветра!" },
    ["744a"] = { common = "Вскоре мой брат предстанет перед вождём Кровавым Копытом, и мне выпала большая честь сделать для него головной убор. Мне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом? Перья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утёса. Мне нужно всего-то шесть лазурных и шесть бронзовых перьев, чтобы закончить работу." },
    ["744c"] = { common = "Спасибо за помощь. Моё участие в церемонии в честь моего брата почти закончено. От меня требуется только подарить ему этот убор и быть свидетелем." },
    ["745a"] = { common = "Нашей земле причиняют боль раздоры её обитателей. Я надеюсь, что тебе не суждено видеть столько войн, сколько выпало мне. И всё же я вынужден просить тебя вступить в бой. Благодаря этому ты поймёшь, что малая угроза, если не искоренить её, со временем разрастается. Гноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора. Слова бессильны остановить их." },
    ["745c"] = { common = "Хорошо, что ты отнёсся к моему заданию со всей серьёзностью. Очень важно уважать землю и её обитателей. Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого. Обдумай это хорошенько и никогда не забывай." },
    ["746a"] = { common = "К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у неё надо учиться, а не осквернять бесконечными ямами. Собери инструменты дворфов, уничтожь их и принеси мне. Ломать инструменты можно в кузнице, которая есть в Громовом Утёсе, но подойдёт любая, даже та, что находится в дворфийском лагере." },
    ["746c"] = { common = "Спасибо. Звери Мулгора успокоятся. И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний." },
    ["747a"] = { male = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утёс. Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достоин этой чести. На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты способен, – поохоться на равнинных долгоногов и принеси мяса в деревню.", female = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утёс. Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достойна этой чести. На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты способна, – поохоться на равнинных долгоногов и принеси мяса в деревню." },
    ["747c"] = { common = "Таурены Нараче благодарят тебя. Я уверен, ты достигнешь больших высот." },
    ["748a"] = { common = "Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо. Для очищения колодцев придётся создать тотэмы, а ты пойдёшь с ними к колодцам и проведёшь очищающие ритуалы. Начнём мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы койотов и когти взрослых долгоногов. Эти звери живут на юго-западе." },
    ["748c"] = { common = "Молодец. Я вплету силу принесённых тобой вещей в тотэм Очищения." },
    ["749a"] = { common = "Несколько дней назад мы наткнулись на охраняемый караван Торговой компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван. Мы бросили их ящики с припасами, полагая, что наши факелы уничтожат всё ценное, но учитывая, что возле сожжённых телег видели мародёров Торговой компании, похоже, мы ошиблись. Быть может, ты сходишь к каравану и посмотришь, что в ящиках?" },
    ["749c"] = { common = "Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании." },
    ["750a"] = { common = "Любой искушённый в охоте таурен понимает, что её смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведёшь впечатление на старейшин, если принесёшь им несколько шкур горных пум – они у нас очень высоко ценятся! Нашим детям нужна одежда, да и шатры пора подлатать." },
    ["750c"] = { common = "Таурены из Нараче благодарят тебя за твои дары. Твоё охотничье искусство будет высоко цениться в Громовом Утёсе." },
    ["751a"] = { common = "Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг. Со стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров." },
    ["751c"] = { common = "Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать." },
    ["752a"] = { common = "Все члены племени живут вместе в мире и гармонии. Мы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. Моя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты её, пока я занимаюсь делами племени?" },
    ["752c"] = { male = "Ты проделал такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа. Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу.", female = "Ты проделала такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа. Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." },
    ["753a"] = { male = "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. Думаю, ты достойный герой. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.", female = "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. Думаю, ты достойная героиня. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." },
    ["753c"] = { male = "Ты принёс мне этот кувшин по просьбе Великой матери Соколиный Ветер. Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе.", female = "Ты принесла мне этот кувшин по просьбе Великой матери Соколиный Ветер. Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." },
    ["754a"] = { common = "Я создал тотэм для очищения колодца Заиндевевшего Копыта. Отнеси его туда и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины! Дело непростое, но кому-то придётся его сделать, иначе мы не сможем брать там воду. Удачи тебе." },
    ["754c"] = { common = "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой. Ты оказал большую услугу нашему краю. И всему народу тауренов." },
    ["755a"] = { male = "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны. Не сомневаюсь, придёт день, и тебя, герой, назовут одним из величайших. Но сначала ты должен пройти три обряда Матери-Земли. Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче.", female = "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны. Не сомневаюсь, придёт день, и тебя, героиня, назовут одной из величайших. Но сначала ты должна пройти три обряда Матери-Земли. Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." },
    ["755c"] = { common = "Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд..." },
    ["756a"] = { common = "Для создания Тотэма очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придётся тебе убить несколько охотников прерий и пум плоскогорья и принести мне их когти. Живут эти звери на востоке и на западе." },
    ["756c"] = { common = "Спасибо. Чтобы создать следующий очищающий тотэм, тебе придётся постичь, в чём разница между убийством ради пропитания и бессмысленной жестокостью. Гоблинам же не дано понять разницу между захватом земли и жизнью в гармонии с ней." },
    ["757a"] = { male = "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса. Сначала ты должен пройти обряд Силы. Чтобы выдержать это испытание, ты должен доказать свою храбрость, убивая врагов племени. Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.", female = "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса. Сначала ты должна пройти обряд Силы. Чтобы выдержать это испытание, ты должна доказать свою храбрость, убивая врагов племени. Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." },
    ["757c"] = { common = "Ты прошёл первый из обрядов Матери-Земли. Племя гордится тобой!" },
    ["758a"] = { common = "Тотэм готов. Тебе остаётся лишь провести ритуал очищения. Ступай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью тотэма очищения. После этого возвращайся ко мне. И да пребудут с тобой духи." },
    ["758c"] = { common = "Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца. Они просили передать тебе это в знак признательности…" },
    ["759a"] = { common = "Тебе осталось очистить лишь один колодец, названный в часть племени Буйногривых. Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий. Ступай на север, убей его и возвращайся. Могучие волки прерий водятся неподалёку от славного города Громового Утёса." },
    ["759c"] = { common = "Замечательно. Увы, нашей земле приходится приносить в жертву своих детей, и я исполняюсь печали и гордости." },
    ["760a"] = { male = "Духи говорят, что ты успешно очистил колодцы Заиндевевшего Копыта и Громового Рога, юный герой. Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания. Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой.", female = "Духи говорят, что ты успешно очистила колодцы Заиндевевшего Копыта и Громового Рога, юная героиня. Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания. Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой." },
    ["760c"] = { common = "Ты справился! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе. Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." },
    ["761a"] = { common = "Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – всё равно что медаль для охотника, говорящая о его уме и решимости. Если ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. Принеси мне их перья, и прославь свой клан этой победой. Перепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта." },
    ["761c"] = { common = "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живёшь у нас в деревне." },
    ["763a"] = { male = "Чтобы продолжить прохождение обрядов Матери-Земли, ты должен пройти ещё два испытания. Тебе бы не помешало поднабраться опыта. Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса. Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии. Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!", female = "Чтобы продолжить прохождение обрядов Матери-Земли, ты должна пройти ещё два испытания. Тебе бы не помешало поднабраться опыта. Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса. Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии. Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!" },
    ["763c"] = { male = "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты путник особой породы!", female = "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты путница особой породы!" },
    ["764a"] = { common = "Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой компании. Эти гоблины... Компания слишком быстро растёт, не жди добра. Как говорят, гоблинам палец в рот не клади. Маленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок." },
    ["764c"] = { common = "Думаю, такой намёк невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые." },
    ["765a"] = { male = "Согласно документам, которые ты отыскал в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить. Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нём чего полезного.", female = "Согласно документам, которые ты отыскала в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить. Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." },
    ["765c"] = { common = "Ярость немного отступила при вести о гибели злодея Шумовика. Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой Компании. Спасибо за помощь." },
    ["766a"] = { common = "Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах. И вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь мне нужны редкие части животных, чтобы вылечить воспалённую рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника. Торопись, время не ждёт." },
    ["766c"] = { common = "А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью. Но пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть… Будь осторожен во время своих странствий." },
    ["767a"] = { common = "Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утёса. Наш народ твёрдо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождём деревни, Зарельманом Две Луны." },
    ["767c"] = { male = "Я предчувствовал, что ты придёшь ко мне, герой. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.", female = "Я предчувствовал, что ты придёшь ко мне, героиня. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." },
    ["768a"] = { male = "Привет тебе, юноша. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесёшь ты честь своему клану! Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса. Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.", female = "Привет тебе, девица. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесёшь ты честь своему клану! Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса. Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." },
    ["768c"] = { common = "Ах, какая кожа! Из неё выйдут отличные товары. Вот. Возьми в знак благодарности..." },
    ["769a"] = { common = "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы. И тогда я поделюсь с тобой своими знаниями." },
    ["769c"] = { common = "Добро. Спасибо. Моё сердце распирает от гордости, когда я вижу молодёжь, взыскующую мастерства в кожевничестве!" },
    ["770a"] = { common = "На потрёпанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом. Может быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя..." },
    ["770c"] = { male = "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный герой. Оказывается, ты превосходный охотник! Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие. Пусть оно не знает промаха и дарует тебе славу. Будем надеяться, что дух Призрачного Воя упокоился с миром.", female = "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты выросла в моих глазах, юная героиня. Оказывается, ты превосходная охотница! Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие. Пусть оно не знает промаха и дарует тебе славу. Будем надеяться, что дух Призрачного Воя упокоился с миром." },
    ["771a"] = { common = "Чтобы пройти обряд Прозрения, тебе придётся собрать некоторые реагенты для создания воды Провидцев. Мне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли. В этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведёт тебя к следующему этапу священного обряда." },
    ["771c"] = { common = "Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." },
    ["772a"] = { common = "Я вручаю тебе воду Провидцев. Выпей её перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнёт видение. После этого следуй за ним навстречу своей судьбе..." },
    ["772c"] = { male = "Не бойся. Ты успешно прошёл Обряд прозрения.", female = "Не бойся. Ты успешно прошла Обряд прозрения." },
    ["773a"] = { male = "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости. Ты уже прошёл Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение. Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков.", female = "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости. Ты уже прошла Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение. Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." },
    ["773c"] = { male = "Ты приложил много стараний, чтобы пройти обряды Матери-Земли. Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс. Итак, я передаю тебе почётную обязанность хранить его от бед. Ты прошёл Обряд мудрости, юный герой. Отныне ты можешь с гордостью войти в Громовой Утёс.", female = "Ты приложил много стараний, чтобы пройти обряды Матери-Земли. Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс. Итак, я передаю тебе почётную обязанность хранить его от бед. Ты прошёл Обряд мудрости, юный героиня. Отныне ты можешь с гордостью войти в Громовой Утёс." },
    ["775a"] = { male = "Отныне тебя будут почитать в стенах нашего великого города. Прошедший обряды Матери-Земли заслуживает такой чести. Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе.", female = "Отныне тебя будут почитать в стенах нашего великого города. Прошедшая обряды Матери-Земли заслуживает такой чести. Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе." },
    ["775c"] = { male = "Привет тебе, юный герой. Вижу, тебе удалось отыскать дорогу ко мне.", female = "Привет тебе, юный героиня. Вижу, тебе удалось отыскать дорогу ко мне." },
    ["776a"] = { male = "Ты прошёл обряды Матери-Земли и заслужил достойное место среди жителей Громового Утёса. Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу. Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи.", female = "Ты прошла обряды Матери-Земли и заслужила достойное место среди жителей Громового Утёса. Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу. Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." },
    ["776c"] = { common = "Отлично! Добрая охота. Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо. Ты оказал своему народу услугу." },
    ["780a"] = { common = "Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. Пойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлёбку для наших детишек!" },
    ["780c"] = { common = "Прекрасно! Мы сварим отличную похлёбку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком." },
    ["781a"] = { common = "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения клана Дыбогривов на Лагерь Нараче. Вождь Соколиный Ветер непременно должен об этом узнать!" },
    ["781c"] = { male = "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спас жизни многих тауренов.", female = "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спасла жизни многих тауренов." },
    ["783a"] = { male = "Надеюсь, ты готов к подвигам, герой, поскольку для тебя есть дело здесь, в Североземье. И я имею в виду не мирные сельские заботы. Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких. Если ты готов откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной.", female = "Надеюсь, ты готова к подвигам, героиня, поскольку для тебя есть дело здесь, в Североземье. И я имею в виду не мирные сельские заботы. Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких. Если ты готова откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной." },
    ["783c"] = { common = "Отлично. Ещё один доброволец. В эти дни у нас много таких, как ты. Надеюсь, нам хватит бойцов. Землям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам. И из-за этого бандитские шайки вольготно чувствуют себя в наших землях. Нам приходится воевать на много фронтов... Готовьтся к долгой войне." },
    ["784a"] = { common = "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда. Вторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров! Покажи свою доблесть. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей." },
    ["784c"] = { male = "Твоя отвага скоро станет известна всем, герой! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.", female = "Твоя отвага скоро станет известна всем, героиня! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." },
    ["785a"] = { common = "Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани. Тролли из племени Чёрного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне. И вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы. Разыщи Лара и спроси, не нужна ли ему помощь." },
    ["786a"] = { male = "Говори потише, герой! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара. Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара! Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбр, чтобы напасть на Утёс Колкара и уничтожить их планы? Я заметил, что они хранятся у трёх лидеров кентавров.", female = "Говори потише, героиня! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара. Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара! Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбра, чтобы напасть на Утёс Колкара и уничтожить их планы? Я заметил, что они хранятся у трёх лидеров кентавров." },
    ["786c"] = { male = "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь. А кровопролитий в эти смутные времена и без того хватает. Ты хорошо послужил своему народу, герой.", female = "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь. А кровопролитий в эти смутные времена и без того хватает. Ты хорошо послужил своему народу, героиня." },
    ["787a"] = { male = "Тром'ка, герой! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов. Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся. Горнек скажет тебе, что делать дальше.", female = "Тром'ка, героиня! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов. Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся. Горнек скажет тебе, что делать дальше." },
    ["787c"] = { common = "Ещё один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно. К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой." },
    ["788a"] = { male = "Вот тебе первое поручение, чтобы ты набрался опыта и показал себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему. Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.", female = "Вот тебе первое поручение, чтобы ты набралась опыта и показала себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему. Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." },
    ["788c"] = { male = "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами. Однако ты показал себя достойным бойцом. В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает.", female = "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами. Однако ты показала себя достойным бойцом. В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." },
    ["789a"] = { common = "Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне десять их хвостов, чтобы доказать свою воинскую доблесть. Из яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя... Но тебе-то оно не понадобится, а?" },
    ["789c"] = { common = "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого. Ну что ж! Я научил тебя всему, чему мог. Ты оказалась хорошим учеником. Я буду с интересом следить за твоей карьерой." },
    ["790a"] = { male = "герой! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу. А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...", female = "героиня! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу. А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда..." },
    ["790c"] = { common = "Да, убить его мне не удалось, но ранил я его серьёзно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берёт!" },
    ["791a"] = { common = "Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путём. Я сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне всё реже и реже приходится трубить в сигнальный рог. А чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину. Я могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров." },
    ["791c"] = { common = "Отлично! Такая сумка пригодится любому хорошему бойцу. Я отдаю честь твоей силе и решимости умереть во имя Орды!" },
    ["792a"] = { male = "Что ж, герой, надеюсь, у нас ты многому научишься. Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно! В долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос. Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.", female = "Что ж, героиня, надеюсь, у нас ты многому научишься. Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно! В долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос. Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." },
    ["792c"] = { common = "Молодец! Да, злобные фамильяры для злодеев из Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предрекает великие события!" },
    ["794a"] = { common = "С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и чёрная магия. Этот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена. Но берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамильяры, с которыми тебе уже доводилось встречаться! Ступай. Грот находится к северо-западу отсюда." },
    ["794c"] = { common = "Он у тебя! Молодец! Теперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях. Так что эта встреча с ними была не последней." },
    ["804a"] = { male = "То, что ты сделал ради меня, заставило меня воспрянуть духом. Я ещё повоюю! Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.", female = "То, что ты сделала ради меня, заставило меня воспрянуть духом. Я ещё повоюю! Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь." },
    ["804c"] = { common = "Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот! Неудивительно, что Хана'зуа с ним не справился. Не тревожься о нём, помощь уже в пути. Однако, нужно сказать, я тебя зауважал. Неужели тебе действительно удалось одолеть Саркота? Это немалый подвиг, тебе есть чем гордиться. А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь." },
    ["805a"] = { common = "Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь. Ступай в тролльскую деревню Сен'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо. Расскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний. Узнай, не видно ли их в Сен'джине. Ступай, и не медли в пути! Боюсь, появление Пылающего Клинка в долине – это только первая ласточка..." },
    ["805c"] = { common = "Хм... Как это всё не вовремя! Нет, у нас в Сен'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло. Орки – друзья троллей Чёрного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!" },
    ["806a"] = { common = "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползётся по нашей земле! Я провёл расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос! Найди Пшикса, убей его и принеси мне его коготь в качестве доказательства." },
    ["806c"] = { male = "Ага! Ты его убил! Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше.", female = "Ага! Ты его убила! Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше." },
    ["808a"] = { common = "Я слышу голос моего брата, Миншины. Он взывает ко мне из снов. Его захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мёртв. Но смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена не вечные страдания. Прошу тебя, отыщи этот круг и похить череп Миншины. Принеси его мне. Освободи его!" },
    ["808c"] = { common = "Спасибо! Тебе удалось спасти Миншину! Дух моего брата избавлен от рабства!" },
    ["809a"] = { common = "Со времён последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков. И принесённый тобой ошейник подтверждает мои опасения! Он принадлежит Пылающему Клинку, культу, объединённому вокруг предмета, который наделён демонической силой. Этот предмет называется Демоново Семя, и находится он в Степях, на вершине Багрового Тумана. Его необходимо уничтожить! Отправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом. Он скажет тебе, что делать дальше." },
    ["809c"] = { common = "Вот как? Ниру хочет, чтобы Демоново семя было уничтожено? Странно… Что ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя." },
    ["812a"] = { common = "А... Ты как нельзя вовремя! Надеюсь на твоё проворство. Я сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь! Коргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее! Долго мне не протянуть. Ищи его в расселине Теней." },
    ["812c"] = { common = "Ты спас мне жизнь! Спасибо тебе. Прошу тебя, возьми эту вещь. Денег за неё не выручишь, но, надеюсь, она пригодится тебе в странствиях. Судя по тому, что ты говоришь, мне она пригодится нескоро. Кор'гхан подвергнет меня ещё множеству своих ритуалов, пока я не сумею показать, на что способен. Снова охотиться на вепрей, собирать хвосты скорпидов... вздыхает" },
    ["815a"] = { common = "Ба! А я и позабыл, что надо готовить завтрак. Слушай, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки. Имей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен'джин, там эти яйца лежат повсюду." },
    ["815c"] = { common = "Ну, может, ты и слабак но уж ловкости и проворства тебе не занимать! На вот, возьми за труды и проваливай. Мне готовить надо!" },
    ["816a"] = { common = "Прошу тебя, может, хоть ты сумеешь мне помочь? Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушёл на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я опасаюсь худшего… Крон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью. Если не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придётся заглянуть в брюхо каждому кроколиску на берегах Строптивой!" },
    ["816c"] = { common = "Ох, сыночек... милый мой сыночек… Что ж, я не знала судьбы своего сына и потому терзалась понапрасну. Теперь же я хоть смогу его оплакать… Спасибо тебе. Прошу тебя, возьми этот плащ. Я-то собиралась подарить его Крону, когда он вернётся с добычей... А теперь, зная, что он погиб, я даже не смогу смотреть на него." },
    ["817a"] = { common = "У нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их. В общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры. Принеси мне четыре шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда." },
    ["817c"] = { common = "Молодец! Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима. Спасибо тебе." },
    ["818a"] = { male = "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо. И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков. Что? Ты достоин? Ну да, конечно... Это ты так думаешь. Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть? Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим.", female = "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо. И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков. Что? Ты достойна? Ну да, конечно... Это ты так думаешь. Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть? Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим." },
    ["818c"] = { common = "Отличная работа! Ты молодец!" },
    ["819a"] = { common = "Маленькая табличка на торце одной из бочек гласит: \"Чэнь Буйный Портер – Да будет ваш дух горяч, а кружка – полной.\"" },
    ["819c"] = { male = "Ну, я… Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принёс мне этот бочонок.", female = "Ну, я… Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принесла мне этот бочонок." },
    ["821a"] = { common = "Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит! Принеси мне пять клыков равнинного льва, пять почек долгонога и один рог рокочущей ящерицы. Из них выйдет прекрасный портер. Все эти составляющие нетрудно отыскать в Степях." },
    ["821c"] = { common = "Ха-ха... Вот уж не думал, что снова сварю этот напиток! Прямо ностальгия охватила. Сразу вспомнилось, как я наварил троггского пойла. Спасибо. От воспоминаний даже на душе посветлело." },
    ["823a"] = { male = "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем. В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнал в долине Испытаний. Ему нужно это знать. Колючий Холм находится к северу отсюда.", female = "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем. В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнала в долине Испытаний. Ему нужно это знать. Колючий Холм находится к северу отсюда." },
    ["823c"] = { common = "Да? Тебе есть, о чём доложить? Ну так рассказывай, чего ты ждёшь?!" },
    ["825a"] = { common = "Один из моих лучших разведчиков принёс сообщение, что обломки кораблей Праудмура всё ещё плавают около побережья Дуротара, к востоку от крепости Тирагард. Ни для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать всё о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу. Сплавай к обломкам, и добудь мне инструменты Альянса." },
    ["825c"] = { male = "Ты успешно выполнил поручение, герой. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном.", female = "Ты успешно выполнила поручение, героиня. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном." },
    ["826a"] = { common = "Знахарь Залазан живёт на островах Эха на востоке. Эти острова мы когда-то называли родиной… А теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону всё новых приспешников. Его нужно остановить! Уничтожь Залазана и его слуг – бывших троллей из племени Чёрного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришёл конец." },
    ["826c"] = { common = "Залазана больше нет, наше племя снова может спать спокойно! Спасибо. Племя Чёрного Копья многим тебе обязано. Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом'бею, который находится позади меня. Он силён в магии вуду…" },
    ["827a"] = { male = "путник! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками. Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников. Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники. Принеси их мне, и я раскрою их тайну!", female = "путница! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками. Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников. Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники. Принеси их мне, и я раскрою их тайну!" },
    ["827c"] = { common = "Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!" },
    ["828a"] = { common = "Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка. Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка. Прежде чем отправиться к скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться. Ты найдёшь его на северо-востоке, между побережьем и Сухой лощиной. Следуй его советам, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!" },
    ["828c"] = { male = "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающая герой. Не сворачивай с этого пути, и великое будущее будет ждать тебя!", female = "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающая героиня. Не сворачивай с этого пути, и великое будущее будет ждать тебя!" },
    ["829a"] = { common = "Принесённые тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник. Отнеси один обжигающий ошейник Нииру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а ещё говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам ещё может понадобиться в борьбе с последователями демонов в Дуротаре. Нииру можно найти в Оргриммаре, в Расселине Теней." },
    ["829c"] = { common = "О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно? Ну-ка, дай взглянуть..." },
    ["830a"] = { common = "Вы открываете потрёпанный и выгоревший конверт и обнаруживаете документ официального вида. На нём – печать адмирала Праудмура. Похоже, это что-то важное. Может быть, Га'току, командиру Колючего Холма, эта информация пригодится..." },
    ["830c"] = { common = "Ничего хорошего это не предвещает... Очень хорошо, что ты принёс это мне." },
    ["831a"] = { common = "Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут. Адмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел изложить свои планы на бумаге, прежде чем встретил заслуженную смерть. Его наследие не пропадёт даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега? Эти приказы нужно немедленно доставить в Оргриммар, Назгрелу! Ты найдёшь его в зале приёмов Тралла." },
    ["831c"] = { male = "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости. Ты достойно послужила Орде, герой. А теперь извини, мне нужно немедленно поговорить об этом с Траллом!", female = "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости. Ты достойно послужила Орде, героиня. А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" },
    ["832a"] = { common = "Слова из амулета плавно перетекают в ваш разум. Газз'уз! Газз'уз, докладывай! О том, что ты нашёл в Скале Черепа, уже стало известно. Готовься к нападению! Говори, Газз'уз! Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит! С Нииру тебе лучше не связываться... Газз'уз, ты меня слышишь?" },
    ["832c"] = { common = "Нииру разглядывает Око Пылающей Тени. Любопытно. Так ты говоришь, голос упоминал моё имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашёл этот амулет, так похоже на мою фамилию. Надо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение. Спасибо, что сообщил мне об этом. Ты оказал своему народу серьёзную услугу." },
    ["833a"] = { male = "Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей. Похоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. Против них поможет только сила, герой.", female = "Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей. Похоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. Против них поможет только сила, героиня." },
    ["833c"] = { male = "Молодец. Ты проучил племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места.", female = "Молодец. Ты проучила племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места." },
    ["834a"] = { common = "Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Всё бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны всё время грабят? Последний караван – они мне клялись, что он-то уж точно дойдёт! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра! А мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток..." },
    ["834c"] = { common = "О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесёт мне эти мешки." },
    ["835a"] = { common = "Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\". Мы не можем и дальше терять караваны. Я вынужден взять дело в собственные руки. Сухая лощина находится в восточной части Каньона Колючего Ветра. Если перебить всех тамошних гарпий, дороги станут безопасными. Разумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, возьмёшься?" },
    ["835c"] = { common = "Ну всё, теперь нашим караванам больше ничто не угрожает! Наконец-то я вздохну свободно. Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек! Ты, своё дело знаешь. Обратись к моему шефу в Кабестане. У него наверняка найдётся для тебя работёнка. Ах да, не беспокойся, разумеется, я тебе заплачу за труды!" },
    ["837a"] = { common = "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно. Однако, с нас довольно! Ради нашей безопасности мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!" },
    ["837c"] = { common = "Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее." },
    ["840a"] = { male = "Хм, слабаком тебя не назовёшь… Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс. Передай Каргалу это письмо о найме – возможно, он его подпишет.", female = "Хм, слабенькой тебя не назовёшь… Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс. Передай Каргалу это письмо о найме – возможно, он его подпишет." },
    ["840c"] = { common = "А, так тебя Такрин прислал? Он отличный разведчик, не знаю даже, что бы я без него делал… Письмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрёстке." },
    ["842a"] = { male = "Отнеси это подписанное письмо о найме в Перекрёсток. Там всем заправляет – Сергра Чёрный Шип, лопни её шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сам, парень...", female = "Отнеси это подписанное письмо о найме в Перекрёсток. Там всем заправляет – Сергра Чёрный Шип, лопни её шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сама, детка..." },
    ["842c"] = { common = "Ладно. Не хочешь есть свой хлеб в Орде даром? Что ж, дел у нас предостаточно. Просто слушай внимательно и делай, что тебе скажут. Имей в виду, я по глазам вижу, что у тебя на уме. Наглости я не спущу! Тралл самолично заявил, что в Орде женщины во всём будут наравне с вами, мужиками. Только попробуй проявить ко мне неуважение – узнаешь, почём фунт лиха!" },
    ["843a"] = { common = "Ныне я брожу по дорогам родного края в одиночестве. Дворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие моё племя, захвачены вредоносными дворфами. Все попытки решить дело миром провалились. Пришло время для решительных действий. Выгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря." },
    ["843c"] = { common = "Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным. Быть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой. Дай-ка я изучу записи этого дворфа..." },
    ["844a"] = { common = "Первое задание будет совсем простым. Равнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет! Перебей несколько долгоногов и принеси мне их клювы." },
    ["844c"] = { common = "Хорошо. Долгоногов перебили, и нам будет проще доставлять продовольствие. Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги..." },
    ["845a"] = { common = "Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов. Не беспокойся, в своё время тебе и покрупнее дичь достанется, но пока тебе ещё надо малость поточить зубки. Поохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьёзнее." },
    ["845c"] = { common = "Неплохо. У жевр сильные ноги. Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону! Похоже, в тебе тоже силы хватает. Ну что, готов пройти настоящее испытание?" },
    ["846a"] = { common = "Очевидно, что шахтёры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину. Пусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости. Собери всё необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!" },
    ["846c"] = { male = "Вижу, ты зря времени не терял, герой. Очень скоро дворфов ожидает неприятный сюрприз!", female = "Вижу, ты зря времени не терял, героиня. Очень скоро дворфов ожидает неприятный сюрприз!" },
    ["848a"] = { common = "Оазисы Степей таят в себе тайну. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных. И меняющая их. Неподалёку от этих оазисов растёт вид грибов, чьи споры мы, аптекари Лордерона, используем при создании снадобий. Принеси мне эти споры – и благодарность наша будет велика." },
    ["848c"] = { common = "Ах, да. Прекрасный материал. Действенный. Я из Отрёкшихся, а мы исполняем свои обещания. Вот твоё вознаграждение." },
    ["849a"] = { common = "Изучив схемы Хазгорма, можно без труда создать взрывчатку. Ну вот, готово. А теперь, я дам тебе особое задание. Возьми взрывчатку и подорви летающую машину в Бейл Модане. Эта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что ещё важнее – она воплощение мощи дворфов и оскорбление памяти моего племени. Выполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь." },
    ["849c"] = { common = "Отличная работа. В Громовом Утёсе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени." },
    ["850a"] = { common = "Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьёз грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско. Чтобы сохранить наши земли, мы должны убить вождей кентавров. Принеси мне голову Барака Кодобоя. Он живёт в лагере неподалёку от Забытых прудов на севере. Когда одержишь над ним верх, возвращайся." },
    ["850c"] = { common = "Молодец. Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой. Они-то опаснее прочих. Барак таким и был. Хорошо, что он мёртв." },
    ["851a"] = { common = "Кентавр Верог Дервиш бродит по Пустошам, и найти его будет нелегко. Живёт же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке. Быть может, удастся заманить его туда. Отправляйся в Застывший оазис и напади на кентавров рядом с командным шатром. Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог. Принеси мне его голову, и я помещу её рядом с головой Барака Кодобоя." },
    ["851c"] = { common = "Замечательно. Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса. Наверное, это твоя работа. Можешь гордиться своим подвигом. Ты необыкновенно отважен." },
    ["852a"] = { male = "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр. Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам. Итак, убей его. Принеси мне его голову, как принёс головы Барака и Верога. Он управляет своим народом из Цветущего оазиса на юге.", female = "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр. Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам. Итак, убей его. Принеси мне его голову, как принесла головы Барака и Верога. Он управляет своим народом из Цветущего оазиса на юге." },
    ["852c"] = { common = "Хвала тебе. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники. Одержав над ними верх, ты доказал свою доблесть." },
    ["853a"] = { common = "Я сделал эмульсию из принесённых тобой спор, и теперь мне нужно доставить её моей коллеге, аптекарю Заме. Если ты отнесёшь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров. Она живёт в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утёса. Путь к этой пещере хорошо скрыт, но начинается он на Вершине духов. Поспеши. Эмульсия хранится не очень долго, потому надо вскрыть и использовать её до того, как она испортится." },
    ["853c"] = { male = "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо. Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, герой.", female = "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо. Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, героиня." },
    ["854a"] = { male = "Я знал, что ты придёшь, юный герой. Хотя, пожалуй, ты уже не так юн. Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрёстку. Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли.", female = "Я знал, что ты придёшь, юная героиня. Хотя, пожалуй, ты уже не так юна. Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрёстку. Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." },
    ["854c"] = { common = "Я рад, что нам на помощь прибыли союзники из самого Громового Утёса. Добро пожаловать!" },
    ["855a"] = { common = "Клан Колкар угрожает завоеваниям Орды в Степях. Мы должны сократить численность их войск. В связи с этим у меня есть для тебя задание. Отправляйся в земли Колкар, перебей их воинов и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит." },
    ["855c"] = { common = "Неплохо. Уверен, тебе удалось вселить страх в выживших кентавров. Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление. К сожалению, вряд ли им на это хватит ума. Что весьма плохо. Плохо для них, разумеется." },
    ["857a"] = { common = "Она была у меня в руках! В этих самых руках! И я хочу вернуть её! Вернуть, говорю! Её откопали эти грязные землекопы... и как она была прекрасна. Её назвали слеза Лун. Первое серьёзное открытие в Бейл Модане. Она должна достаться мне! Мне, говорю! Генерал Двукосса позавидовал силе, которую она мне давала, и запер её в Крепости. Сказал, что эта вещь проклята. Дурак! Её хотели заполучить и другие, мне пришлось их остановить. А этот ублюдок Двукосса прогнал меня. А я хочу её вернуть. Вернуть, говорю!" },
    ["857c"] = { common = "Наконец-то сила снова со мной! Со мной, говорю!" },
    ["858a"] = { common = "Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска резака нужен ключ. Один из операторов спросил меня, всё ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я потерял ключ, я заявил, что резак неисправен. Надо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира должен быть ключ от резака. Выручи меня!" },
    ["858c"] = { common = "Ага, похоже, ключ подходит. Ну-ка, знаю ли я, как управлять этой штуковиной… Хм... Управление вращением... Этот рычаг отвечает за скорость и равновесие... Управление манипулятором. Ну и ну! Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего. Надо доставить этот резак в Кабестан!" },
    ["860a"] = { common = "Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет. Поговори с Сергрой Чёрный Шип. Она будет первой твоей наставницей в Степях. Сергра сейчас в Перекрёстке. Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных." },
    ["860c"] = { common = "Хочешь охотиться в Степях? Глаза у тебя горячие и молодые. Они ещё не окосели от выслеживания добычи на тутошних пыльных равнинах. Но ты не бойся. Мы закалим твоё тело и дух! И растолкуем, что охота – не просто выслеживание и добыча. Готовься. Твой путь начинается прямо сейчас." },
    ["861a"] = { male = "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий… Странствий и охоты. Ведь охота – первая доблесть таурена. Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живёт в Громовом Утёсе, на вершине Охотников. Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для молодого героя, избравшего путь охотника.", female = "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий… Странствий и охоты. Ведь охота – первая доблесть таурена. Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живёт в Громовом Утёсе, на вершине Охотников. Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для молодой героини, избравшей путь охотника." },
    ["861c"] = { common = "Скорн Белое Облако – мудрый таурен. Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр. Мы высоко чтим его. Если тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника. Добыть же эти когти было непросто, я знаю. Быть может, тебе пора вступить на избранный путь." },
    ["862a"] = { male = "Должно быть, герою вроде тебя в Степях голодно. Я вот постоянно хочу есть. Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс. Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс. Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!", female = "Должно быть, героине вроде тебя в Степях голодно. Я вот постоянно хочу есть. Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс. Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс. Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!" },
    ["862c"] = { male = "Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден. Дай-ка я сварю тебе похлёбку из пещерных крыс. Ну вот, готово. Кушай на здоровье!", female = "Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голодна. Дай-ка я сварю тебе похлёбку из пещерных крыс. Ну вот, готово. Кушай на здоровье!" },
    ["863a"] = { common = "Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?" },
    ["863c"] = { common = "Надеюсь, нам удастся найти что-нибудь ценное в этом поломанном образце крошшера... Время на исходе! Я отправлю спасательную экспедицию на помощь к Визлкранку. А, вот тебе за труды." },
    ["865a"] = { common = "Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\". Я мог бы продавать его за баснословные деньги!!! Ты можешь мне помочь. Принеси мне целые рога ящерочешуйчатых смертехватов. Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса." },
    ["865c"] = { common = "Здорово, тебе удалось их добыть! Остаётся стереть рога в порошок, смешать с вином и..." },
    ["866a"] = { common = "Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они всё же отличаются от подобных им, хоть и не сильно. Я хочу выяснить, в чём же состоит разница... и нельзя ли ей воспользоваться! Если ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов." },
    ["866c"] = { male = "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства... И не беспокойся – ты узнаешь об этом первым. Потому что в таком случае мне понадобится много корней!", female = "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства... И не беспокойся – ты узнаешь об этом первой. Потому что в таком случае мне понадобится много корней!" },
    ["867a"] = { common = "Нет сил терпеть нападения на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому. Я пробрался к их гнёздам и выяснил, кто есть кто. Начать надо с низов, а потом постепенно пробиваться наверх. Для начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне восемь когтей Зачарованного Крыла. Будет уже неплохо..." },
    ["867c"] = { common = "Прекрасные когти. Чудные. Отличная работа. Надеюсь, в ближайшем будущем мне снова доведётся полюбоваться на твою работу." },
    ["868a"] = { common = "Эй. Меня отправили в Перекрёсток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится. В частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных. Возьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь." },
    ["868c"] = { common = "Порадовал ты меня. Молодец. Вот твоя награда..." },
    ["869a"] = { common = "Недавно из сторожевой башни был похищен груз серебра. Он предназначался в уплату стражам Перекрёстка, и его необходимо вернуть. Самое странное... одного из воров мы поймали с поличным. И... это оказался ящер! Немыслимо! Не знаю, зачем ящерам серебро. Мне всё равно: главное, чтобы у нас не воровали. Пусть сдохнут! Отправляйся на охоту в Степи. Принеси мне их головы!" },
    ["869c"] = { male = "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный герой.", female = "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный героиня." },
    ["870a"] = { common = "Давным-давно Степи были цветущим садом, полным жизни. Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню. Это наполняет моё сердце грустью, но так уж получилось. Впрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь. Мы, друиды, чувствуем, что из глубины к поверхности рвётся какая-то сила. Мы должны обнаружить её источник. Отправляйся к Забытым прудам, к северу от Перекрёстка. Отыщи в воде источник силы и возвращайся сюда." },
    ["870c"] = { common = "Там есть расселина, из которой выходят пузырьки газа? Странно. Может быть, это и есть ответ на наши вопросы, но уверенности нет. Впрочем, хоть какая-то зацепка. Спасибо, что нашёл её." },
    ["871a"] = { common = "Все свинобразы – наши враги. Просто одни из них причиняют нам больше неприятностей, чем другие. Клан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесём эти свиньям, тем лучше. Ступай на северо-восток, по направлению к Дуротару. Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли. Отыщи их и убей, кого сможешь." },
    ["871c"] = { common = "Отличная работа. Мерзавцы-иглоривы наконец-то научатся считаться с мощью Орды." },
    ["872a"] = { common = "Один из разведчиков своими глазами видел нападение на караван из Дуротара. Естественно, виноваты свинобразы из племени Иглогривых. Возглавляет нападения Криниг Грознорыл. Его видели на северо-востоке отсюда, южнее дороги на Дуротар. Пока Криниг жив, покоя не будет. Но чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов. Убей Кринига Грознорыла и его приспешников и принеси мне его клык." },
    ["872c"] = { common = "Молодец. Криниг мёртв, и число нападений на караваны сократится. Твой народ должен гордиться тобой." },
    ["873a"] = { male = "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа. Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник. Если ты готов, плыви на поиски Иши Авака, Рока Глубин. Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе.", female = "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа. Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник. Если ты готова, плыви на поиски Иши Авака, Рока Глубин. Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." },
    ["873c"] = { common = "Теперь вы с Иши Аваком едины. Его дух живёт в тебе. Он таится в твоих глазах… Глазах, которые однажды научатся видеть." },
    ["874a"] = { male = "Ты поохотился на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море. Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя. Ищи её с осторожностью, потому что побережье Степей захвачено людьми.", female = "Ты поохотилась на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море. Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя. Ищи её с осторожностью, потому что побережье Степей захвачено людьми." },
    ["874c"] = { male = "Тебя прислал мой брат? Должно быть, ты произвёл на него впечатление. А если тебя зауважал Джорн, то и я буду уважать. Желаешь ли ты сделать следующий шаг на пути охотника?", female = "Тебя прислал мой брат? Должно быть, ты произвела на него впечатление. А если тебя зауважал Джорн, то и я буду уважать. Желаешь ли ты сделать следующий шаг на пути охотницы?" },
    ["875a"] = { male = "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать. На сей раз я хочу, чтобы ты убил несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству. И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой.", female = "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать. На сей раз я хочу, чтобы ты убила несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству. И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой." },
    ["875c"] = { common = "Прекрасная работа. Думаю, ты достигнешь высокого положения в Орде." },
    ["876a"] = { male = "Ты так хорошо справился с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение. Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры. Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.", female = "Ты так хорошо справилась с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение. Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры. Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." },
    ["876c"] = { common = "ХА! Молодец! Отличная работа... Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать. Ещё раз спасибо за избавление от нашествия гарпий. Вот награда, используй её с умом." },
    ["877a"] = { common = "Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов. Надо проверить. Вот, возьми эти семена. Сейчас они мёртвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в неё семена... и понаблюдай." },
    ["877c"] = { common = "Удивительное открытие! Я дал тебе иссохшие, мёртвые семена. Значит, то, что таится в этих оазисах, создаёт жизнь из ничего! Необходимо исследовать это явление повнимательнее..." },
    ["878a"] = { common = "Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землёй и её мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны. Если ты в самом деле хочешь узнать, кто причинил Торку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи." },
    ["878c"] = { male = "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, путник. Но нет, радости нет места. фыркает Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке! Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!", female = "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, путница. Но нет, радости нет места. фыркает Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке! Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" },
    ["879a"] = { male = "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, путник. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает* Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, путник, как они убили меня.", female = "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, путница. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает* Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, путница, как они убили меня." },
    ["879c"] = { male = "Дело сделано. Кривозуб считает, уж лучше так. фыркает Надо было убедиться фыркает, что я мёртв, а не бросать меня здесь, во всеми забытой клетке. Тебе осталось лишь одно дело, путник.", female = "Дело сделано. Кривозуб считает, уж лучше так. фыркает Надо было убедиться фыркает, что я мёртв, а не бросать меня здесь, во всеми забытой клетке. Тебе осталось лишь одно дело, путница." },
    ["880a"] = { common = "Ты рассказываешь невероятные вещи. Источник свойств этих оазисов явно сторонний. Или, быть может, вообще потустороннй. Я хочу узнать, какое влияние расселины оказывают на зверей, приходящий на водопой. Убей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах. Принеси мне их панцири, и я их пристально изучу." },
    ["880c"] = { common = "Спасибо. Изучая обитателей различных мест, узнаешь немало о самих местах. Посмотрим, о чём нам поведают панцири. Прошу тебя, прими благодарность за помощь... Быть может, эти монеты тебе не помешают. Мне они уже не нужны." },
    ["881a"] = { common = "Ичияки, Белый Туман на языке тауренов, король кошачьих саванны. Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелящемуся над землёй. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли. Таурены говорят, что он воплощает собой милосердие и смерть. Ты узнаешь это на своём опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается на северо-востоке от Перекрёстка, среди костей огромного кодо. Ступай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов." },
    ["881c"] = { male = "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии. Перед тобой долгий путь, герой. Хочется верить, что ты далеко пойдёшь.", female = "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии. Перед тобой долгий путь, героиня. Хочется верить, что ты далеко пойдёшь." },
    ["882a"] = { male = "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе. Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала. Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на её запах. Будь готов к его появлению.", female = "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе. Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала. Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на её запах. Будь готова к его появлению." },
    ["882c"] = { common = "Клык – всего лишь символ, но символ очень важных вещей. Теперь в тебе есть сила Ишамухала. Пользуйся ей, но соблюдай умеренность. Отныне это твоя ноша. И это великая честь." },
    ["883a"] = { common = "Копыто Лакота'мани – символ силы великого кодо." },
    ["883c"] = { common = "Лакота'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны. Теперь он пребывает с тобой, к тебе перешло всё его мужество. Отныне ты не побоишься встретиться с любой опасностью. Верь в себя. Верь в себя, Землекрушитель." },
    ["884a"] = { common = "При касании от хвоста Оватанки летят искры." },
    ["884c"] = { male = "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой. Ныне её неутомимость передалась тебе. Теперь ты не отстал бы от Оватанки.", female = "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой. Ныне её неутомимость передалась тебе. Теперь ты не отстала бы от Оватанки." },
    ["885a"] = { common = "Пера Ваште Пауни больно касаться." },
    ["885c"] = { male = "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок. Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу. Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений. Впрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познал.", female = "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок. Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу. Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений. Впрочем, я вижу, что ты справилась с этими искушениями и познала, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познала." },
    ["886a"] = { common = "Друиды Громового Утёса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора. Мы отправили найти источник этой силы Тонгу Рунического Тотэма, но, похоже, ему нужна помощь. Отправляйся в Степи и поговори с Тонгой. Он будет в Перекрёстке. Иди туда по дороге на восток от Деревни Кровавого Копыта. Как попадёшь в Степи, сверни на развилке на север. И продолжай идти, пока не упрёшься в Перекрёсток. С дороги не сходи, ибо Степи – край суровый." },
    ["886c"] = { male = "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный герой. Ибо тайну Степей мне в одиночку не раскрыть. Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос.", female = "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный героиня. Ибо тайну Степей мне в одиночку не раскрыть. Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." },
    ["887a"] = { common = "Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей. В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары! Говорят, что флибустьеры Южных морей разбили лагерь к югу отсюда. Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?" },
    ["887c"] = { common = "Молодец, малыш. Побольше таких подвигов, и у меня станет одной проблемой меньше. Хочется верить, что они решат перенести свой лагерь. Остаётся одно – вернуть украденные товары!" },
    ["888a"] = { common = "Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны! Как видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской бухты! Ступай в пиратский лагерь и поищи их." },
    ["888c"] = { common = "Я так рад, что вернул своё добро! Спасибо за помощь. Знаешь, мне пригодились бы помощники вроде тебя. Если понадобится работа, не забывай, что Газлоу неплохо платит!" },
    ["890a"] = { common = "Я уже сто лет жду последнего заказа из Пиратской бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Дыбоволоса, вдруг товары без моего ведома отнесли на склад? Вот, отнеси мою учётную книжку Головокружилкинсу, пусть сверит со своими записями." },
    ["890c"] = { common = "А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда. Небось, он ждёт поставку сапог от Дриззлика..." },
    ["891a"] = { common = "Вот и ещё один мой корабль захватили рьяные людишки из крепости Северной стражи! Пора разобраться с этими мерзавцами. Их паранойя перешла все мыслимые границы. Эти безрассудные любители спускать курок стреляют во всё, что движется. Отправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе. Принести в доказательство собственных подвигов медали их солдат. И во имя моего флота, убей капитана Гордостанную и её рьяных канониров!" },
    ["891c"] = { common = "Ах, какая жалость, праведные пушки Альянса умолкли. Ты получишь награду за помощь. Как бы теперь выручить тела наших погибших..." },
    ["892a"] = { common = "У меня в записях всё в порядке. Ступай к Газулу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. Я ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает." },
    ["892c"] = { common = "Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чём, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку. Похоже, мне придётся вернуть себе кое-какие товары. Что скажешь?" },
    ["893a"] = { common = "Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьёзное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы. Если ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!" },
    ["893c"] = { common = "Прекрасные, прекрасные образцы. Свинобразы куда более умелый народ, чем мне казалось. Вот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы." },
    ["894a"] = { common = "Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\". Что ещё за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить. Мне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала." },
    ["894c"] = { common = "На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны один-три открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина." },
    ["895a"] = { common = "РОЗЫСК! Разыскивается Барон Дольноберег, капитан \"Безрассудной\". Капитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях. Предоставленные останки должны быть пригодны для опознания! - Газул." },
    ["895c"] = { common = "А! Вот какое у тебя дело. Знаешь, я однажды видел \"Безрассудную\" в открытом море. Впечатляющий корабль. Или судно? Эти моряки так придираются к словам! В общем, она так скользила по водной глади, что дух захватывало. Я рад, что её проклятый капитан перестанет тревожить мои корабли." },
    ["896a"] = { common = "Хозяин причала в таком оживлённом порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой. Последние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтёров нашёл изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией." },
    ["896c"] = { common = "Только посмотри, какой он огромный! Теперь мы разбогатеем! Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю... Пятьдесят процентов, будь спок! Посчитаем... Да, примерно так. С тобой приятно иметь дело." },
    ["897a"] = { common = "Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно." },
    ["897c"] = { male = "Я ничего не могу сказать о природе этого существа, так как его дух ушёл. Как ты уже догадался, оно не из Степей. Я боюсь, что это может предвещать мрачное будущее нашему народу... Но сейчас приготовься, давай надеяться, что время раскроет тайну этого существа.", female = "Я ничего не могу сказать о природе этого существа, так как его дух ушёл. Как ты уже догадалась, оно не из Степей. Я боюсь, что это может предвещать мрачное будущее нашему народу... Но сейчас приготовься, давай надеяться, что время раскроет тайну этого существа." },
    ["898a"] = { common = "Наконец-то! Кто-то пришёл мне на помощь! Поверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса. Я! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую бухту. Довольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег." },
    ["898c"] = { common = "Подумать только, мы полагали, что Огненный Цветок давно погиб! Ты заслужил уважение всех Тало'данских каперов." },
    ["899a"] = { male = "Быть может, тебе знакома мука неопределённости, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, герой, мог бы мне помочь. Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.", female = "Быть может, тебе знакома мука неопределённости, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, героиня, могла бы мне помочь. Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах." },
    ["899c"] = { male = "герой, ты отнёсся к моему заданию серьёзно, спасибо тебе за это. Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я.", female = "героиня, ты отнёсся к моему заданию серьёзно, спасибо тебе за это. Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." },
    ["900a"] = { common = "В настоящий момент открыты три контрольных клапана. Суда по надписям на панели управления, их надо закрыть, прежде чем выключать прибор." },
    ["900c"] = { common = "Лампочки, относящиеся к трём управляющим клапанам, медленно гаснут. Зелёный огонёк становится жёлтым, и теперь можно повернуть рычаг, выключающий прибор. Клапаны закрыты, и терминал можно отключить." },
    ["901a"] = { common = "Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Всё бы хорошо, но чтобы отпереть терминал, нужен ключ." },
    ["901c"] = { common = "Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен." },
    ["902a"] = { common = "Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного рывка хватает, чтобы вытащить его из паза." },
    ["902c"] = { common = "Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна. Впрочем, сначала надо самому посмотреть что к чему..." },
    ["903a"] = { common = "Пришло время поохотиться на тех, кто может постоять за себя. Хищники саванны, живущие в Степях – сильные звери. Сильные, могучие, хитрые и опасные. Их можно найти в высокой траве на юго-западе от Перекрёстка. Соблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь." },
    ["903c"] = { common = "А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников. Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?" },
    ["905a"] = { common = "Что ж, теперь твоя задача усложняется. Сначала тебе надо победить свою добычу, а потом отыскать её логово. Я предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге. Убей их и забери перья. Отнеси перья в их гнёзда на юго-западе от Застывшего оазиса. Покажи их сородичам, что ты не боишься!" },
    ["905c"] = { common = "Значит, ты побывал возле гнёзд и поместил в них перья? На это требуется немало мужества. Ты чувствуешь, что стал сильнее? Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз. Думаю, Степи сыграли в этом свою роль." },
    ["906a"] = { male = "Отнеси голову Лока Торку на Перекрёсток, путник. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает* Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.", female = "Отнеси голову Лока Торку на Перекрёсток, путница. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает* Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай." },
    ["906c"] = { common = "Тебе удалось найти главаря племени Иглогривых и собственноручно убить его? Поразительно. У меня нет слов, но это не значит, что я не благодарен тебе. Жители Перекрёстка должны уважать твою силу. Должен признать, я считал, что возглавляет налёты на наши обозы другой свинобраз. Ещё раз спасибо." },
    ["907a"] = { common = "Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя. Ящерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой." },
    ["907c"] = { common = "Я рад, что ты принёс доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы." },
    ["913a"] = { male = "Грозовой змей – лютый зверь. И всё же ты уже готов бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты. Выполни моё задание, и твоё обучение подойдёт к концу.", female = "Грозовой змей – лютый зверь. И всё же ты уже готова бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты. Выполни моё задание, и твоё обучение подойдёт к концу." },
    ["913c"] = { common = "Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь. Не останавливайся, следуй дальше по своему пути. Более того, жизнь настоящего охотника – постоянная борьба. Ступай же с высоко поднятой головой по избранному тобой пути. Пора." },
    ["914a"] = { common = "Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращёнными мечтаниями. У Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир. Иди, и разыщи их укрытия в Пещерах Стенаний." },
    ["914c"] = { common = "Ты сделал это. Ты убил друидов Клыка, теперь мои сны свободны от их присутствия. Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." },
    ["916a"] = { common = "Я пришёл в Тенистую долину, чтобы наблюдать за чащобными тенётниками, обитающими в Паучьем логове. Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие... Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки. Для начала мне понадобится немного их яда. Добудь ядовитые железы у пауков-тенётников в Паучьем логове и вокруг него, к северу отсюда. После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей." },
    ["916c"] = { common = "Благодарю тебя. Когда я вернусь в Дарнас, я первым же делом сравню образцы яда из этих желёз с ядами других пауков. Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни." },
    ["917a"] = { common = "Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец. Не волнуйся, я не могу просить тебя поймать гигантского паука живьём. Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"! Но если ты принесёшь яйцо, из которого ещё не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать. В глубинах Паучьего логова должно быть гнездо. Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне." },
    ["917c"] = { common = "О, отлично. Я отправлю яйцо и яд в Дарнас, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены. Я многого ожидаю от этих образцов. Твоя помощь оказалась поистине бесценной." },
    ["918a"] = { male = "Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе. Потому меня очень тревожит, что древесники становятся такими озлобленными. Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не мог бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?", female = "Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе. Потому меня очень тревожит, что древесники становятся такими озлобленными. Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не могла бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" },
    ["918c"] = { male = "Ты их добыл. Славно! Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты ещё увидишь результаты!", female = "Ты их добыла. Славно! Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты ещё увидишь результаты!" },
    ["919a"] = { common = "Вокруг вод озера Аль'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придётся выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды. Когда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадётся тебе по дороге. Помоги очистить нашу землю!" },
    ["919c"] = { common = "Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их. Благодарю за помощь. Этот край благодаря твоим усилиям стал чище." },
    ["920a"] = { male = "Ты путник, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила. Хоть мы и живём долго, не стоит заставлять Тенарона ждать.", female = "Ты путница, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила. Хоть мы и живём долго, не стоит заставлять Тенарона ждать." },
    ["920c"] = { common = "А. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе." },
    ["921a"] = { common = "Пришло время тебе отправиться на поиски своей судьбы. Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории. Многое изменилось для нашего народа со времён битвы за гору Хиджал. Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион... Тебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила." },
    ["921c"] = { common = "Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако ещё многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнас." },
    ["922a"] = { male = "Не мог бы ты доставить один из тех ростков, что ты принёс мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом. Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов. Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять.", female = "Не могла бы ты доставить один из тех ростков, что ты принесла мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом. Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов. Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." },
    ["922c"] = { common = "А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях. К сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют её от родителей. И не в моих силах это исправить. У Деналана великий талант работать со всем, что растёт. Если кто и найдёт исцеление для будущих древесников, то это он. Возможно, он – наша последняя надежда." },
    ["923a"] = { common = "Древесники становятся всё более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить! Уничтожь всех древесников, которых там найдёшь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь." },
    ["923c"] = { common = "Хорошая работа! Эти опухоли - симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли. Я уничтожу эти опухоли. Благодарю тебя." },
    ["924a"] = { common = "Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарём Огня. Я подготовил камни силы, которые разорвут связь Семени с Легионом. Возьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. Торопись: сила камня постепенно иссякает." },
    ["924c"] = { common = "Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Ниру. Но это ещё не конец… После уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали… Впрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Ниру велел дать это в уплату и поблагодарить тебя. Итак, я благодарю тебя." },
    ["927a"] = { common = "Сердце Черномшеца Злосмрадного поросло тёмным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. Возможно, это заинтересует Деналана." },
    ["927c"] = { common = "...Это ещё что такое? Сердце древесника? Оно всё поросло вонючим мхом! Хорошо, что ты принесла его мне. Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." },
    ["928a"] = { male = "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя. Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнёс его Коритрасу. Ты найдёшь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками. И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа.", female = "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя. Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнесла его Коритрасу. Ты найдёшь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками. И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." },
    ["928c"] = { common = "А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало. Думаю, лучше не медлить и приступить к делу сейчас же." },
    ["929a"] = { common = "Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнасса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев. Отнеси этот сосуд к лунному колодцу у деревни Звёздного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон..." },
    ["929c"] = { common = "После битвы за гору Хиджал мы не знали, что делать дальше. Нордрассил дымился, опалённый огнём, и наше бессмертие – сама сущность нашего бытия! – было утрачено. Именно в эту пору испытаний Предатель вырвался из заточения и исчез Шан'до Ярость Бури. Настали тёмные времена." },
    ["930a"] = { common = "Под ветками этого светящегося растения висит большой круглый плод. Вы уверены, что Деналану захочется его изучить." },
    ["930c"] = { male = "Ты нашёл его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила. Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать...", female = "Ты нашла его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила. Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать..." },
    ["931a"] = { common = "Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение. Наверное. Деналана интересует именно такой образец." },
    ["931c"] = { male = "Где ты это нашёл? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины! Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком...", female = "Где ты это нашла? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины! Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." },
    ["932a"] = { common = "Должен предупредить тебя, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет. Его зовут лорд Меленас. Он живёт по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны. Найди его в пещере, прямо к северу отсюда, и принеси мне его голову!" },
    ["932c"] = { common = "Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность." },
    ["933a"] = { common = "К юго-востоку от входа в Дарнасс, на берегу Арлитириэнских прудов есть ещё один лунный колодец. Стражам трудно наблюдать за этими местами из-за всё учащающихся нападений и всё большей злобности фурболгов из племени Кривой Сосны. Будь начеку во время поисков колодца и держи оружие наготове." },
    ["933c"] = { common = "Шан'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении. После пропажи Малфуриона верховный Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Тёмных берегах, что нашему народу пора снова заполучить былую мощь и бессмертие. С одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни." },
    ["934a"] = { common = "Но не всё было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила. Однако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне." },
    ["934c"] = { common = "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость. Позволь мне продолжить... Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." },
    ["935a"] = { male = "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников. Могу только надеяться, что верховный друид быстро найдёт то, что ищет. Я наполню все принесённые тобой фиалы, чтобы ты доставил их в Дарнасс. Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов.", female = "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников. Могу только надеяться, что верховный друид быстро найдёт то, что ищет. Я наполню все принесённые тобой фиалы, чтобы ты доставила их в Дарнасс. Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." },
    ["935c"] = { common = "О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать её... хотя гонца, может, и не самого надёжного выбрали... хм-м. Однако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнётом лежит на моих плечах. Но скоро я избавлюсь от этого ярма. Вот, возьми. Может, тебе пригодится." },
    ["937a"] = { common = "Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнёзда по всей поляне. Мы стараемся потихоньку вытеснить их отсюда. Когда древо-оракул попыталось послать гонца в Дарнасс, на него напала стая гарпий и растерзала. Если ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига." },
    ["937c"] = { common = "Ты столького достигла за такое короткое время! Это очень впечатляет Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела. Я заметила, что Древо-оракул только что сбросило кусок коры. Несомненно, оно хочет, чтобы ты выполнила какое-то поручение для него. Поговори с ним." },
    ["938a"] = { common = "Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на её спине и брюхе. Она смотрит на вас, и в её голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами." },
    ["938c"] = { common = "О, благодарю тебя! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о её гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность." },
    ["940a"] = { common = "Шум леса донёс до меня весть о твоих подвигах. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности. Передай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли." },
    ["940c"] = { male = "Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная. Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие. Тем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда.", female = "Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная. Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие. Тем не менее, ты славно справилась с заданием Древа-оракула, и за усердие тебе положена награда." },
    ["941a"] = { common = "Я удалил этот смрадный мох с сердца, но оно всё ещё остаётся запятнанным... Попытайся посадить его в мою кадку. Она наполнена плодородной землёй, которая может очистить и исцелить это сердце." },
    ["941c"] = { common = "Вы сажаете сердце в кадку, и оно быстро в неё зарывается! Через несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки." },
    ["942a"] = { common = "Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил её на ежегодную конференцию Лиги Исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить. Последнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждёт, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого. Корабль в Менетилов отходит из Аубердина." },
    ["942c"] = { common = "О боги! Так вы говорите, эта вещь происходит из далёких земель Калимдора? Поразительно! Просто поразительно!" },
    ["943a"] = { common = "Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости. Пока я шёл по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила её, но если вам удастся её вернуть, я смогу высвободить силу этих артефактов. Принесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара." },
    ["943c"] = { common = "Великолепно! Теперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях." },
    ["944a"] = { common = "Очень странно, что наги появились здесь, на Тёмных берегах. Но ещё страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым. Меч Властителя, что к югу отсюда, – место, где пал один из этих древних богов. Пойди туда и поищи других культистов Сумеречного Молота. Возьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь всё у Меча Властителя. Посредством этой чаши поговори со мной." },
    ["944c"] = { male = "Так ты обнаружил клан Сумеречного Молота у Меча Властителя? Плохо. Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества. Должно быть, клан Сумеречного Молота пытается найти его силу.", female = "Так ты обнаружила клан Сумеречного Молота у Меча Властителя? Плохо. Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества. Должно быть, клан Сумеречного Молота пытается найти его силу." },
    ["945a"] = { common = "Помогите! Я бродила у Меча Властителя, как вдруг меня окружили эти жуткие культисты. Счастье, что я умею отлично прятаться!!! Можете помочь мне отсюда выбраться? И ещё, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины." },
    ["945c"] = { common = "Моя сестра была – где? Терилун любит бродить по всяким местам, но всё-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место... Ну, спасибо вам. С вашей стороны было очень любезно сообщить мне, что с ней всё в порядке." },
    ["947a"] = { common = "Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах. Я бы и сам туда пошёл, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло. Прошу вас, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев." },
    ["947c"] = { common = "Большое вам спасибо. Это отличные экземпляры! Кстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев? Дерева мудры, но я надеялся, что на сей раз они ошибаются." },
    ["948a"] = { common = "Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор. Дерева терпеливы и мудры. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное." },
    ["948c"] = { male = "путник. Ты здесь. Хорошо. Нам есть... что обсудить. Тебе и мне.", female = "путница. Ты здесь. Хорошо. Нам есть... что обсудить. Тебе и мне." },
    ["949a"] = { common = "Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе Обыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения. Ведь мы должны узнать об их целях раньше, чем они выработают план действий." },
    ["949c"] = { common = "Книга написана от руки на древнем языке и прекрасно иллюстрирована." },
    ["950a"] = { common = "Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы. Вырвать одну страницу с безумными каракулями – вот и всё, что вам удаётся сделать, пока вы не потеряли сознание." },
    ["950c"] = { common = "Неизученная первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы. Будем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Тёмном Берегу." },
    ["951a"] = { male = "Пергамент, который ты обнаружил близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев. Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.", female = "Пергамент, который ты обнаружила близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев. Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." },
    ["951c"] = { common = "Благодарю тебя. Эти реликвии относятся к поре расцвета Матистры. Этот некогда могучий оплот эльфов давно разрушен, но остатки магии ещё попадаются в руинах. Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги. Будь настороже." },
    ["952a"] = { common = "Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Тёмный Берег, прямо к югу от Аубердина. Ты наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждёт от меня вести, точно так же, как я ждал вести с Поляны Оракула." },
    ["952c"] = { common = "А. Спасибо. Тем не менее, это странно. Верховный друид всегда так торопится. Лес знает, что всему своё время. Шан'до Ярость Бури это понимал." },
    ["953a"] = { common = "К востоку отсюда находятся руины Амет'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии. Меня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала. Пожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня." },
    ["953c"] = { common = "У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности. Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили. Спасибо вам. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад." },
    ["954a"] = { common = "Руины Башал'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал'Арана, и силы их растут от постоянной подпитки энергией. Но при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утёса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту. Я хотел бы, чтобы вы его исследовали." },
    ["954c"] = { male = "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная путник? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение... Но, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.", female = "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная путница? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение... Но, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." },
    ["955a"] = { male = "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук. Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помог мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след.", female = "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук. Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помогла мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." },
    ["955c"] = { common = "И правда... Грелли Башал'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру..." },
    ["956a"] = { common = "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чём дело. Несомнено эта печать находится во владении сатира, предводительствующего ими. Я убеждён, что моя догадка верна. Она наверняка у одного из сатиров. Если ты сможешь её добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слёз..." },
    ["956c"] = { common = "Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам." },
    ["957a"] = { common = "Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет'Аране – точно таких же руинах к югу отсюда – до сих пор горит древний синий огонь. В этом огне печать может быть уничтожена. Будь осторожнее в тех руинах..." },
    ["957c"] = { common = "Я свободен! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я узнаю только отдельные фрагменты. Подумать только, что когда я в последний раз гулял на свободе, ещё существовал Источник и высокорожденные держали совет с Азшарой, нашей любимой королевой. Я чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, ещё жив... Моё осознание безнадёжности вскоре сменится мыслями о мести." },
    ["958a"] = { male = "герой. Вот задание, которое я вам поручаю. Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями. Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.", female = "героиня. Вот задание, которое я вам поручаю. Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями. Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." },
    ["958c"] = { common = "Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось." },
    ["959a"] = { common = "Ой! Как видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов всё рухнуло на землю. Не успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна девяносто девять-летней выдержки и бросился наутёк. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок. Может, тебе хватит пороху, чтобы найти его?" },
    ["959c"] = { common = "Великолепно! И ведь меня едва не уволили! Теперь надо поскорее отнести подарок Газлоу. Cпасибо. Отличная работа!" },
    ["962a"] = { common = "Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью. Возможно, вы сумеете помочь мне, а, стало быть, и Тёмной Госпоже в трудах на благо Отрёкшихся. Не так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности. Увы, змеецвет можно найти только в самых тёмных закоулках Пещер Стенаний, опасной системе подземелий в Степях." },
    ["962c"] = { common = "Ах, замечательные экземпляры! Вы хорошо поработали." },
    ["963a"] = { common = "После битв за Источник Вечности я узнал, что Амет'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя. Я никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Тёмном Берегу, я очутился в руинах Амет'Арана... где и увидел неупокоенный дух моей любимой. Её нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить её призрак." },
    ["963c"] = { common = "Благодарю тебя. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную. Пожалуйста, оставь меня наедине с моим горем..." },
    ["965a"] = { male = "Привет тебе, юный путник. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда. С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда. Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты смог найти его и удостовериться, что с ним всё в порядке.", female = "Привет тебе, юная путница. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда. С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда. Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты смогла найти его и удостовериться, что с ним всё в порядке." },
    ["965c"] = { common = "Тебя прислала Элисса? Это хорошо. У меня есть для неё тревожные вести, но не было возможности передать их ей." },
    ["966a"] = { common = "Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать. Делгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем. Несколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!" },
    ["966c"] = { common = "Большое спасибо. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников... Хмм... Клан Тёмной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чём могут заключаться их планы. Больше нельзя тянуть. Нужно немедленно предупредить Делгрена." },
    ["967a"] = { common = "Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве. Делгрен должен немедленно узнать о деятельности клана. Вы найдёте его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Тёмной Нити растёт с каждым часом." },
    ["967c"] = { male = "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет... Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их. Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.", female = "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простой посланницы, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет... Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их. Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." },
    ["968a"] = { common = "Хотя книга ужасно истрёпана и исцарапана, её название на обложке всё же можно разобрать: \"Подземные Силы\". В книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями... И среди этих жертвоприношений числятся живые разумные создания. На внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват\". Если Костохват торгует подобными книгами, может быть, он выкупит эту?" },
    ["968c"] = { male = "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже... Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице! Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его друг? Да, должно быть, так. У вас в глазах такой же огонь горит! Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?", female = "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже... Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице! Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его подруга? Да, должно быть, так. У вас в глазах такой же огонь горит! Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?" },
    ["970a"] = { common = "Письмо Балтула приводит меня в ужас. Этот клан Тёмной Нити – сущее бельмо у меня на глазу, и его надо устранить! Мне приходилось иметь дело с мерзавцами из Тёмной Нити к северо-востоку отсюда в Ордиль-Аране. У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана. Принеси его мне, а уж я сумею разгадать его тайну." },
    ["970c"] = { common = "Хмм, этот самоцвет Души наполнен какой-то тёмной магией. Давай-ка посмотрим, что в нём таится..." },
    ["971a"] = { common = "Насколько вам известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Ходят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса. Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины. Найдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней." },
    ["971c"] = { common = "Вы нашли манускрипт! Что за радостный день! Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестёр! Вы даже не понимаете, какую услугу нам оказали. Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам." },
    ["973a"] = { common = "Илкруд Магтрулл. Да, я знаю о нём. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса. Доныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться." },
    ["973c"] = { male = "Сегодня ты сделал большое дело. Гордись – ты сразил могущественного чернокнижника. А теперь посмотрим, что сказано в записях Илкруда.", female = "Сегодня ты сделала большое дело. Гордись – ты сразила могущественного чернокнижника. А теперь посмотрим, что сказано в записях Илкруда." },
    ["976a"] = { common = "Делгрен попросил меня доставить письма и припасы часовому Звёздный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки. Если ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю всё это в Аубердин." },
    ["976c"] = { male = "Ты сегодня славно поработал, герой. То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес. Прими это вместе с моей сердечной благодарностью.", female = "Ты сегодня славно поработала, героиня. То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес. Прими это вместе с моей сердечной благодарностью." },
    ["981a"] = { common = "За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сражённый вашей рукой, а клан Тёмной Нити сокрушён, и остатки его рассеяны." },
    ["981c"] = { common = "Я знал, что вы возьмётесь за это задание. Я чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите моё благословение, и этот дар." },
    ["982a"] = { male = "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы ты добыл их для нас; это много значило бы для членов команды.", female = "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы ты добыла их для нас; это много значило бы для членов команды." },
    ["982c"] = { male = "Вы оказали нам огромную услугу, юноша. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход. Что же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.", female = "Вы оказали нам огромную услугу, девушка. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход. Что же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." },
    ["983a"] = { common = "Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С её помощью можно общаться на расстоянии! Может быть, ты уже видел их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход. У каждой из них есть своя проблема, но я нашёл хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка восемьсот двадцать семь. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы её починить, нужно шесть ножек краба. Я заплачу..." },
    ["983c"] = { common = "Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины. \"Алло! Уфф... Алло! Ты её починила! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить ещё одну машинку?\"" },
    ["984a"] = { common = "Некоторые из моих собратьев спаслись от порабощённых порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то ещё хуже. Я уже вижу признаки присутствия скверны на Тёмных берегах, но она ещё не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, ты найдёшь один из их лагерей, а затем вернёшься ко мне, если увидишь следы порчи?" },
    ["984c"] = { common = "Это и вправду ужасные новости. Поскольку фурболги находятся так близко к Аубердину, нам придётся приготовиться к неизбежному. Спасибо вам." },
    ["985a"] = { common = "Вы уже поднаторели в разведке на вражеских территориях. Но способны ли вы не только следить за врагами, но и биться с ними? Не все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения. Если вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдёте там фурболгов Чернолесья. Убейте восемь следопытов и пять заклинателей ветра, а потом возвращайтесь сюда, ко мне." },
    ["985c"] = { common = "Смойте кровь с ваших доспехов, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе. Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Тёмный Берег пока ещё находится в опасности из-за Мха Скверны." },
    ["986a"] = { common = "Ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Тёмного Берега, пока вы будете искать Волкора. Для изготовления плаща, чтобы хватило материала, мне нужно пять прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или ещё дальше на юг, близ Ясеневого леса." },
    ["986c"] = { common = "Эти шкуры отлично подойдут. Я немедленно приступаю к работе над плащом. Дайте мне немного времени, а затем возвращайтесь. Да, ещё кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своём взаимодействии с другими лицами. Если сможете, ограничьтесь только разговорами. Всё, что сверх этого, может развеять чары." },
    ["990a"] = { common = "Моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни. Отправляйся отсюда на юг и держись дороги – ты легко найдёшь путь, если будешь держаться этого направления." },
    ["990c"] = { male = "А, герой с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение. Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.", female = "А, героиня с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение. Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь." },
    ["991a"] = { common = "Один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он ещё не вернулся. Он думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. Прежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла. Он также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор. Камень хранился там до того, как святилище было разрушено. Найди моего друга, пожалуйста." },
    ["991c"] = { common = "Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь. Глубокие резаные раны явно оставлены оружием и когтями мурлоков." },
    ["993a"] = { male = "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем. Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять. Сам решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя. Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.", female = "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем. Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять. Сама решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя. Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." },
    ["993c"] = { common = "Чудесно! Терентис прислал мне помощь! О, посмотри-ка, ещё и плащ... кашляет Ох... Больно. Спасибо. Фурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне ещё минутку, и я буду в состоянии разговаривать дальше." },
    ["994a"] = { common = "Ладно, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьёмся к дороге – Мрачнокоготь должен всё ещё ждать. А там мы уже сможем разделиться. Терентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся." },
    ["994c"] = { male = "путник! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами.", female = "путница! Рад видеть вас живой и здоровой. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." },
    ["995a"] = { common = "Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдём, как только вы будете готовы. Не забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас." },
    ["995c"] = { male = "путник! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами.", female = "путница! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." },
    ["997a"] = { male = "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу... Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что. Не мог бы ты отнести ему эту землю?", female = "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу... Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что. Не могла бы ты отнести ему эту землю?" },
    ["997c"] = { male = "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая... Спасибо тебе за доставку. Ты – путник, не жалеющий времени на благие дела!", female = "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая... Спасибо тебе за доставку. Ты – путница, не жалеющая времени на благие дела!" },
    ["1001a"] = { common = "Тоненький голосок пробивается откуда-то из глубины машины. \"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу. Итак, номер той Жужжалки – четыреста одиннадцать, и для её починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Тёмного Берега... *И-ик!* Извини... Как и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной всё в порядке!\"" },
    ["1001c"] = { common = "Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба. После коротких помех вы слышите знакомый голосок. \"Вино из крабов лучше всего...\" И-ик! \"Что? О, ты уже её починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?\" Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки." },
    ["1002a"] = { common = "Жужжалка издаёт треск статических помех, и вы слышите голос Бацбаха. \"Шшшледуюшшшая жужшшшалка – номер триста двадцать три. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшо? О, она шшштоит на дороге, так шшшо ты легко её найдешшшь около мосшшшт\". Бацбах что-то неразборчиво бормочет, а потом вы слышите отчётливый звук глотка. \"В эту нужшшшно положшшшить клыки лунопардов... шшшесть\"." },
    ["1002c"] = { common = "Неожидано Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку. \"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"" },
    ["1003a"] = { common = "Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха. \"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка пятьсот двадцать пять снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи...\" Вы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает. \"Четыре!\"" },
    ["1003c"] = { common = "Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались! Шшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшшё варят и дишшштиллируют отличшшшное питьё. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!" },
    ["1007a"] = { common = "Я хотел бы дать тебе поручение. Я на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Я убежал, унеся с собой всё, что смог, и чего хватило лишь вот на этот жалкий лагерь. Но когда я добрался до берега и побежал... я потерял одну дорогую мне вещь. Прошу тебя, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку. Именно из-за неё я отважился подвергнуть себя опасностям Зорамского взморья." },
    ["1007c"] = { male = "Ты её нашёл! Спасибо тебе! Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них.", female = "Ты её нашла! Спасибо тебе! Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." },
    ["1008a"] = { common = "По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло. Там покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощённого морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт. Теперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины! Возвращайся, когда выполнишь поручение." },
    ["1008c"] = { common = "Отлично. Твои деяния против наг на Зорамском взморье достойны похвалы. Я знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам. Мы это знаем, ибо у нас одна история. Но эту историю я вспоминать не желаю." },
    ["1009a"] = { common = "Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не нати ключа к этому древнему замку. Этим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его. Долгие годы кольцо считалось утраченным, пока наги недавно не нашли его. Их предводительница, Руузель, живёт на острове на северной окраине Зорама. Прошу тебя, добудь мне это кольцо!" },
    ["1009c"] = { male = "Ты добыл кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты делал сегодня.", female = "Ты добыла кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты сделала сегодня." },
    ["1010a"] = { common = "Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души. В этой деревне болеет ребёнок, и сдаётся мне, что это болезнь не телесная. Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребёнка. Убежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Тёмным Берегом." },
    ["1010c"] = { male = "Ах, ты принёс эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал. И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная...", female = "Ах, ты принесла эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал. И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная..." },
    ["1013a"] = { common = "В крепости Тёмного Клыка хранится книга – книга Ура, я хочу видеть её в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрёкшихся. Отправляйся в крепость Тёмного Клыка и найди книгу. Принеси мне её, и я сообщу о твоих заслугах Тёмной Госпоже." },
    ["1013c"] = { common = "Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. Мы, Отрёкшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... И уж тем более не обрести власть." },
    ["1014a"] = { common = "Аругал по-прежнему сидит в крепости Тёмного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Тёмной Госпожи до тех пор, пока Аругал жив. Я позабочусь о том, чтобы искоренить его магию. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. Отправляйтесь в крепость Тёмного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!" },
    ["1014c"] = { common = "Наконец-то Серебряный бор избавлен от злодеяний Аругала. Вы сослужили огромную службу Тёмной Госпоже. Ваша стойкость будет вознаграждена." },
    ["1016a"] = { common = "Бозьми этот гадальный свиток – он поможет определить создателя этих элементалей. Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут. Хватит нескольких неповрежденных браслетов с этих существ. Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать. Как только ты добудешь неповрежденные браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим." },
    ["1016c"] = { common = "Хорошая работа, это даст нам информацию, необходимую для того, чтобы раскрыть преступника. Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями? У меня сердце сжимается при виде осквернённого Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается ещё сильнее навредить этому краю. Мы заставим его за всё ответить." },
    ["1017a"] = { common = "Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеётся надо мной. Тебе придётся проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. Уничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя." },
    ["1017c"] = { common = "Теперь эта мерзкая ухмылка навсегда стёрта с его лица. Славное, воистину славное дело. Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема. Он спасёт тебя по воле Богини." },
    ["1020a"] = { common = "Я изготовил лекарство, которое, надеюсь, поможет больному ребёнку. Отнеси его в Астранаар отцу ребёнка, Пельтуру Белой Луне. Чтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток." },
    ["1020c"] = { common = "Это от Орендила? Он славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было..." },
    ["1023a"] = { common = "Осматривая вещи Терониса, вы находите дневник, который всё ещё в неплохом состоянии. Вы берёте дневник и оставляете труп Терониса. Остаётся только найти камень, который искал Теронис. Раэна говорила, что он где-то здесь. Возможно, его забрали мурлоки..." },
    ["1023c"] = { common = "Это ужасно. Теронис мёртв?! Мы оплачем его, когда придёт пора, но сейчас надо сосредоточить усилия на другом. Я отправлю часовых за телом Терониса как можно скорее. У тебя дневник Терониса и камень, который он искал. Как думаешь – ты сумеешь завершить его дело? Моя душа успокоится, если я буду знать, что он не попусту погиб." },
    ["1024a"] = { male = "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь готов, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя. Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её. Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл.", female = "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь готова, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя. Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её. Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." },
    ["1024c"] = { common = "О, так тебя послала Раэна? Тогда это и правда серьёзное дело. Чем я могу тебе помочь?" },
    ["1025a"] = { male = "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу. На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв. Помоги часовым защитить эти края, отплати этим чудовищам их же монетой. Думаю, их лагерь находится к югу от дороги... будь осторожен.", female = "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу. На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв. Помоги часовым защитить эти края, отплати этим чудовищам их же монетой. Думаю, их лагерь находится к югу от дороги... будь осторожна." },
    ["1025c"] = { common = "Славная работа. Спасибо тебе." },
    ["1026a"] = { common = "Хотелось бы мне, чтобы у тебя были более хорошие новости. Раэна права, я знаю о творении Дартола и древнях этих краёв – или знала прежде. Они теперь все осквернены, их природа искажена. Если твоя цель – найти ещё один фрагмент жезла, то тебе придётся найти ключ, чтобы отпереть сундук, в котором он лежит. Деревянный ключ – на одном из древней к северу отсюда, близ Осквернённого леса. Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Осквернённого леса... Сундук должен быть спрятан где-то там." },
    ["1026c"] = { common = "Я рада твоему возвращению." },
    ["1027a"] = { common = "Последний фрагмент жезла был отдан на хранение друидам Дор-Даниля. Я понятия не имею, где они его спрятали. Сожалею, что больше ничем не могу тебе помочь. Могу только сказать, что тебе следует идти по дороге, что ведёт в Степи. Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили... мне не очень хочется об этом думать. Когда найдёшь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл." },
    ["1027c"] = { common = "Ты нашёл последний фрагмент? Тебе очень повезло... И Раэне тоже. Как понимаю, нам надо попытаться собрать его, да?" },
    ["1028a"] = { common = "Вот собранный жезл. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой. Но при твоих целеустремлённости и усердии, после всех твоих достижений тебе не слишком трудно будет его найти. Ступай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину. Как только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе." },
    ["1028c"] = { common = "Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл." },
    ["1029a"] = { common = "Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. Удачи." },
    ["1029c"] = { common = "Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать. Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." },
    ["1030a"] = { common = "Увы, не могу сказать, что у него было на уме. Если он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ. Какой – не знаю. Может, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Дартол, превращённый при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны. На мой взгляд, надо начать поиски к юго-востоку от озера Мистраль." },
    ["1030c"] = { common = "Да-да... ты мой сородич, но ты здоровый. Пока ещё чистый. Не знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок. Нынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени. По ночам я по-прежнему вижу костры в темноте." },
    ["1033a"] = { common = "Я надеялся, что лекарство Орендила спасёт Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие ещё он попытается применить лекарства, если первое не поможет. Слеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!" },
    ["1033c"] = { male = "О, ты нашёл её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!", female = "О, ты нашла её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!" },
    ["1034a"] = { common = "Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже её мучить, хвала богине. Но... лихорадка всё ещё сжигает её. Орендил рассказал мне о морозной пыли, которую находят среди руин Звёздной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси её мне. Руины Звёздной Пыли находятся на юге. Да ускорит твой шаг Элуна!" },
    ["1034c"] = { common = "Ты принёс пыль! Я сделаю из неё припарки – они должны унять лихорадку Релары. Ещё раз спасибо тебе. Без твоей помощи моё дитя несомненно умерло бы." },
    ["1035a"] = { male = "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу. Мне кажется, тут нужна мощь лунного камня. Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники. Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должен отнять лунные камни у Оракула. И, боюсь, для этого тебе придётся его убить.", female = "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу. Мне кажется, тут нужна мощь лунного камня. Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники. Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должна отнять лунные камни у Оракула. И, боюсь, для этого тебе придётся его убить." },
    ["1035c"] = { common = "О, ты спас мою дочь! Я знаю, что сила лунного камня вернёт моей дочери силы! Мне никогда не отблагодарить тебя за всё, что ты для меня сделал, но... пожалуйста, возьми вот это. После Релары это самое дорогое, что есть у меня." },
    ["1045a"] = { common = "Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь ещё и наши жизни. Но это уже никак не получится контролировать... Я много в чём могу обвинять эльфов, но мы всё равно отвечаем за свои деяния. Даже не подвергнувшись порче, мы способны творить великое зло. Рэн Кровавый Клык – такое зло. Жаждущий мощи, алчный... порча только сделала его сильнее. Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих." },
    ["1045c"] = { common = "Славная работа. Спасибо тебе." },
    ["1046a"] = { common = "Возвращайся в своё племя и поведай им о нашей победе. Покажи им свой трофей и насладись славой..." },
    ["1046c"] = { common = "Значит, вот он – череп самого лютого фурболга в Ясеневом лесу? Я более чем довольна твоими способностями. Не знаю даже, как часовым отблагодарить тебя. Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу. Я положу этот череп и жезл Дартола на почётное место, чтобы всё их увидели. Теронис гордился бы тобой. Ещё раз спасибо тебе." },
    ["1054a"] = { common = "Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар! Убей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. Я останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна." },
    ["1054c"] = { common = "Славная работа. Эти фурболги постоянно угрожают нам. По счастью, теперь они некоторое время будут сидеть тихо." },
    ["1055a"] = { common = "Воссозданный жезл у вас в руках. Шаэлдрин захочет услышать о ваших успехах." },
    ["1055c"] = { common = "У тебя получилось! Великолепно!" },
    ["1056a"] = { male = "Лесные духи говорят мне, что ты отважен и лёгок на подъём. На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя. Там ждёт хранитель Албагорм. Выслушай его просьбу, путник. Путешествие будет опасным.", female = "Лесные духи говорят мне, что ты отважна и легка на подъём. На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя. Там ждёт хранитель Албагорм. Выслушай его просьбу, путница. Путешествие будет опасным." },
    ["1056c"] = { common = "Наконец-то! Вижу, Фальдреас прислушался к духам лесов..." },
    ["1057a"] = { common = "Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен. Чтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов. Обугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краёв! Изгони прочь злобных гарпий!" },
    ["1057c"] = { common = "Теперь, когда клан Смертельной Ярости понёс большие потери, вероятно, и начнётся истинная работа по восстановлению этих земель..." },
    ["1058a"] = { common = "Я в восхищении! Три маленьких клетки для трёх маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии! Мне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и ещё, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика. Живо в Каменный Коготь, чтобы я мог сварить немножко лесной магии!" },
    ["1058c"] = { common = "О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!" },
    ["1059a"] = { common = "Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. Далеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог. Этот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины. Поведай ему о нашей беде! Отправляйся на его поиски немедленно!" },
    ["1059c"] = { common = "Хранитель Албагорм поступил мудро, прислав тебя со срочным известием. Будем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно." },
    ["1060a"] = { male = "Ты сделал мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё. Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу. Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.", female = "Ты сделала мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё. Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу. Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место." },
    ["1060c"] = { common = "А, письмо от Дарсока. Давно от него не было вестей. Значит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рокхан пошёл убивать её старшую сестру с этим психом из Мок'Натала. Да, тогда я был молод, как ты сейчас." },
    ["1061a"] = { common = "Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали. В Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи. Отправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрёстка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса." },
    ["1061c"] = { male = "А, герой! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!", female = "А, героиня! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" },
    ["1062a"] = { common = "Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию! Отправляйсся на северо-запад, за Долину Высокого леса, к Утёсу Ветрорезов. Ты найдёшь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают... На языке беспощадной силы!" },
    ["1062c"] = { common = "Это подлинно отважное деяние. Вероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но... Первый шаг в верном направлении сделан – Торговая Компания лишилась работников." },
    ["1063a"] = { common = "Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов. Я мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Я слышала, что она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она. Магата живёт в главном городе тауренов Громовом Утёсе, на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах." },
    ["1063c"] = { common = "Я приветствую тебя. Ты ищешь совета?" },
    ["1064a"] = { common = "Таурены в сродстве с этой землёй, и мне больно слышать о том, что творится в Каменном Когте. Но я боюсь, что для исцеления этой земли нам прежде придётся справиться с той заразой, что терзает нас самих. Разве не удача, что Отрёкшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами. Поговори с аптекаршей Замой. Она – учёная и представитель Отрёкшихся. Ты найдёшь её у Прудов Видений под Уступом Духов." },
    ["1064c"] = { common = "Магата прислала о тебе весточку. Хотя сердце моё уже и не бьётся, оно всё же разрывается от горя по духам Каменного Когтя. Отрёкшиеся готовы помочь всем, чем только можно." },
    ["1065a"] = { common = "Нам придётся прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития. У одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живёт в городе Мельница Таррен в предгорьях Хилсбрада, в далёком краю Лордерон. Чтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад. Найди Лидона и передай ему эту записку. Там написано, что нам от него нужно." },
    ["1065c"] = { common = "Записка от Замы? Наверняка её сильно прижало, раз пишет в такую даль. Посмотрим... Замечательно! Я знаю, что ей надо!" },
    ["1066a"] = { common = "Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Каменном Когте, да? Но для создания отравы мне понадобится кровь невинных, а её нелегко найти. К счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько тёмных магов... а они собирают кровь невинных для своих нечистых целей. Тёмных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке." },
    ["1066c"] = { common = "Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем? Как я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката. А теперь подожди, я создам мой состав..." },
    ["1067a"] = { common = "Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы. Мне не терпится испытать свою работу в деле! Впрочем, прежде отнеси её аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы." },
    ["1067c"] = { common = "Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию..." },
    ["1068a"] = { common = "Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не всё, что они шепчут, однако одно послание - одно видение - было чётким... В этом видении я узрела на Утёсе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить! В явленном мне видении я заметила, что машины эти отмечены странными символами: XT:четыре и XT:девять." },
    ["1068c"] = { common = "Уничтожение машин XT:четыре и XT:девять успокоило многих духов Каменного Когтя. Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы. Ибо если этого не произойдёт, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждёт нас впереди." },
    ["1069a"] = { common = "В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет. Я чую прибыль! На Утёсе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу! На Утёсе Ветрорезов паучьи кладки можно найти под оставшимися деревьями. В Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утёсе Ветрорезов..." },
    ["1069c"] = { common = "Ты принёс мне яйца! Спасибо! Я пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту! Вот твоя доля. Без тебя мне бы не справиться." },
    ["1070a"] = { common = "Привет тебе. Судя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов. Недавно часовой Волкопас послала туда мою подругу Келу Копьё Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от неё нет вестей. Я ещё беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги. Может быть, ты найдёшь её и пошлёшь весточку мне?" },
    ["1070c"] = { common = "А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передаёт путникам. Я горжусь за неё. Рада познакомиться с тобой." },
    ["1071a"] = { common = "Понимаешь ли, я состою в Просвещённой Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса. Однако это тяжёлая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения! Мне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утёса Ветрорезов к востоку отсюда..." },
    ["1071c"] = { common = "Спасибо тебе за помощь. Да и вернуться тебе удалось как раз вовремя. Кажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть. Понимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов..." },
    ["1072a"] = { common = "Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней. А для этого нам нужно мощное взрывчатое вещество: нитромирглицероний. Единственный, кто может создать НГ-пять, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков. Если уговоришь его сделать для нас немного НГ-пять, то я начну работать над размещением своих устройств." },
    ["1072c"] = { common = "А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врёшь? Ась? Ась?.." },
    ["1073a"] = { common = "Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?! Мне всё равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесёт на мелкие кусочки: или тебя, или гоблинов. Но есть проблемка: у меня кончились химикалии. Но вот что я тебе скажу: принесёшь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик. По крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения." },
    ["1073c"] = { common = "Вот это подойдёт. Не знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?" },
    ["1074a"] = { common = "Ну вот тебе, держи. Тока поосторожней... это летучая смесь. Если Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха." },
    ["1074c"] = { common = "Дело сделано, и сделано отлично. НГ-пять незаменимый компонент для поджига повозок с динамитом. Что? Да, динамит... целыми повозками. Это идеальный отвлекающий манёвр, я тебе скажу... подожди и увидишь." },
    ["1075a"] = { male = "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого? Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять. Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимателен, не ошибись.", female = "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого? Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять. Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимательна, не ошибись." },
    ["1075c"] = { common = "Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм." },
    ["1076a"] = { common = "А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. Мне нужно создать свиток с запечатлённым на нём заклинанием. Для этого мне нужен прах Пыледемона. Пока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима. Когда ты вернёшься, я буду здесь." },
    ["1076c"] = { common = "Подожди несколько секунд, и нужный тебе свиток будет готов." },
    ["1077a"] = { common = "Вот. Это то, что нужно. Когда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история. Всего тебе хорошего." },
    ["1077c"] = { common = "Великолепно! Славная работа. Это заклинание вместе с НГ-пять даст идеальную дистанционную взрывчатку. У нас получится прекрасный отвлекающий манёвр, и ты прокрадешься и сопрёшь документы и инженерные планы Торговой Компании. Тогда они не смогут вырубать леса так быстро." },
    ["1078a"] = { common = "Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причём самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией. В Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. Если эти василиски ещё живут там, мне надо заполучить хотя бы несколько чешуек. Если не очень торопишься, удели на это немного времени, я хорошо заплачу тебе." },
    ["1078c"] = { common = "Великолепно. Спасибо тебе огромное. Может быть, и я когда-нибудь смогу помочь тебе." },
    ["1079a"] = { common = "Так вот, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию. Возьми эти листы – здесь всё объясняется про детонаторы, взрывчатку и про то, как их разместить. Помни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План \"Альфа\" увенчается успехом в том случае, если ты принесёшь технические чертежи Торговой компании, находящиеся на лесопилке к югу от Скалистого Озера." },
    ["1079c"] = { common = "Просто великолепно! Это сильный удар по Торговой Компании. Мы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день." },
    ["1080a"] = { male = "План Бета – почти то же, что и план Альфа. путник. Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма. Главное – получить письма... помни это. На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...", female = "План Бета – почти то же, что и план Альфа. путница. Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма. Главное – получить письма... помни это. На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами..." },
    ["1080c"] = { common = "Великолепно! Каэла и часовые будут счастливы. При твоих умениях да моих творениях нас никто и ничто не остановит!" },
    ["1085a"] = { common = "Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома. Торговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению. Не суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе. Если ты хочешь помочь нам, то для начала поговори с Гаксимом. Извини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре..." },
    ["1085c"] = { common = "Предательская... предательская и опасная, вот какова эта земля. Но я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее. Видишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без неё не могут. И мир без неё не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса." },
    ["1086a"] = { common = "Отрава готова. Остаётся только её доставить адресату. И это придётся сделать тебе. У Торговой Компании есть средства доставки сообщений и лёгкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролета. Обыщи всё области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдёшь, помести туда отраву. Положишь – беги оттуда." },
    ["1086c"] = { common = "Ты нашёл аэропорт? Молодец! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберётся до их штаб-квартиры. Ты оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они ещё не того заслуживают. И вот какой мудрости союзникам Отрёкшихся стоит поучиться: Не бойся тёмных дорог... если они ведут к победе." },
    ["1087a"] = { common = "Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов. Я так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена. Не сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся." },
    ["1087c"] = { common = "Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы калдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам. Как же скучна и бесцветна жизнь без этого огненного потока!" },
    ["1088a"] = { common = "Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Хорданиуса – но я заполучу его голову! Магия даёт мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе. Принеси мне его голову, и я поделюсь с тобой могуществом." },
    ["1088c"] = { common = "Некогда, давным-давно, я знала Хорданиуса. Он был горд, как и всё его сородичи, и ставил себя даже над высокорожденными. Однако теперь ему трудно так же высоко держать голову, не так ли? Я обещала тебе награду, и ты её получишь. Слушай меня!" },
    ["1089a"] = { common = "В Пещере Когтей друиды построили Логово Когтя, где хранят множество могущественных предметов. Они продумали сложный план, чтобы не дать этим предметам попасть в чужие руки. К счастью, мне удалось... вытянуть некоторые подробности из одного из них. В маленьком светильнике у входа в пещеру ты найдёшь спрятанный там Ключ Хранителя Врат – с его помощью ты сможешь отворить тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещённую в одном из центральных помещений." },
    ["1089c"] = { common = "Когда три ключа вошли каждый в своё отверстие, посреди мерцающего сияния появились несколько предметов." },
    ["1090a"] = { common = "Знаешь, когда-то я был второй по важности персоной во всём этом деле. Всё изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо. В любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зелёной руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража." },
    ["1090c"] = { common = "Спасибо. Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны. Но важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу." },
    ["1092a"] = { common = "Полагаю, мне тоже нужно убираться отсюда. Не пройдёт много времени. как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской. Мне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работёнку!!! Я попытаюсь тут слегка подчистить за собой, но тебе придётся доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утёса Ветрорезов. Удачи!" },
    ["1092c"] = { common = "А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть. Конечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?" },
    ["1093a"] = { common = "Ну, Торговая Компания и наломала дров! О чём они только думали? Гоблинская компания нанимает гнома! К счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда! Мне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдёшь чертежи? Они должны быть у кого-то из операторов компании." },
    ["1093c"] = { common = "Эй, это то, что я думаю? Отлично! Ну-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролетах." },
    ["1094a"] = { common = "В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи \"Супер-потрошителя шесть тысяч\". Паровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зелёный тип." },
    ["1094c"] = { common = "Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше! Хотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой..." },
    ["1095a"] = { common = "В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо. Ридлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение. Как бы то ни было, Геренцо необходимо устранить, и Физзику придётся хорошо поработать." },
    ["1095c"] = { common = "Убрать Геренцо? Я только за! Гномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо." },
    ["1096a"] = { common = "Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниёт и отпадает, части его тела заменены металлическими деталями и механизмами. К северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу. Если ты убьёшь его по моей просьбе, то получишь щедрое вознаграждение!" },
    ["1096c"] = { common = "Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять её этой штукой, если можно просто сохранить обе руки и приделать третью! Гномы, я тебе скажу... Геренцо, по крайней мере, если и не мёртв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте." },
    ["1097a"] = { male = "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север. Ты мне кажешься опытным путешественником... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами. Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города.", female = "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север. Ты мне кажешься опытной путешественницей... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами. Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города." },
    ["1097c"] = { common = "Ты поможешь мне с доставкой? Замечательно!" },
    ["1098a"] = { common = "Готовясь к нападению на крепость Тёмного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчёта нам не организовать успешного нападения! Итак, вот твоё задание. Отправляйся в крепость Тёмного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь. Это очень опасное и важное задание. Не подведи нас." },
    ["1098c"] = { common = "Перед вами лежит израненное тело Винсента. Страж смерти Адамант написал отчёт Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унёс это с собой в могилу. В мёртвой руке зажата небольшая безделушка..." },
    ["1130a"] = { common = "Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь. Если вы хотите пройти его, отправляйтесь в Громовой Утёс и поговорите с Мелором. Его можно найти на вершине Охотников." },
    ["1130c"] = { male = "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли? Раз так, юный герой, то слушайте...", female = "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли? Раз так, юный героиня, то слушайте..." },
    ["1131a"] = { common = "Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли. Но охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли. Гиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе. Найдите Сталезуба. Найдите и убейте его." },
    ["1131c"] = { common = "Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти. И это, ваш урок на сегодня." },
    ["1133a"] = { common = "Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар. Уверен, такому преданному члену Альянса будет, чем заняться в городе. Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги. Не стоит говорить ей, кто вас прислал. Шиндрелл меня не знает..." },
    ["1133c"] = { common = "Вы здесь, чтобы предложить помощь Альянсу? любой помощи. Хотя красота всё ещё живёт в Ясеневом лесу... война добралась и до этих мест." },
    ["1134a"] = { common = "Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. Об одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса! Если это правда, мы обязаны остановить их. Мы должны лишить их источника яда." },
    ["1134c"] = { common = "Благодарю тебя. Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг. Быть может, друг мой, твоё сердце оплакивает величавых виверн, которых тебе пришлось убить, однако пусть тебе принесёт утешение то, что твои союзники больше не будут погибать от их яда." },
    ["1138a"] = { common = "Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Ещё их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушёный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и всё. Я здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить..." },
    ["1138c"] = { common = "Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно. Спасибо! Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности. Может быть, ты сможешь как-то это использовать? В деликатесные блюда из крабов это уж точно не положишь. Я ведь уже рассказывал тебе о крабах, правда?" },
    ["1140a"] = { male = "Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса. Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такой закалённый герой, как ты.", female = "Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса. Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такая закалённая героиня, как ты." },
    ["1140c"] = { common = "Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчёт этого, когда в другой раз поеду в Аубердин. Тем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ." },
    ["1141a"] = { common = "Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак. Есть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят. Слушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!" },
    ["1141c"] = { male = "Какие отличные окуни! Большое спасибо за помощь! Ты как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп. У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп.", female = "Какие отличные окуни! Большое спасибо за помощь! Ты как минимум такая же хорошая рыбачка, как моя драгоценная родственница Граун Блумп. У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." },
    ["1143a"] = { common = "Понятно. Ну если то, о чём ты говоришь, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будь начеку, его окружает множество сильных чернокнижников, гораздо более опасных, чем те, с кем тебе доводилось встречаться ранее." },
    ["1143c"] = { common = "Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем ещё лучше подготовлены, чтобы встретить эту угрозу лицом к лицу." },
    ["1144a"] = { common = "Наконец-то, помощь пришла! Ты не представляешь, как долго я уже здесь торчу! Видишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс даёт хорошую цену за растущий здесь корень краснолиста. Ну я и подумал, что на этом можно обтяпать неплохие денежки. Как видишь, жестоко ошибался! Вытащи меня отсюда, я тебе хорошо заплачу!" },
    ["1144c"] = { common = "Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!" },
    ["1195a"] = { common = "Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся ещё со времён сотворения кентавров. Нам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов. Чтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал." },
    ["1195c"] = { common = "Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!" },
    ["1196a"] = { common = "Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъёмнике, что возле южного обрыва Степей. Не удивлюсь, если ты и в дальнейшем будешь нам помогать." },
    ["1196c"] = { common = "Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров." },
    ["1197a"] = { male = "Водой, которую ты принёс, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить. Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса. Будь осторожен – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.", female = "Водой, которую ты принесла, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить. Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса. Будь осторожна – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." },
    ["1197c"] = { common = "От этого копыта исходит странная энергия... Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах. Благодарю вас. Я немедленно приступлю к разгадке тайны, которую вы принесли мне." },
    ["1198a"] = { common = "В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса. Я должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь. Уже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся. Другие мои разведчики заняты насущными делами. Помоги мне найти Талрида." },
    ["1198c"] = { common = "Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план." },
    ["1199a"] = { common = "Черпая силу из старинных обрядов, посвящённых Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих тёмных покровителей и распространить смерть и ужас по всему миру. Мы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса. Что бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться. Объяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены." },
    ["1199c"] = { common = "Нет сомнений – в тебе течёт отважная и благородная кровь. Серебряный Рассвет благодарит тебя за содействие силам добра." },
    ["1200a"] = { common = "Силы оставили меня. Мне необходима твоя помощь! В давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец. Аку'май, слуга Древнего бога, поднялся из глубин. Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы. Убей Келриса и принеси его голову Сельгорму в Дарнасс." },
    ["1200c"] = { male = "Келрис ускользал от нас слишком долго. Кажется, всякий раз, когда в этих землях давало о себе знать зло, Келрис играл в этом какую-то роль. Долгое время мы считали его мёртвым или пропавшим без вести. Теперь всё встало на свои места. Покончив с его правлением, ты спас множество невинных жизней. Свет во имя! Принести жертву прислужнику Древнего Бога ради личной выгоды — это за пределами всякого понимания! Ты совершил великое деяние. От лица Серебряного Рассвета — честь тебе и слава.", female = "Келрис ускользал от нас слишком долго. Кажется, всякий раз, когда в этих землях давало о себе знать зло, Келрис играл в этом какую-то роль. Долгое время мы считали его мёртвым или пропавшим без вести. Теперь всё встало на свои места. Покончив с его правлением, ты спасла множество невинных жизней. Свет во имя! Принести жертву прислужнику Древнего Бога ради личной выгоды — это за пределами всякого понимания! Ты совершила великое деяние. От лица Серебряного Рассвета — честь тебе и слава." },
    ["1221a"] = { common = "Корень синелиста – признанный деликатес в любом уголке мира! Но растёт он только здесь, в Пустошах, глубоко под землёй в Лабиринтах Иглошкурых. К тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землёй. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов! Задачка, конечно, непростая, но если принесёшь мне корней, я хорошо заплачу." },
    ["1221c"] = { male = "Прекрасно! О, я загоню их перекупщикам за очень хорошую цену! Спасибо за работу. Ты вполне надёжный поставщик!", female = "Прекрасно! О, я загоню их перекупщикам за очень хорошую цену! Спасибо за работу. Ты вполне надёжная поставщица!" },
    ["1275a"] = { common = "Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора? Я боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить ещё одну расу злобных монстров. Я хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдёте в Непроглядной Пучине, на побережье Ясеневого леса. Путь неблизкий." },
    ["1275c"] = { male = "Ты проделал долгий путь и, несомненно, столкнулся с множеством опасностей. Твои поступки были бескорыстны. Ради блага всего Азерота ты помогаешь мне в моих исследованиях. Благодарю тебя, за всё, что ты сделал. А теперь, если позволишь… у меня ещё много работы.", female = "Ты проделала долгий путь и, несомненно, столкнулась с множеством опасностей. Твои поступки были бескорыстны. Ради блага всего Азерота ты помогаешь мне в моих исследованиях. Благодарю тебя, за всё, что ты сделала. А теперь, если позволишь… у меня ещё много работы." },
    ["1338a"] = { common = "Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника ещё поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него! Проблема в том... что он живёт далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя! Если ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?" },
    ["1338c"] = { common = "А, заказ от дворфа Грозовой Вершины. Это гордый клан, славный крепкими, сильными дворфами. И их богатством. Большое спасибо. Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины." },
    ["1339a"] = { male = "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли путник вроде тебя справиться с его поручением? Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.", female = "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли путница вроде тебя справиться с его поручением? Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." },
    ["1339c"] = { common = "Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придётся поработать ногами. Зато отличная возможность поискать приключений!" },
    ["1358a"] = { common = "Мой коллега на Калимдоре, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. Хелбрим обосновался в Степях, в деревне под названием Перекрёсток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдёте до Перекрёстка." },
    ["1358c"] = { common = "А, очень хорошо. Если первые результаты верны, токсические свойства этих сердец могут серьёзно продвинуть нас в наших представлениях о ядах. Это долгожданная посылка. Ваша награда за неё – совершенно заслуженная." },
    ["1359a"] = { common = "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! Это просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Её можно найти в главном представительстве нашего Общества в Подгороде." },
    ["1359c"] = { common = "Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе." },
    ["1470a"] = { common = "Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не даётся тебе пока. Я чувствую, как велико твоё желание учиться. Да, ты будешь учиться. В невежестве нет силы. Знание – вот залог нашего могущества. Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле. Я покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы." },
    ["1470c"] = { common = "Хотя ты ещё не прошёл испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле. Пусть тебя не обманывают его небольшие размеры. Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе. Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." },
    ["1471a"] = { male = "Ты наверняка уже видел круг призыва. Только в его пределы ты можешь вызвать демона Бездны. При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии. Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.", female = "Ты наверняка уже видела круг призыва. Только в его пределы ты можешь вызвать демона Бездны. При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии. Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь." },
    ["1471c"] = { male = "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны. Ты сможешь обратить силу, которую недавно испытал на себе, против своих врагов.", female = "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны. Ты сможешь обратить силу, которую недавно испытала на себе, против своих врагов." },
    ["1472a"] = { common = "Сайаады – пожиратели душ, разбивающие сердца и вводящие в искушение. Существа, исполненные зла и изощрённой хитрости. Сказания из уст что праведников, что грешников говорят одно: их женщин называют суккубами, а мужчин – инкубами. Просто так их в наш мир не выманишь. Сайаад не сможет устоять перед сердцами добрых и любящих смертных. Когда он явится в Азерот, можно побороть его и подчинить себе. Ступай в храм и поговори с моим помощником Годриком Фарсаном. Он поможет тебе подобрать приманку." },
    ["1472c"] = { male = "Тебя прислал Карендин? Говоришь, ты путник? Не думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.", female = "Тебя прислал Карендин? Говоришь, ты путница? Не думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." },
    ["1473a"] = { male = "Похоже, ты готов призвать демона Бездны. Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части. Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре. К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.", female = "Похоже, ты готова призвать демона Бездны. Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части. Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре. К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями." },
    ["1473c"] = { common = "А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант. Мы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию." },
    ["1474a"] = { common = "При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу. Остерегайся её чар, даже сила воли может не защитить от них. Если ты победишь, суккуб вернётся в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать её в любой момент." },
    ["1474c"] = { male = "И снова ты справился с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям. А теперь я хочу научить тебя заклинанию призва личного суккуба.", female = "И снова ты справилась с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям. А теперь я хочу научить тебя заклинанию призва личного суккуба." },
    ["1476a"] = { common = "Чтобы поймать суккуба, нужно чистое сердце. Но разве остались среди смертных непорочные сердца? После долгих поисков и расспросов мне удалось найти только двоих. Первый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня у Стены Седогрива. Вторая – Корма Виллард. Она скорбит об утраченной дружбе и бродит по Болотине в поисках подруги. Принеси их сердца Карендину. Но сначала я покажу тебе твои жертвы." },
    ["1476c"] = { common = "А с виду доброе сердце ничем не отличается от любого другого, да? Может быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечёт суккуба." },
    ["1478a"] = { common = "А! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчёт дальнейшего обучения. Можете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника. Его можно найти в Квартале Магов Подгорода, возле Храма Проклятых." },
    ["1478c"] = { common = "Хорошо, я вижу, Агерон нашёл вас. Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдём к вашему обучению. Вам ещё очень много надо узнать." },
    ["1483a"] = { common = "Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть своё. Некоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь. Не навестишь его? Он живёт у западного края Утёса Ветрорезов." },
    ["1483c"] = { common = "Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех! Ха! И всё же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдётся." },
    ["1485a"] = { common = "Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают. Однако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении. Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг. Но прежде чем я научу тебя искусству призывания, принеси мне шесть голов злолбных фамильяров из той пещеры на северо-востоке." },
    ["1485c"] = { common = "Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно. Пусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают." },
    ["1486a"] = { common = "Пока Наралекс погружался в свои кошмары всё глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные. Эти искажённые существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее. Если эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искажённых шкур." },
    ["1486c"] = { male = "Твои услуги не останутся незамеченными. путник. Спасибо тебе за твою неоценимую помощь.", female = "Твои услуги не останутся незамеченными. путница. Спасибо тебе за твою неоценимую помощь." },
    ["1487a"] = { common = "Цели у Наралекса были самые благие. Наш лидер стремился впасть в Изумрудный сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так. Мечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры. В то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей. Отправляйся туда. и уничтожь порченое семя." },
    ["1487c"] = { common = "Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи. Благодарю тебя, и да пребудет тобой удача." },
    ["1489a"] = { common = "На раковинах, что ты мне принёс, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины её возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям. Источник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотэмом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет. Найдёшь его в Громовом Утёсе, на Вершине Старейшин." },
    ["1489c"] = { common = "Приветствую тебя, добро пожаловать. И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелёгким." },
    ["1490a"] = { common = "Я вошёл в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей. Я уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти. Поговори с ней, ты найдёшь её в дальней палатке." },
    ["1490c"] = { common = "Всё верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуёй лица. Я знаю об их злодеяниях, и самое главное, мне известны их планы. Ты должен остановить их." },
    ["1491a"] = { common = "Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удаётся разбогатеть. Кроме того, мне удалось придумать кое-что получше! Существует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить её в напиток! Насколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию." },
    ["1491c"] = { common = "Здорово, ты принёс её! Не терпится опробовать напиток. Я знаю, он принесёт мне много денег! Спасибо. Вот тебе деньги, и, разбогатев, я пришлю тебе ещё, клянусь!" },
    ["1492a"] = { male = "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл. Не мог бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.", female = "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл. Не могла бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." },
    ["1492c"] = { male = "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр. Ну вот, всё готово. Пока, герой.", female = "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр. Ну вот, всё готово. Пока, героиня." },
    ["1498a"] = { common = "Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь. Ступай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек. Как только принесёшь, я возьмусь тебя учить." },
    ["1498c"] = { male = "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости. Учись хорошенько. Вскоре тебе предстоит новый урок.", female = "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкая. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости. Учись хорошенько. Вскоре тебе предстоит новый урок." },
    ["1499a"] = { male = "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами. Думаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты помогал разобраться с бесами – возможно, у неё найдётся для тебя награда.", female = "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами. Думаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты помогала разобраться с бесами – возможно, у неё найдётся для тебя награда." },
    ["1499c"] = { common = "Молодец! Да, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" },
    ["1501a"] = { common = "Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва. Для начала добудь табличку Верги. Чернокнижники из клана Пылающего Клинка похитили её и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны." },
    ["1501c"] = { common = "Молодец. Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали? Они причинили немало вреда вождю, да и нам, чернокнижникам, тоже." },
    ["1502a"] = { common = "Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун'грим Огневзор. Это отшельник, который живёт на вершине холма к востоку от Перекрёстка. Если тебе нужно оружие, воин, отправляйся к Тун'гриму. Чтобы добраться до его жилища, дойди до Перекрёстка и сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине." },
    ["1502c"] = { male = "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно. И раз ты добрался до моего жилища, то я могу предположить, что именно.", female = "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно. И раз ты добралась до моего жилища, то я могу предположить, что именно." },
    ["1503a"] = { common = "Я дам тебе оружие, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы! Они украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие. Найди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки." },
    ["1503c"] = { common = "Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью. Спасибо. Вот твоя награда. Пусть она служит тебе верой и правдой." },
    ["1504a"] = { common = "Посмотри на табличку Верги. Изображённые на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Нииру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны. Тебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле." },
    ["1504c"] = { common = "Молодец! Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть. Знай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды! Однако пусть успех не кружит тебе голову. Впереди куда более сложные задачи!" },
    ["1505a"] = { common = "Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому. Отыщи Уззека. Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам. Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." },
    ["1505c"] = { common = "Приветствую тебя. Ты здесь для обучения?" },
    ["1506a"] = { male = "Эй, ты! Ты ведь путник, верно? Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдёшь его среди старших чернокнижников в расселине Теней. Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.", female = "Эй, ты! Ты ведь путница, верно? Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдёшь его среди старших чернокнижников в расселине Теней. Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." },
    ["1506c"] = { common = "Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться. Тебе пора продолжить своё обучение на чернокнижника. Все прочие дела пока отложи. Надеюсь, с этим проблем не будет?" },
    ["1507a"] = { common = "Пора тебе научиться новому колдовству. Ты научишься вызывать сайаада, чьи чары порабощают разум. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ему не одолеть. Чтобы приманить сайаада, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь. Где? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит." },
    ["1507c"] = { male = "Хм... путник. Ты ещё новичок, но я чую в тебе большие способности. У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются.", female = "Хм... путница. Ты ещё новичок, но я чую в тебе большие способности. У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются." },
    ["1508a"] = { male = "Раз Ган'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку... Ну, если ты готов довериться слепому поводырю, то слушай. Среди утёсов Оргриммара, к западу от башни ветрокрылов, живёт Занкайя. Она ждёт, когда к ней вернётся близкий друг. Ступай к ней.", female = "Раз Ган'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку... Ну, если ты готова довериться слепому поводырю, то слушай. Среди утёсов Оргриммара, к западу от башни ветрокрылов, живёт Занкайя. Она ждёт, когда к ней вернётся близкий друг. Ступай к ней." },
    ["1508c"] = { common = "У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нём до сих пор ни слуху, ни духу..." },
    ["1509a"] = { common = "Моего супруга, Дограна, не так давно отправили служить в Перекрёсток. Это было повышение по службе, он так гордился… Мне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего… Он должен был вернуться неделю назад, а от него до сих пор нет никаких вестей! Может, ты сходишь в Перекрёсток, разузнаешь о нём? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там..." },
    ["1509c"] = { common = "Занкайя? Жена Дограна, да? Слышать-то я о нём слышал, но это не те новости, которые стоит ей передавать. Да нет, не убили его. Но он ранен и сейчас в плену у иглогривов." },
    ["1510a"] = { common = "Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повёл нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать. Они отправили сюда послание, просили троллей из Малака'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся." },
    ["1510c"] = { male = "путник? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра. Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного.", female = "путница? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра. Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного." },
    ["1511a"] = { common = "Я так и думал, что за зельем явится кто-нибудь ещё! Вот оно, бери. Имей в виду, сразу всё ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечёт кровью. На следующее утро пусть выпьет вторую половину. Отнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран." },
    ["1511c"] = { common = "О, как нельзя более кстати! А то Догран уже умирает там, в плену. Это нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании..." },
    ["1512a"] = { common = "Занкайя молода и красива. Зачем ей калека? Несправедливо это будет. Оставь меня. Спасибо тебе. Я предпочёл бы умереть в славной битве, а не влачить это жалкое существование. И прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой." },
    ["1512c"] = { common = "Ну, если ты говоришь, что этого достаточно, я тебе верю. Дай-ка я её оботру... Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба." },
    ["1513a"] = { common = "Отнеси это к кругу призыва в шатре Нииру. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но всё же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников. Когда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся." },
    ["1513c"] = { common = "Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик. Теперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба. С печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты её не забывай: она послужит хорошей защитой от хитростей тёмного демона, который явился к тебе сегодня." },
    ["1515a"] = { common = "Ну, раз уж ты здесь и хочешь завершить своё дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не cмогу, ступай в одиночку. Дограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его ещё не убили, или он не умер от ран. Удачи тебе!" },
    ["1515c"] = { common = "Тьфу, гадость… Однако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придётся отнять. И руку тоже." },
    ["1516a"] = { male = "Что ж, герой, пора! Ты набрался сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости. Стихия земли будет управлять твоей судьбой, станет частью тебя. Готов ли ты? Тебе придётся предстать перед самой Землёй. И тогда ты увидишь многое, что ведомо лишь шаманам. Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее.", female = "Что ж, героиня, пора! Ты набралась сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости. Стихия земли будет управлять твоей судьбой, станет частью тебя. Готова ли ты? Тебе придётся предстать перед самой Землёй. И тогда ты увидишь многое, что ведомо лишь шаманам. Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее." },
    ["1516c"] = { male = "Великолепно! Твой успех доказывает: ты действительно готов. Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной. Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!", female = "Великолепно! Твой успех доказывает: ты действительно готова. Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной. Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!" },
    ["1517a"] = { common = "Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нём. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка. Запомни: сапту можно пить лишь в священном месте, и нигде более! Отыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!" },
    ["1517c"] = { male = "Ах... путник... Земля ликует от того, что ты пришёл сюда. Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", female = "Ах... путница... Земля ликует от того, что ты пришла сюда. Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." },
    ["1518a"] = { male = "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма. Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелив. Оставайся сильным. И ищи мудрости. В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя.", female = "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма. Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелива. Оставайся сильной. И ищи мудрости. В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." },
    ["1518c"] = { male = "Великолепно! Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли.", female = "Великолепно! Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники скажут тебе, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм Земли." },
    ["1519a"] = { male = "Время настало, юный герой. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрёл мудрость. Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания. Если ты готов, твоему взору откроется то, о чём известно лишь нашему народу. Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья.", female = "Время настало, юная героиня. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрела мудрость. Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания. Если ты готова, твоему взору откроется то, о чём известно лишь нашему народу. Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." },
    ["1519c"] = { male = "Отлично. Ты вернулся – а значит, готов к следующему шагу. Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.", female = "Отлично. Ты вернулась – а значит, готова к следующему шагу. Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути." },
    ["1520a"] = { common = "Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворённое с помощью магии зелье позволит тем, чьё сознание открыто, видить стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. Сапта должна быть выпита в только в священном месте и более нигде. Найди шаманское святилище к востоку отсюда и выпей сапту там." },
    ["1520c"] = { male = "Ах... путник... Земля ликует от того, что ты пришёл сюда. Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", female = "Ах... путница... Земля ликует от того, что ты пришла сюда. Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." },
    ["1521a"] = { male = "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотэм, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелив. Оставайся сильным. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя.", female = "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотэм, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелива. Оставайся сильной. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя." },
    ["1521c"] = { male = "Прекрасно! Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники в Калимдоре скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли...", female = "Прекрасно! Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники в Калимдоре скажут тебе, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм Земли..." },
    ["1522a"] = { male = "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом. Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готов к этому. Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт.", female = "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом. Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готова к этому. Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт." },
    ["1522c"] = { male = "Что, тебя Сеарн прислал, да? Ну, на Сеарна положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Сеарн прислал, да? Ну, на Сеарна положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["1523a"] = { male = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готов платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!", female = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готова платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" },
    ["1523c"] = { male = "Хм, тебя Ксанис прислал ко мне? Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готов принять участие в следующей сапе, cапте-огня. Вижу в твоих глазах, огненное желание. Ты попробовал власть на вкус, и теперь, ты готов к большему. Терпение. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должен знать, когда нужно остановить руку.", female = "Хм, тебя Ксанис прислал ко мне? Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готова принять участие в следующей сапе, cапте-огня. Вижу в твоих глазах, огненное желание. Ты попробовала власть на вкус, и теперь, ты готова к большему. Терпение. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должна знать, когда нужно остановить руку." },
    ["1524a"] = { male = "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готов к этому. Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени. Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня.", female = "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готова к этому. Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени. Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня." },
    ["1524c"] = { common = "А, я ошибся! Прошу прощения. Я не знал, что у тебя с собой этот факел. Очень рад познакомиться. Сюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым. Но мы-то с тобой знаем истину, не так ли? Это святилище скрывает от несведущих великую тайну. Для нас эта тайна священна!" },
    ["1525a"] = { common = "Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотэм Огня! Первый шаг – это создать сапту, чтобы связать тебя со стихией огня. Я могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространённое вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях. А вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма." },
    ["1525c"] = { common = "Это как раз то, что надо. Огонь – это не просто хаос и разрушение. Запомни это хорошенько! Огонь – это ещё и жизнь, и творение! Всё в мире взаимосвязано подобным же образом. Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке. Они взаимно уничтожаются, но придают друг другу смысл. Помни об этом! Одновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости." },
    ["1526a"] = { male = "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападёт на тебя, пока ты не будешь готов к этому, однако оно поймёт, что ты его видишь. Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.", female = "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападёт на тебя, пока ты не будешь готова к этому, однако оно поймёт, что ты его видишь. Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." },
    ["1526c"] = { common = "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя. Вы опускаете факел в чашу, и он мгновенно вспыхивает." },
    ["1527a"] = { common = "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвётся и трепещет на ветру. И вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу." },
    ["1527c"] = { common = "Твой дух пылает ярче любого факела! Тебе есть чем гордиться. Не сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений. Позволь мне первым поздравить тебя и вручить тебе новый тотэм..." },
    ["1528a"] = { male = "Вода – твоё будущее, дружище. Вижу, ты уже покорил огонь и, кажись, готов поговорить с Ислен. Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готов. Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном.", female = "Вода – твоё будущее, дружище. Вижу, ты уже покорила огонь и, кажись, готова поговорить с Ислен. Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готова. Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." },
    ["1528c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["1529a"] = { male = "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["1529c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["1530a"] = { male = "Первым делом ты должен понять, что вода означает возрождение. Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода. Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания. Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы.", female = "Первым делом ты должна понять, что вода означает возрождение. Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода. Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания. Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы." },
    ["1530c"] = { male = "Да? М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого путник отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие? Готова поспорить, что мы оба знаем ответ на этот вопрос.", female = "Да? М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого путница отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие? Готова поспорить, что мы оба знаем ответ на этот вопрос." },
    ["1534a"] = { common = "Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей. Добравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звёздной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника." },
    ["1534c"] = { common = "Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе. Я рада, что среди избравших наш путь есть такие, как ты. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах." },
    ["1535a"] = { common = "Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют её. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других. Начнём с малого: ниже моего домика есть пруд с драгоценной влагой." },
    ["1535c"] = { common = "Я предполагала, что если ты возьмёшься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись. Да, для них это плохо, но для других обитателей Степей – скорее хорошо." },
    ["1536a"] = { common = "Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрёкшимися, – Мельнице Таррен. И удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что поражённые чумой жители города осознают его ценность – это малый луч света в царстве тьмы. Набери воду из этого источника в этот бурдюк и принеси мне." },
    ["1536c"] = { common = "Хорошо. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха. Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна." },
    ["1578a"] = { common = "Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться. Мой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если бы вы могли изготовить несколько медных топоров и плетёных поясов и доставить их Торвальду, он был бы очень вам благодарен. Он даже может поделиться с вами своими знаниями. Торвальда вы найдёте в южной сторожевой башне озера Лок Модан." },
    ["1578c"] = { male = "Ох, прости! Я и не понял, что ты пришёл помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут! Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.", female = "Ох, прости! Я и не понял, что ты пришла помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут! Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся." },
    ["1579a"] = { common = "Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна! Так что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами! Точно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезёт..." },
    ["1579c"] = { male = "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самый везучий путник на Калимдоре!", female = "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самая везучая путница на Калимдоре!" },
    ["1580a"] = { common = "Мы знаем, что тебе везёт, но... насколько сильно везёт? Однажды ночью я бродил по дорогам Тёмного Берега. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришёл в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил её в воду! Мне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоёма на Тёмном Берегу?.." },
    ["1580c"] = { male = "Глазам не верю! Ты их нашёл! Ты лучший рыбак на моей памяти! Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении.", female = "Глазам не верю! Ты их нашёл! Ты лучшая рыбачка на моей памяти! Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." },
    ["1581a"] = { common = "Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь! Ты нам не поможешь? Если ты привезёшь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя." },
    ["1581c"] = { common = "Прекрасные снадобья! Ты проявила исключительную щепетильность, что очень важно для алхимика! Вот твои травы, я только-только их собрала. Пусть они тебе пригодятся!" },
    ["1582a"] = { common = "У нас, жителей Дарнасса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймётся испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов. Если ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей." },
    ["1582c"] = { common = "Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник. Слушай. Давай-ка я покажу тебе выкройку жилета Лунного сияния." },
    ["1598a"] = { male = "Ах, это ты! Тебя зовут путник, верно? Надеюсь, ты точно уверен, что желаешь стать чернокнижником, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего. Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно силён. В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги. Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне.", female = "Ах, это ты! Тебя зовут путница, верно? Надеюсь, ты точно уверена, что желаешь стать чернокнижницей, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего. Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно сильна. В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги. Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне." },
    ["1598c"] = { common = "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг. Ладно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!" },
    ["1599a"] = { common = "Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть. Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой. Не беспокойся: я не ставлю это тебе в вину. Что ж, самое простое из заклинаний призыва позволяет вызвать беса. Однако, прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы... Принеси мне три оберега из перьев. Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда." },
    ["1599c"] = { common = "Прекрасно, прекрасно! В самом деле, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись... Впрочем, это не мне решать. Поживём – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрёт внутренности – думаю, подобное могло бы серьёзно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев. Кстати, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – ещё не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией." },
    ["1618a"] = { common = "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются! На Красногорье время от времени устраивают налёты орки Чёрной Горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей." },
    ["1618c"] = { male = "Спасибо. Это чрезвычайно мне поможет. Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск. То, что ты принёс, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить...", female = "Спасибо. Это чрезвычайно мне поможет. Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск. То, что ты принесла, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить..." },
    ["1638a"] = { common = "Ты в самом деле неплохой воин, но лет тебе мало, и ещё многому придётся научиться. Поговори с Гарри Берлгардом – обычно он сидит в \"Свинье и Свистке\", в Старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приёмов, глядишь, и подольше проживёшь." },
    ["1638c"] = { male = "О-хо! Выпей со мной. С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?", female = "О-хо! Выпей со мной. С первого взгляда ты кажешься крепкой, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?" },
    ["1639a"] = { male = "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься. Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку. Ха, если ты знаком с ним, то догадаешься, что так просто он её не отдаст.", female = "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься. Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку. Ха, если ты знакома с ним, то догадаешься, что так просто он её не отдаст." },
    ["1639c"] = { male = "Эй, красавчик! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь...", female = "Эй, красавица! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь..." },
    ["1640a"] = { male = "Что ты хочешь? Да ты спятил! Эту кружку ты получишь только через мой труп...", female = "Что ты хочешь? Да ты спятила! Эту кружку ты получишь только через мой труп..." },
    ["1640c"] = { common = "А ты крепче, чем кажешься с первого взгляда." },
    ["1642a"] = { common = "Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу. Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро. Ныне наступили тяжёлые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его. Однако помни: не борьба со злом отличает нас от прочих жителей Азерота. Сострадание, терпение, отвага и помощь ближним – для паладина всё это значит не меньше, чем искусство воина. Никогда не забывай об этом!" },
    ["1642c"] = { common = "И снова рад приветствовать тебя. Как идёт изучение Фолианта Божественности? Помни: тебе предстоит пройти испытание. Каждого из нас ждёт множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей. Докажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету." },
    ["1643a"] = { common = "Итак, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всём будет полагаться на тебя. Ты возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоём пути – а равно и о том, что значит быть паладином Света." },
    ["1643c"] = { male = "О, привет, дорогой. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке! Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо... Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...", female = "О, привет, милашка. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке! Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо... Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." },
    ["1644a"] = { common = "Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити... Мой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров. Что? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя! Если бы у меня был лён на одёжки малышам, их жизнь стала бы хоть немного легче..." },
    ["1644c"] = { common = "Ах, благодарю, благодарю тебя! Детишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее. Прими мою искреннюю признательность. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет." },
    ["1646a"] = { common = "Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших. Хотя в эти тяжёлые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении. Усвой же это и помни всегда." },
    ["1646c"] = { male = "С возвращением. Надеюсь, ты нашёл время на прочтение книги? Тогда ты должен быть готов к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить. Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света.", female = "С возвращением. Надеюсь, ты нашла время на прочтение книги? Тогда ты должна быть готова к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить. Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." },
    ["1647a"] = { common = "Твоя задача, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту. Сделай это и по выполнении возвращайся ко мне. Тогда мы ещё поговорим о твоём пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Моё наставничество нужно и другим паладинам." },
    ["1647c"] = { common = "СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь. Меня зовут Джон Тернер. Как поживаете? Рад, искренне рад слышать, что у вас всё хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих." },
    ["1648a"] = { common = "Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций. Нынешняя поездка была мучительно медленной и не слишком продуктивной. Если бы мне удалось добыть ещё немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой." },
    ["1648c"] = { common = "Это так прекрасно с вашей стороны. Снова большое вам спасибо. Вы благородный человек, что так помогли мне. Не удивительно, что вы избрали путь Света. Хотел бы я, чтобы был какой-либо способ отплатить вам за всё, что вы сделали... что? Это наименьшее что вы могли сделать? Видите? Это как раз то, о чём я говорю, вы благородны до самого конца. Берегите себя, и да охранит вас Свет в ваших путешествиях." },
    ["1649a"] = { common = "Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары. Твои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим." },
    ["1649c"] = { male = "Ты просишь испытать твою отвагу? Прекрасно! Для тебя в городе и в окрестностях найдётся немало заданий. Нам как раз нужен кто-нибудь с твоими способностями. Это испытание не будет лёгким! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли герой служить правому делу. Чувствуешь ли ты в себе готовность к испытанию?", female = "Ты просишь испытать твою отвагу? Прекрасно! Для тебя в городе и в окрестностях найдётся немало заданий. Нам как раз нужен кто-нибудь с твоими способностями. Это испытание не будет лёгким! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли героиня служить правому делу. Чувствуешь ли ты в себе готовность к испытанию?" },
    ["1650a"] = { common = "Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так! В самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живёт чёта Стивеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остаётся дома одна, без защиты... Донесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда." },
    ["1650c"] = { common = "Здравствуй. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана. Позволь представиться: я – Дафна Стилвелл. Очень приятно! Твоё прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту..." },
    ["1651a"] = { common = "Бьюсь об заклад, они скоро вернутся – так что приготовься. В доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы. Не знаю, сколько их будет, но уверена, что больше, чем в прошлый раз. Моли Свет благословить тебя, потому что… Слышишь? Они идут! Укроемся за домом!" },
    ["1651c"] = { common = "Мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что паладин может справиться с таким количеством врагов зараз. Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..." },
    ["1652a"] = { common = "Прошу, возвращайся к Даториану и передай ему, что теперь со мной всё в порядке – благодаря тебе и Церкви. Он пошлёт весть в Стальгорн, чтобы мой Джордан не волновался за меня. Ох, как я соскучилась по своему мужу! Жду не дождусь его возвращения..." },
    ["1652c"] = { common = "Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь ещё долго ничего не будет угрожать. Отлично! Дафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга. Ты получишь награду за проявленную отвагу." },
    ["1653a"] = { common = "Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить. Джордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надёжных наших приверженцев. Он должен ещё быть в Стальгорне – он любит работать днём за воротами, там где с гор тянет холодным воздухом." },
    ["1653c"] = { male = "Добрый день. Вижу, ты служишь Свету? Что это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным ещё до нынешних своих налётов, но теперь уж королевские советники не смогут этой угрозы отрицать. Что ещё велел передать Даториан? Именно ты и был назначен оберегать мою жену? Тогда ещё раз прими мою благодарность. Не могу придумать лучшего испытания доблести, чем это.", female = "Добрый день. Вижу, ты служишь Свету? Что это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным ещё до нынешних своих налётов, но теперь уж королевские советники не смогут этой угрозы отрицать. Что ещё велел передать Даториан? Именно ты и была назначена оберегать мою жену? Тогда ещё раз прими мою благодарность. Не могу придумать лучшего испытания доблести, чем это." },
    ["1654a"] = { male = "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода. Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придётся добыть необходимые для ковки предметы. Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, герой?", female = "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода. Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придётся добыть необходимые для ковки предметы. Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, героиня?" },
    ["1654c"] = { male = "Великолепно! Ты добыл всё необходимое. Теперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе. Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!", female = "Великолепно! Ты добыла всё необходимое. Теперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе. Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!" },
    ["1656a"] = { common = "Умоляю, помоги мне! У меня ещё есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! Как же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?! Не отнесёшь ли ты их вместо меня? Таверна - такое милое и уютное местечко, там есть всё, чего может пожелать притомившийся путник. Даю слово, тебе понравится!" },
    ["1656c"] = { common = "О, а вот и мои меха! Благодарю вас. Вы доставили их даже быстрее, чем я ожидал. Они послужат отличными одеялами для моих постояльцев. Прошу вас, гостите в таверне, сколько пожелаете. Наши двери всегда открыты, и мы рады каждому. Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога." },
    ["1665a"] = { common = "Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери." },
    ["1665c"] = { common = "А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своём. Молодец. Приступим к обучению..." },
    ["1666a"] = { male = "Ты освоил несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард. Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия. Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием.", female = "Ты освоила несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард. Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия. Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." },
    ["1666c"] = { male = "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкрался, что я принял тебя за гнолла!", female = "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкралась, что я принял тебя за гнолла!" },
    ["1667a"] = { common = "Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание… Некоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришёл в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить! Верни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге." },
    ["1667c"] = { common = "Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности. Вот моё оружие, которое лежит без дела с тех времён, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!" },
    ["1678a"] = { male = "Хорошему воину пристало быть стойким. Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками. Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов. Принеси мне голову Веджрека, и я поверю, что ты не лыком шит.", female = "Хорошему воину пристало быть стойким. Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками. Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов. Принеси мне голову Веджрека, и я поверю, что ты не лыком шита." },
    ["1678c"] = { male = "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок... Ты, может, и не знал, но крепкая защита — жизненно важна для герой. Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники", female = "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок... Ты, может, и не знала, но крепкая защита — жизненно важна для героиня. Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники" },
    ["1679a"] = { male = "Привет тебе, воин! Ты наделён многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь. Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.", female = "Привет тебе, воин! Ты наделена многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь. Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним." },
    ["1679c"] = { common = "А. Я слышал твоё имя от воинов Дун Морога. Надеюсь, ты не всё время проводишь в пивных?" },
    ["1680a"] = { male = "Ты уже освоил несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу. Тормус живёт здесь, в Стальгорне, в Великой Кузне.", female = "Ты уже освоила несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу. Тормус живёт здесь, в Стальгорне, в Великой Кузне." },
    ["1680c"] = { common = "Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу. Не бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?" },
    ["1681a"] = { common = "У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела. Но однажды ученики принесли ему странную руду. Мастер Сталекрут назвал её мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Чёрного Железа. Они поубивали всех! Ступай в мастерскую Сталекрута, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды." },
    ["1681c"] = { male = "Ты нашёл её! Молодец! Надеюсь, что в ходе поисков ты убил целую толпу дворфов Чёрного Железа. Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута. Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства.", female = "Ты нашла её! Молодец! Надеюсь, что в ходе поисков ты убила целую толпу дворфов Чёрного Железа. Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута. Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства." },
    ["1683a"] = { common = "Прежде чем браться за твоё обучение, я хочу испытать твою храбрость. Сатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием. Отыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя. Отыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдёт." },
    ["1683c"] = { common = "Прекрасно сделано. Как приятно знать, что Ворлус побеждён и наш лунный колодец очищен. Приятно видеть юных воинов, стремящихся защитить от порчи наш любимый Тельдрассил. Теперь, давай начнём обучение..." },
    ["1684a"] = { common = "Приветствую тебя, воин. Ты растёшь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель. В Дарнассе, на террасе Воинов, живёт Эланария. Поучись у неё." },
    ["1684c"] = { common = "Приветствую. Говорят, что ты подаёшь надежды. Но надо ещё убедиться есть ли у тебя сила воли, необходимая выбравшему путь воина." },
    ["1685a"] = { common = "И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли. Я уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться. Ты найдёшь его в подвале таверны \"Забитый ягнёнок\". К слову сказать, не стоит много болтать об этом месте..." },
    ["1685c"] = { common = "Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен. Ну, неважно. Когда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?" },
    ["1686a"] = { male = "Ты многому научился. Пора создать для тебя настоящее оружие. Оружие воина. Тебе придётся отправиться за ним на Тёмный берег. Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой. Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи её, забери у неё медальон и собери со дна ящики с элунитом.", female = "Ты многому научилась. Пора создать для тебя настоящее оружие. Оружие воина. Тебе придётся отправиться за ним на Тёмный берег. Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой. Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи её, забери у неё медальон и собери со дна ящики с элунитом." },
    ["1686c"] = { male = "Браво. Ты дал Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие.", female = "Браво. Ты дала Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие." },
    ["1688a"] = { common = "У меня была ученица по имени Сурена Каледон. Помню, она стояла как раз там, где сейчас стоишь ты… Просила меня научить её искусству чернокнижия, а у самой даже капли таланта к этому не было. Хм, зато она была молода и довольно миловидна. Если бы я видел тогда, что это за вероломная дрянь! Распутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур. Об этой потере я нисколько не сожалею, однако колье Кровавого камня, которое я подарил ей, мне всё ещё нужно. Её жизнь для меня больше ничего не значит. Ты найдёшь девку на тыквенной ферме Бреквеллов. Верни мне моё имущество!" },
    ["1688c"] = { common = "Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя. Надеюсь, усилия, вложенные в тебя, прахом не пойдут..." },
    ["1689a"] = { male = "Вернув моё колье и обманув Сурену, ты доказал, что не уступаешь ей в таланте. Поэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше. Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении. Используй магию колье в кругу призыва.", female = "Вернув моё колье и обманув Сурену, ты доказала, что не уступаешь ей в таланте. Поэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше. Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении. Используй магию колье в кругу призыва." },
    ["1689c"] = { common = "Тебе удалось даже больше, чем я ожидал. На это я и надеялся. Теперь ты можешь научиться управлять покорённым тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, ещё увидимся..." },
    ["1692a"] = { common = "Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие. Матиль на юге отсюда, на другой стороне этого здания." },
    ["1692c"] = { common = "А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлён самой богиней Элуной. Выковать элунитовое оружие – великая честь. Подожди, я сейчас примусь за работу..." },
    ["1698a"] = { common = "Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждёт в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание." },
    ["1698c"] = { common = "Ха! Значит, до тебя дошли вести о моём вызове, а? Что ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни." },
    ["1699a"] = { male = "Я называю моё испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"… Вернуться тебе придётся в течение часа. Там полно красногорских гноллов. Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец! Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готов принять Ретбанский вызов?", female = "Я называю моё испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"… Вернуться тебе придётся в течение часа. Там полно красногорских гноллов. Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец! Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готова принять Ретбанский вызов?" },
    ["1699c"] = { male = "Ты справился! Молодец! Трижды ура путник!", female = "Ты справилась! Молодец! Трижды ура путница!" },
    ["1701a"] = { common = "Ну вот, я дал тебе отличный щит, но это ещё не всё. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный. Что скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать." },
    ["1701c"] = { common = "Тебе удалось добыть всё необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами! Что ж, займёмся доспехами..." },
    ["1702a"] = { male = "Да, приняв Ретбанский вызов, ты показал, на что способен. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде. Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу. Вот, отнеси Фьюрену этот боченок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст.", female = "Да, приняв Ретбанский вызов, ты показала, на что способна. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде. Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу. Вот, отнеси Фьюрену этот боченок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст." },
    ["1702c"] = { common = "А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а? Конечно я дам тебе щит, да ещё какой! Такого нигде не найти, честное слово!" },
    ["1703a"] = { common = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живёт довольно далеко, в Дарнассе, но несомненно будет рад, если я поделюсь с ним своими открытиями." },
    ["1703c"] = { common = "Это интересно, очень интересно. Мой коллега Фьюрен, сделал грандиозное открытие. Спасибо. Это будет честью для меня, применять новые технологии к моим разработкам." },
    ["1704a"] = { common = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живёт в Стальгорне, и когда услышит о моём открытии... Он бороду себе выдернет от восторга!" },
    ["1704c"] = { common = "Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга! Фьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!" },
    ["1705a"] = { common = "Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе. Мне понадобится горящая кровь и горящий камень. Единственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер. И не мешкай, во имя Света." },
    ["1705c"] = { common = "Недурно! А теперь, прошу прощения, мне тоже надо поработать..." },
    ["1708a"] = { male = "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты помог Фьюрену, а он мне, я разрешу тебе забрать их себе! Чтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине. Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело.", female = "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты помогла Фьюрену, а он мне, я разрешу тебе забрать их себе! Чтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине. Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело." },
    ["1708c"] = { male = "Вот, то что нужно! Молодец! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет! Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!", female = "Вот, то что нужно! Умница! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет! Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" },
    ["1710a"] = { common = "Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдёт все ожидания. Не поможешь? Если ты принесёшь мне все необходимые материалы, я и для тебя сделаю такие доспехи. Мне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнёздами. Как наберёшь достаточно, возвращайся." },
    ["1710c"] = { common = "Ах, спасибо тебе! Это прекрасно подойдёт! Я начну создавать броню немедленно." },
    ["1715a"] = { common = "Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград. По счастью, Гакин не растяпа, так что ты всё равно узнаешь всё, что тебе надо, но я просто киплю! Короче, ты найдёшь Гакина в подвале \"Забитого ягнёнка\" в Штормграде." },
    ["1715c"] = { common = "Так тебя послал Злобноверт? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечём к себе внимание." },
    ["1716a"] = { common = "Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла. В легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины. Примани демона символом любви, победи его – и он будет тебе служить. Но найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдёшь его в калимдорских Степях возле лагеря Таурахо." },
    ["1716c"] = { common = "Как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь." },
    ["1717a"] = { male = "путник! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать. Ты давненько уже не проходил очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.", female = "путница! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать. Ты давненько уже не проходила очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать." },
    ["1717c"] = { common = "Хорошо, что кто-то, наконец, поймал тебя. Я уже опасался худшего. В тебя вложено слишком много и было бы жалко тебя потерять. Мы ещё поговорим на эту тему позднее.. Твоя тренировка более важна в данный момент." },
    ["1738a"] = { common = "Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашёл то, что тебе нужно. Во время Войны Древних двое влюблённых вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви. Этого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растёт сердцедрево, находятся в северо-западной части Ясеневого леса." },
    ["1738c"] = { common = "Да, сердцедрево нам подойдёт. Дай-ка я немного обработаю древесину... Такар – настоящий кладезь премудростей; с таким не пропадёшь, правда? Если б я только мог убедить его вернуться к цивилизации..." },
    ["1739a"] = { common = "С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале. Не забывай об осторожности, суккубы подчиняли себе и самых стойких заклинателей. После того как вызовешь демона и вернёшь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом." },
    ["1739c"] = { common = "Неплохо, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают. Пора научить тебя обращению с только что подчинённым суккубом. Только не забывай про осторожность!" },
    ["1740a"] = { common = "Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам. Многих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключённых внутри. Шар Соран'рука был расколот надвое. Одну из частей раздробили на ещё более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Тёмного Клыка. Найди их, и я смогу воссоздать этот шар." },
    ["1740c"] = { common = "Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки. Воссоздать их, сделав Соран'рука единым целым, несложно. Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." },
    ["1778a"] = { male = "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, герой.", female = "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, героиня." },
    ["1778c"] = { male = "Итак, ты быстро вернулся, а? И чего же ты достиг за это время? Итак, ты помог достойному делу? Возможно ты уже заслужил уважение граждан Азерота. Скажи мне кому ты помог – и я скажу кто ты… Удивительно , ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в своё время..", female = "Итак, ты быстро вернулась, а? И чего же ты достигла за это время? Итак, ты помогла достойному делу? Возможно ты уже заслужила уважение граждан Азерота. Скажи мне кому ты помогла – и я скажу кто ты… Удивительно , ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в своё время.." },
    ["1779a"] = { male = "Я хочу, чтобы ты взял это. Это называется знак Жизни. Ты показал своё милосердие и терпение, а теперь я хочу, чтобы ты проявил себя не только как воин, но и как целитель. Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа. Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов. Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.", female = "Я хочу, чтобы ты взяла это. Это называется знак Жизни. Ты показала своё милосердие и терпение, а теперь я хочу, чтобы ты проявила себя не только как воин, но и как целительница. Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа. Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов. Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет." },
    ["1779c"] = { male = "*кашляет* Доброго тебе здравия, герой. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна. Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно. У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.", female = "*кашляет* Доброго тебе здравия, героиня. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна. Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно. У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." },
    ["1780a"] = { male = "Я сегодня же отнесу это детям. Ты можешь не тревожиться, герой. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказал, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!", female = "Я сегодня же отнесу это детям. Ты можешь не тревожиться, героиня. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказала, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!" },
    ["1780c"] = { common = "Ты уже здесь? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведённое вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне всё... Что ж, это производит впечатление. Поверь, это поистине поступки того, кто следует путём Света и ставит благо других выше своего собственного. Рано или поздно такое самопожертвование всегда вознаграждается." },
    ["1781a"] = { common = "Прими этот знак Жизни. Тебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. Мой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны. Возьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!" },
    ["1781c"] = { male = "*кашляет* Я рад встрече с тобой, герой. Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока. Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти...", female = "*кашляет* Я рад встрече с тобой, героиня. Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока. Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." },
    ["1783a"] = { common = "Мы выслеживали дворфов Чёрного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздаёт приказы своим воинам. Мы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь. Нарму нужна помощь. И я не успокоюсь, пока он её не получит. Ты ведь поможешь ему?" },
    ["1783c"] = { male = "Не знаю, как мне отблагодарить тебя, брат! Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни. Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.", female = "Не знаю, как мне отблагодарить тебя, сестра! Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни. Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появилась. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." },
    ["1784a"] = { common = "Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Чёрного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги. Кое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Чёрного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймём, что они затевают. Добудь один из приказов и отнеси Майридону." },
    ["1784c"] = { male = "Хаха! Тебе удалось! Ты спас Нарма и нашёл доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность.", female = "Хаха! Тебе удалось! Ты спасла Нарма и нашла доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность." },
    ["1785a"] = { male = "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней. Сдаётся, она хочет перекинуться с тобой парой слов. Да хранит тебя Свет, славный герой. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора.", female = "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней. Сдаётся, она хочет перекинуться с тобой парой слов. Да хранит тебя Свет, славная героиня. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." },
    ["1785c"] = { male = "Сегодня ты оказал большую услугу Стальгорну. Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни. Я научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна.", female = "Сегодня ты оказала большую услугу Стальгорну. Я горда, что ты среди нас, и если ты готова, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни. Я научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." },
    ["1786a"] = { common = "Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам. Мы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить. Хенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!.. И вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь?" },
    ["1786c"] = { male = "Прими мою благодарность, брат. В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин. Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён... Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить. Это свидетельство крепости твоей веры...", female = "Прими мою благодарность, сестра. В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин. Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён... Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить. Это свидетельство крепости твоей веры..." },
    ["1787a"] = { common = "У нас ещё будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах. Увы, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо? Если это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной всё хорошо." },
    ["1787c"] = { common = "Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь!" },
    ["1788a"] = { common = "После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя. Твоя помощь поистине неоценима. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой." },
    ["1788c"] = { male = "Что ж, полагаю, ты можешь гордиться своими свершениями. Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения. Ты сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза. Горний Свет озарил тебя, открой же ему душу.", female = "Что ж, полагаю, ты можешь гордиться своими свершениями. Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достойна того, чтобы принять величайший дар паладинов, – дар воскрешения. Ты сможешь возвращать к жизни павших спутников так же, как вернула к жизни Хенза. Горний Свет озарил тебя, открой же ему душу." },
    ["1806a"] = { male = "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт. Когда всё будет закончено, ты будешь гораздо лучше подготовлен к защите дела Света, уж за это я ручаюсь. Не утаю, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня.", female = "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт. Когда всё будет закончено, ты будешь гораздо лучше подготовлена к защите дела Света, уж за это я ручаюсь. Не утаю, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." },
    ["1806c"] = { common = "Вот оно. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!" },
    ["1818a"] = { common = "Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Тёмной Госпоже, немедленно отправляйся к нему. Страж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем." },
    ["1818c"] = { common = "Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрёкшихся." },
    ["1819a"] = { male = "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич. Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить. Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готов!", female = "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич. Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить. Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готова!" },
    ["1819c"] = { common = "Молодец. Улаг был серьёзным сторонником Плети. Тебе удалось доказать стражам смерти и через них Тёмной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения." },
    ["1820a"] = { common = "Тебе удалось услужить Тёмной Госпоже, пришло время услужить одному из её подданных. Колману Фартингу нужен воин, который сможет отомстить врагам Отрёкшихся. Коулман сидит в таверне \"Петля висельника\", в восточной части Брилла." },
    ["1820c"] = { common = "Да, это правда. Мне нужна помощь закалённого воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрёкшихся. Так что если ты справишься, наградой будет почёт." },
    ["1821a"] = { common = "При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича. Мне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу. Склеп находится севернее мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные Агамонды." },
    ["1821c"] = { common = "А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!" },
    ["1823a"] = { common = "Ты уже опытный воин, и имя твоё на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотэма Гнева? Коли так, отправляйся в Лагерь Таурахо, в Степи. Он ждёт всех воинов, что готовы принять его вызов." },
    ["1823c"] = { common = "Ты хочешь пройти испытание?" },
    ["1824a"] = { common = "Чтобы пройти это испытание, тебе придётся отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незванными, и мне они совсем не нравятся. Принеси их усики. Главное, чтобы они всё ещё дёргались, поэтому тебе придётся поторопиться. Добудь мне усики за отведённое время, и я сочту, что испытание пройдено." },
    ["1824c"] = { male = "Отличная работа! Ты прошёл испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина.", female = "Отличная работа! Ты прошла испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." },
    ["1825a"] = { common = "Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться. Тун'грим живёт на востоке от Перекрёстка, что в Степях." },
    ["1825c"] = { male = "Да, ты пришёл. Отлично, нам с тобой многое придётся обсудить.", female = "Да, ты пришла. Отлично, нам с тобой многое придётся обсудить." },
    ["1838a"] = { common = "Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях. Впрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды. Возьми этот список. Я составлял его не одну ночь, напряжённо вглядываясь в пергамент почти незрячими глазами. Принеси мне всё перечисленное, и я создам тебе первую часть доспеха." },
    ["1838c"] = { male = "Ты принёс всё, что я просил. Теперь дело за мной...", female = "Ты принесла всё, что я просил. Теперь дело за мной..." },
    ["1839a"] = { common = "Кузнец-тролль по имени Ула'елек готов выковать для тебя рукавицы жестокости. Он живёт в Дуротаре, в деревне Сен'джин, вместе со своими собратьями из племени Чёрного Копья, и с нетерпением ждёт твоего прихода." },
    ["1839c"] = { common = "Привет тебе. Старый Тунгрим предупредил меня о твоём приходе, но умолчи он, я не удивился бы твоему появлению. Духи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов." },
    ["1840a"] = { common = "Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости. Его можно найти в Громовом Утёсе, рядом с прудом и центральным тотэмом города." },
    ["1840c"] = { common = "Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?" },
    ["1841a"] = { common = "Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости. Велора трудится в Подгороде Лордерона, в торговом квартале." },
    ["1841c"] = { common = "Тебе нужны набедренники? Отлично! Хм... Тогда кто из нас будет их делать? Шутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать." },
    ["1842a"] = { common = "Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придётся добыть эту самую силу. В северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя её. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам. В этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц." },
    ["1842c"] = { common = "Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольётся в моё творение..." },
    ["1844a"] = { male = "Я сделаю тебе шлем, но прежде докажи, что достоин его. В северной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправитьcя. Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий. Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем.", female = "Я сделаю тебе шлем, но прежде докажи, что достойна его. В северной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправитьcя. Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий. Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." },
    ["1844c"] = { male = "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужил шлем...", female = "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужила шлем..." },
    ["1846a"] = { common = "Чтобы создать набедренники Жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны. Но только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные." },
    ["1846c"] = { male = "Молодец! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься. Что-то у меня не так с чувством юмора...", female = "Умница! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься. Что-то у меня не так с чувством юмора..." },
    ["1858a"] = { common = "Загляни в сумку Тазана и принеси мне то, что найдёшь внутри. Замок там непростой, так что постарайся раздобыть ключ. На трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ." },
    ["1858c"] = { male = "Так-так, интересно... Что ж, ты полностью оправдал моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.", female = "Так-так, интересно... Что ж, ты полностью оправдала моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем." },
    ["1859a"] = { common = "Говори тише! Ну да, я знаю твоё имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности. Судя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно? В общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение." },
    ["1859c"] = { common = "А, это ты! Очень хорошо, что Каплак сумел тебя перехватить. Нам нужно поговорить кое о чём, не в последнюю очередь – о твоём будущем в Раздробленной Руке." },
    ["1860a"] = { common = "У нас, магов, есть одна задача, которая жизненно важня для безопасности Штормграда и Элвиннского леса. Подробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай." },
    ["1860c"] = { common = "Тебя послали мне на подмогу? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело… Какое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем." },
    ["1861a"] = { common = "Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего! Но об этом мы поговорим позже. Для начала надо собрать все доступные сведения. Возьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать её на предмет заражения тлетворной магией." },
    ["1861c"] = { common = "Спасибо. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера. Возьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой." },
    ["1879a"] = { male = "путник! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готов ей помочь? Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.", female = "путница! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готова ей помочь? Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." },
    ["1879c"] = { common = "О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы! Ой, кажется, я немного забегаю вперёд. Начнём сначала!" },
    ["1880a"] = { common = "Мы, маги, не просто щёлкаем пальчиками и создаём забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний! Одно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы! Прошу тебя, верни мне гизмонитор!\"" },
    ["1880c"] = { common = "О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования. Спасибо! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться." },
    ["1881a"] = { common = "У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живёт в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрёкшихся." },
    ["1881c"] = { male = "Привет тебе. Ты правильно поступил, откликнувшись на мой зов, но ещё правильнее будет меня выслушать...", female = "Привет тебе. Ты правильно поступила, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." },
    ["1882a"] = { common = "Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил всё живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрёкшихся, считаем её неуправляемой и недопустимой. Для начала надо понять, проникла ли она в Тирисфаль. Отправляйся на ферму Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся." },
    ["1882c"] = { common = "Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель. Молодец. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться." },
    ["1883a"] = { common = "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай всё, что сможешь. Приди к нему на помощь, и со временем тебе откроются великие тайны." },
    ["1883c"] = { male = "Привет тебе. Хвала тебе, ибо ты ответил на мой зов о помощи. Будем надеяться, что ты справишься с заданием...", female = "Привет тебе. Хвала тебе, ибо ты ответила на мой зов о помощи. Будем надеяться, что ты справишься с заданием..." },
    ["1884a"] = { common = "Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил осквернённые фетиши, груды джуджу, среди домов центрального острова Эха. Из-за этого болеет здешнее зверьё, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы. Необходимо уничтожить эти груды джуджу, прежде чем наши земли изменятся до неузнаваемости." },
    ["1884c"] = { common = "Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии. Твой подвиг во имя Орды достоин всяческой хвалы!" },
    ["1885a"] = { male = "путник? Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперёд... В любом случае, вам лучше встретиться с ним, и поскорее. Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него.", female = "путница? Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперёд... В любом случае, вам лучше встретиться с ним, и поскорее. Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него." },
    ["1885c"] = { common = "Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти." },
    ["1886a"] = { common = "Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придётся сперва доказать свои способности. Не буду лгать: это задание может окончиться твоей гибелью. Мне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь - тебе решать. Пока что это всё, что тебе следует знать. Справишься - узнаешь больше." },
    ["1886c"] = { common = "Неплохо. Первая часть испытания пройдена. Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждёт." },
    ["1898a"] = { common = "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умён, чтобы заподозрить неладное. Лорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства. Поговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалёку от Района Фармацевтов." },
    ["1898c"] = { common = "Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями? Боюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?" },
    ["1899a"] = { common = "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочёл бы иметь дело с тобой." },
    ["1899c"] = { common = "Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание." },
    ["1919a"] = { male = "Ты набираешься знаний и опыта, юный путник. Ты готов приступить к подлинному обучению и принять участие в непрекращающейся тайной войне? Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир.", female = "Ты набираешься знаний и опыта, юная путница. Ты готова приступить к подлинному обучению и принять участие в непрекращающейся тайной войне? Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." },
    ["1919c"] = { common = "У меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром." },
    ["1920a"] = { common = "Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов. Там бродят странные невидимые существа, чувствую там образовался провал Маны. Отправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки. Как только наберёшь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." },
    ["1920c"] = { male = "Ну ты молодец! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир. Ты приносишь сообществу магов всё больше пользы.", female = "Ну ты умница! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир. Ты приносишь сообществу магов всё больше пользы." },
    ["1921a"] = { common = "За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесёшь ей всё необходимое. Само одеяние шьётся из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику. Набери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов." },
    ["1921c"] = { common = "Да, превосходный лён. Из него выйдет отличная ряса. А после того, как я разошью её самоцветами, получится настоящее одеяние для мага!" },
    ["1959a"] = { common = "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеями Орды с просьбой выяснить, что же происходит. Подробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живёт в Квартале Магов Подгорода." },
    ["1959c"] = { common = "Это правда. В нашем городе произошёл выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации… Что подводит нас к разговору о задании." },
    ["1960a"] = { common = "В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии. Возьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберёшь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." },
    ["1960c"] = { common = "Отлично. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе. Если дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придётся готовиться к появлению более серьёзных противников." },
    ["1961a"] = { common = "Тебе пора обзавестись первым облачением мага. Одеяние – знак твоего особого положения, свидетельство твоего достоинства. Для создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают. Отнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов." },
    ["1961c"] = { common = "Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани..." },
    ["1963a"] = { common = "Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернёт Орде былую гордость! Мы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни моё задание! Тролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку." },
    ["1963c"] = { common = "Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри! Вот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!" },
    ["1978a"] = { male = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства. Лорд Вариматрас будет доволен, и раз именно ты совершил это открытие – тебе и сообщать о нём. Ах да, как я мог забыть? Добро пожаловать в ряды стражей смерти.", female = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства. Лорд Вариматрас будет доволен, и раз именно ты совершила это открытие – тебе и сообщать о нём. Ах да, как я мог забыть? Добро пожаловать в ряды стражей смерти." },
    ["1978c"] = { common = "Хм, любопытно. Стражи смерти превосходно справились со своими обязанностями. Судя по всему, ты ждёшь благодарности за свои подвиги. Скоро это станет для тебя привычным делом. Стражам смерти не помешают талантливые новички." },
    ["1998a"] = { male = "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться. Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору. Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание. Ты не обделён талантами и выполнишь поручение безукоризненно. По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер.", female = "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться. Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору. Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание. Ты не обделена талантами и выполнишь поручение безукоризненно. По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." },
    ["1998c"] = { common = "Прекрасно. Ты оказался достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." },
    ["1999a"] = { common = "Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане. Эти сведения удалось вытянуть из одного пленника. Лорд Вариматрас поручил стражам смерти добыть эти документы. Честь выполнить это задание выпала тебе. Для задания понадобится кое-какое снаряжение и умение вскрывать замки. Поговори с Эстеллой Джендри, она поставляет нам обмундирование. Попроси у неё набор инструментов, перед тем как отправляться в путь." },
    ["1999c"] = { male = "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал. Вижу, я был прав, положившись на тебя. Поверь, мальчик мой, ты далеко пойдёшь.", female = "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал. Вижу, я был прав, положившись на тебя. Поверь, девочка моя, ты далеко пойдёшь." },
    ["2038a"] = { common = "Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса. Без вертолёта и взрывчатки движению не обойтись! Верни мне инструменты и отыщи сорвиголовку. За Гномреган!" },
    ["2038c"] = { male = "Ты оказал движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!", female = "Ты оказала движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!" },
    ["2039a"] = { common = "Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полёт над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение. Последний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним." },
    ["2039c"] = { common = "Значит, Гноарн сомневается во мне как в разведчике? Интересно, почему... Ладно, не берите в голову, мне нужна ваша помощь! Нет! Ваша помощь нужна нашему общему делу!" },
    ["2040a"] = { common = "Гномреган захватили трогги! Ситуация крайне тяжёлая, но, быть может, вы cможете помочь. Глубоко под землёй, в Мёртвых копях, находится действующий гоблинский резак. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!" },
    ["2040c"] = { common = "Хорошая работа. Благодаря вам день освобождения Гномрегана приблизился ещё на шаг!" },
    ["2041a"] = { common = "Возможно... Возможно, вы поможете нам в битве за Гномреган. В Штормграде вы найдёте командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек. Вы найдёте её среди дворфов в Штормграде. Удачи." },
    ["2041c"] = { common = "Вы с известиями от центрального командования?" },
    ["2078a"] = { male = "Эй, сухопутное создание, нужно, чтоб ты нашёл моего первого помощника. Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу. Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!", female = "Эй, сухопутное создание, нужно, чтоб ты нашла моего первого помощника. Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу. Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" },
    ["2078c"] = { common = "Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная. Кэп тебя, может, даже пустит палубу драить, если так и дальше пойдёт..." },
    ["2098a"] = { common = "Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов. Первое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии! Когда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Тёмном Берегу звери. Краем глаза я заметил разъярённых крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля..." },
    ["2098c"] = { male = "Ах ты ж, акула собачья! Тебе удалось всё найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт! А кстати, ты не видел моего первого помощника?", female = "Ах ты ж, акула собачья! Тебе удалось всё найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт! А кстати, ты не видела моего первого помощника?" },
    ["2118a"] = { common = "Болезнь расползается по Тёмному Берегу, захватывая сознания и тела всех, до кого добирается. На медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти. Отнеси в лес эту ловушку и положи её на землю. Любой бешеный колючешёрстный медведь, попавший в неё, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда." },
    ["2118c"] = { common = "Наша работа только начинается. Вы готовы к следующему заданию?" },
    ["2138a"] = { common = "Как я и боялся, целительное средство не действует. Меня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешёрстных медведей придётся истребить. Возвращайтесь в лес и уничтожьте двадцать бешеных колючешёрстных медведей. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей." },
    ["2138c"] = { common = "Вы сослужили большую службу Аубердину, но ваша работа на этом не закончена. Отдохните, а затем возвращайтесь ко мне. ...И, укрепитесь духом и разумом для дальнейшего кровопролития." },
    ["2139a"] = { male = "За выживание нашего народа и безопасность наших земель мы платим высокую цену. Ты пролил кровь слуг природы, сразил множество больных зверей. Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго. У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать. Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому. В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её.", female = "За выживание нашего народа и безопасность наших земель мы платим высокую цену. Ты пролила кровь слуг природы, сразила множество больных зверей. Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго. У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать. Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому. В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её." },
    ["2139c"] = { common = "Вы с честью и мужеством сражались на благо Аубердина. В наших измученных войной землях смерть и отчаяние стали нормой. Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укреплённые и безопасные земли Альянса. Спасибо вам. Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага." },
    ["2158a"] = { common = "Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\". Там всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку. Найти \"Гордость льва\" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьёшься!" },
    ["2158c"] = { common = "Наш девиз - покой и отдых для всех усталых и продрогших! Прошу, садись у огня, отдохни с дороги. Хочешь - отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает..." },
    ["2159a"] = { male = "Привет тебе, юный герой. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар. Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться. Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.", female = "Привет тебе, юная героиня. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар. Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться. Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда." },
    ["2159c"] = { common = "Ах да, травы из Тенистой долины! Жаль, что Портанниус сам не смог её доставить - нам с ним много что надо обсудить. Но я всё равно рад получить эту посылку и познакомиться с тобой. Покуда ты здесь - чувствуй себя как дома. Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться! Забота о теле и духе только приблизит тебя к победе! Так что располагайся поудобнее..." },
    ["2160a"] = { common = "Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты всё равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Её нужно отдать хозяину таверны. Ты ведь собираешь заглянуть в таверну, верно? После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух. Так вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев ещё ждать и ждать..." },
    ["2160c"] = { common = "О, гляди-ка, Ручник Ржавозубчик всё-таки прислал припасы! Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят. Я тебе очень благодарен, просто словами не передать, как. Ты тут располагайся, будь как дома, дорога-то была не из лёгких!" },
    ["2161a"] = { male = "Извини... Ты не мог бы мне помочь? У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари! Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут... Не мог бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – герой! Ты, небось, ничего не боишься... Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!", female = "Извини... Ты не могла бы мне помочь? У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари! Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут... Не могла бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – героиня! Ты, небось, ничего не боишься... Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!" },
    ["2161c"] = { male = "А, это еда, которую Укор нёс в далину испытаний. Разве она им не нужна? Что ж, они любят морить голодом вас, героев, во время тренировок. Укрепляет дух, как они говорят! Спасибо, что вернул еду. Я разложу её обратно по полкам... и вот, позволь мне предложить тебе немного подкрепиться! И не забудь отдохнуть здесь, в гостинице. Возможно, ты храбрый герой, готовый покорять мир, но если твои силы истощены, ты не сделаешь ничего полезного ни для себя, ни для Орды.", female = "А, это еда, которую Укор нёс в далину испытаний. Разве она им не нужна? Что ж, они любят морить голодом вас, героев, во время тренировок. Укрепляет дух, как они говорят! Спасибо, что вернул еду. Я разложу её обратно по полкам... и вот, позволь мне предложить тебе немного подкрепиться! И не забудь отдохнуть здесь, в гостинице. Возможно, ты храбрый героиня, готовый покорять мир, но если твои силы истощены, ты не сделаешь ничего полезного ни для себя, ни для Орды." },
    ["2178a"] = { common = "Чувствуете этот восхитительный аромат? Это мой секретный рецепт – свежесваренная похлёбка из долгонога. Настоящий деликатес! Не хотите ли узнать рецепт? Но прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами. Нет, я вовсе не жду, что вы пойдёте, приручите себе одного и приедете ко мне на нём верхом! Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлёбка из долгонога." },
    ["2178c"] = { common = "Фантастика! Попробуйте сами и скажите, что вы думаете об этом!" },
    ["2205a"] = { male = "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за торговца сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена. К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!", female = "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за торговку сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена. К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!" },
    ["2205c"] = { common = "Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьёзным испытанием как физических сил, так и умственных способностей. Ну что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?" },
    ["2206a"] = { common = "Наши полевые агенты сообщают о серьёзной активности Братства Справедливости к югу от Златоземья. В этих донесениях указывается, что братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный Край. Мне нужно, чтобы вы проникли в доки и добыли мне расписание поставок. Скорее всего, портовой начальник носит его при себе. ...и кстати, если вас обнаружат – вы никогда не слышали о ШРУ..." },
    ["2206c"] = { common = "Я потрясён... Потрясён, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк. Возьмите этот клинок. Придёт день, когда ШРУ вновь призовёт вас на службу. Совершенствуйте своё мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен. Вы не заметите нас, но почувствуете, когда мы будем рядом..." },
    ["2218a"] = { common = "Ещё одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу. Что же, сегодня тебе повезло. У Хограла найдётся лекарство для твоего недуга. Вот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению." },
    ["2218c"] = { male = "Стало быть, ты считаешь себя настоящим мерзавцем? Достойным оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?B Только настоящий прохвост так высоко себя ценит! Таких мы и ищем! Добро пожаловать!", female = "Стало быть, ты считаешь себя настоящей мерзавкой? Достойной оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?B Только настоящая прохвостка так высоко себя ценит! Таких мы и ищем! Добро пожаловать!" },
    ["2238a"] = { male = "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит. У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь? Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить? Нам надо, чтобы ты переговорил с Онином Макмолотом в Гномрегане и вернулся с ответом. Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее.", female = "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит. У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь? Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить? Нам надо, чтобы ты переговорила с Онином Макмолотом в Гномрегане и вернулась с ответом. Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее." },
    ["2238c"] = { common = "Тсссс! Тише, балда. Нас подслушивают." },
    ["2239a"] = { male = "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день. Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться. Всё в этом донесении, путник. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.", female = "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день. Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться. Всё в этом донесении, путница. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." },
    ["2239c"] = { male = "Большой крюк? Клянусь собственной бородой! Ты постарался на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг. Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?", female = "Большой крюк? Клянусь собственной бородой! Ты постаралась на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг. Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?" },
    ["2241a"] = { common = "Говорят, что я обезумел от любви. Да, я всё время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а всё плачу о нашей несбывшейся любви. Что в этом плохого? И вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник. Не отнесёшь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока." },
    ["2241c"] = { male = "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться... Не хочешь ли подрядиться на одно дельце, герой?", female = "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться... Не хочешь ли подрядиться на одно дельце, героиня?" },
    ["2242a"] = { common = "Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом. Это сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру - с угрозами или добрым словом, - постигала мрачная судьба. Может, надо подкрасться к нему незаметно? Узнай, что у Сетира Древнего в сумках, и возвращайся ко мне." },
    ["2242c"] = { male = "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому. Ты сослужил добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу.", female = "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому. Ты сослужила добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу." },
    ["2259a"] = { common = "Не бойся, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!" },
    ["2259c"] = { male = "Пора идти дальше, путник, – мир ждёт.", female = "Пора идти дальше, путница, – мир ждёт." },
    ["2260a"] = { common = "Весть о ваших деяниях получила широкую огласку. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами. Дорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул! Вас ждёт целый новый мир. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ." },
    ["2260c"] = { common = "Вы откликнулись на призыв ШРУ, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться." },
    ["2281a"] = { common = "Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, бояться нечего: для тебя найдётся не такое опасное дело. Отправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками." },
    ["2281c"] = { common = "Что, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!" },
    ["2282a"] = { common = "Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достаётся ловкость и проворство, как у старого Люция. Рядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нём – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат." },
    ["2282c"] = { male = "Сумел открыть, да? Неплохая работа. Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта.", female = "Сумела открыть, да? Неплохая работа. Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." },
    ["2298a"] = { common = "И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчёт воровства и что они арестуют некоторых членов Тайного Круга. Да только поди возьми старика Чёрную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твоё имя! Хочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом." },
    ["2298c"] = { common = "Всегда рад видеть в наших рядах ребят Хальфдана!" },
    ["2299a"] = { common = "Где тебя носило? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы. Дуй в Стальгорн как можно быстрее и поговори с Хальфданом!" },
    ["2299c"] = { common = "Говори тише, стража может услышать." },
    ["2300a"] = { common = "Слушай, рыбка, тебя тут Рензик искал. На твоём месте я не заставлял бы его ждать – всё-таки он правая рука Матиаса..." },
    ["2300c"] = { common = "Как насчёт того, чтобы приступить к работе? Или хочешь сначала вздремнуть?" },
    ["2359a"] = { common = "Я за этой башней уже не первую неделю наблюдаю. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи. Кто такие? Мы можем только гадать. Одно я тебе скажу: это не люди. Как бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами. Добудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесёшь Матиасу." },
    ["2359c"] = { common = "Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса. Как явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мёртвых с помощью зелий... выражаясь точнее – ядов. Вы бесполезны для ШРУ, если у вас нет чёткого представления о ядах, особенно когда рецепт того, как поднимать нежить, почти у нас в руках." },
    ["2360a"] = { common = "Произошло то, чего я ожидал. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае. Складывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует её как базу для ввоза контрабанды из Красногорья. Отправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада. Она там прячется, неподалёку от башни. ... и кстати, если вас раскроют – вы никогда не слышали о ШРУ..." },
    ["2360c"] = { common = "Наконец-то Матиас прислал ещё одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей." },
    ["2378a"] = { male = "Ты много сделал для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить. У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре.", female = "Ты много сделала для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить. У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре." },
    ["2378c"] = { common = "Так вот кого могучие союзники прислали Шентулу... Не впечатляет…" },
    ["2379a"] = { common = "Одной твоей решимости ещё недостаточно, чтобы преодолеть препятствия, которые ждут впереди. Поговори с Зандо'заном, чтобы начать учиться на агента Изувеченной Длани. Лишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг." },
    ["2379c"] = { common = "Быть может, Зандо'зан ошибся. Зандо'зан просит прощения." },
    ["2380a"] = { common = "Ты, конечно, далеко ещё не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твоё имя! Ступай на север – эта дорога ведёт в Оргриммар. Отыщи там в расселине Теней Шентула и поговори с ним." },
    ["2380c"] = { common = "Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмёшь – для нас главное незаметность и разнообразные уловки!" },
    ["2381a"] = { common = "Не хочу тебя пугать, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись. Потом их нашли... Частично. В южной части побережья пришвартован пиратский корабль, \"Стрела прилива\". В трюме у него хранится то самое сокровище. На второй палубе устроен пиратский притон, в котором они натаскивают своих воров. Проникни на этот корабль, похить сокровище и принеси его мне. Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!" },
    ["2381c"] = { common = "Немыслимо! Невероятно! Поразительно! Да ты талант. Или же ты самый везучий парень на свете! Вот твоя доля. Думаю, ты найдёшь ей лучшее применение, чем я." },
    ["2382a"] = { male = "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает. путник! У Зандо'зана есть поручение для тебя! путник должен отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!", female = "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает. путница! У Зандо'зана есть поручение для тебя! путница должна отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!" },
    ["2382c"] = { common = "Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезёт…" },
    ["2383a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово." },
    ["2383c"] = { male = "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься. Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживёшь и грядущие испытания. Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин. Удачи! Возвращайся, когда будешь готов.", female = "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься. Рад, что тебе удалось добраться сюда невредимой – будем надеяться, что ты переживёшь и грядущие испытания. Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин. Удачи! Возвращайся, когда будешь готова." },
    ["2438a"] = { male = "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит. Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там. Может, тебе удастся добыть моего ловца снов, герой?", female = "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит. Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там. Может, тебе удастся добыть моего ловца снов, героиня?" },
    ["2438c"] = { common = "Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят. Прими мою благодарность за его возвращение." },
    ["2458a"] = { common = "Торговая Компания... Доводилось тебе слышать про такую? Мы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели. Недавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом. Когда найдёшь башню, используй это сигнальное ружьё, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани." },
    ["2458c"] = { common = "Приятно видеть в здешних местах ещё одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний. В следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои." },
    ["2459a"] = { common = "Изумруд... Он пропал! Мой ловец снов повреждён! К северу от деревни Звёздный Ветер засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зелёным в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна. Найди этот пропавший драгоценный камень. И раз уж ты здесь, истреби заодно и этих зловредных мистиков." },
    ["2459c"] = { common = "Теперь я восстановлю своего ловца снов! Спасибо тебе." },
    ["2460a"] = { common = "Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих. Смотри и повторяй за мной." },
    ["2460c"] = { male = "Молодец! Теперь мы можем продолжать.", female = "Умница! Теперь мы можем продолжать." },
    ["2478a"] = { male = "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится. Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способен, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места! Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.", female = "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится. Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способна, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места! Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар." },
    ["2478c"] = { male = "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену. Да, работа агента Изувеченной Длани опасна. Но ты отлично справился с заданием, герой. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.", female = "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену. Да, работа агента Изувеченной Длани опасна. Но ты отлично справилась с заданием, героиня. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам." },
    ["2479a"] = { common = "Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен. Если кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь." },
    ["2479c"] = { male = "О, герой, какой ты бледненький! А чем это от тебя так мерзко благоухает? Я должен выяснить!", female = "О, героиня, какая ты бледненькая! А чем это от тебя так мерзко благоухает? Я должен выяснить!" },
    ["2480a"] = { common = "Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава. Итак, я должен вылечить тебя и научить пользоваться этим ядом? Дай мне пару минут на изучение токсина." },
    ["2480c"] = { common = "Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь." },
    ["2498a"] = { common = "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я. Торопись, ему нужна наша помощь." },
    ["2498c"] = { common = "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришла. Я обнаружил нечто чрезвычайно тревожное!" },
    ["2499a"] = { male = "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной. Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская! Ты и так уже достаточно помог мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!", female = "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной. Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская! Ты и так уже достаточно помогла мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!" },
    ["2499c"] = { common = "Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари. Печальная история – Дубохмур некогда был великим вождём своих сородичей... но порча поражает всех подряд – и подлых, и благородных. Величина этой опухоли в дрожь бросает, но я обязан исследовать её, чтобы понять, какая зараза терзает древесников. Прими мою благодарность." },
    ["2518a"] = { common = "Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме. Но недавно Сатру постигло безумие. Теперь и её потомство под угрозой. Найди леди Сатру, и положи конец её страданиям. Она обитает у северных границ Тельдрассила, близ Родникового озера. Возьми её серебристые паутинные железы и принеси их мне." },
    ["2518c"] = { common = "Лес оплакивает леди Сатру, но это надо было сделать. Благодарю тебя." },
    ["2519a"] = { male = "Одному некогда великому существу из нашего леса нужна помощь, путник. Это трудное дело, но его надо сделать. Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны.", female = "Одному некогда великому существу из нашего леса нужна помощь, путница. Это трудное дело, но его надо сделать. Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны." },
    ["2519c"] = { common = "Стало быть, тебя прислала сестра Аквинна?" },
    ["2520a"] = { male = "Теперь ты должен закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретёт покой. Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие. Когда закончишь дело, возвращайся ко мне.", female = "Теперь ты должна закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретёт покой. Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие. Когда закончишь дело, возвращайся ко мне." },
    ["2520c"] = { male = "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом. Да примет Элуна ту жертву, что ты принёс ей.", female = "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом. Да примет Элуна ту жертву, что ты принесла ей." },
    ["2541a"] = { common = "Шаман племени Кривой Сосны, который живёт в этих местах, нашёл способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил моё тело и заставил его нападать на любого, кто пытается обследовать обитель Бен'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это! Помоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, принеси его мне!" },
    ["2541c"] = { common = "Прими мою благодарность. Какая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие..." },
    ["2561a"] = { common = "Изучив этот оберег, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу. Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль. Там ты найдёшь моё лишённое души тело... Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны. Чтобы я мог сбежать от них, ты должен уничтожить моё физическое тело. Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне." },
    ["2561c"] = { male = "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе. Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна. Возможно, однажды мы снова встретимся, юный герой. Но пока прими эту награду в знак моей благодарности.", female = "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе. Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна. Возможно, однажды мы снова встретимся, юная героиня. Но пока прими эту награду в знак моей благодарности." },
    ["2607a"] = { common = "Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно всё оборачивается. Лекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь." },
    ["2607c"] = { common = "Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе." },
    ["2608a"] = { male = "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже. Вы, сударь, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это! *Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению!", female = "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже. Вы, детка, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это! *Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению!" },
    ["2608c"] = { common = "Позвольте, я минутку посовещаюсь со своими коллегами. Доктор Монтгомери, мистер Ноарм, все на консилиум!" },
    ["2609a"] = { common = "Однозначно. У вас чтотит. К счастью, от чтотита у меня есть средство. И вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-жёлтого шёлка. Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\". Эту лавку можно найти, если идти вдоль каналов. А теперь поспешите, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!" },
    ["2609c"] = { common = "Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущённо на меня смотреть! Ещё несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!" },
    ["2745a"] = { common = "Хм-м, интересная история, причём не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путём, если уж вы хотите довести дело до конца. С Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны? Решать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом." },
    ["2745c"] = { common = "Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание! Что вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Тёмного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоём в кустах прячемся. Мне нужно блюсти репутацию." },
    ["2746a"] = { common = "Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично. Значит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдёт мимо стражников. Принесите мне немного шелка и пару яблок. Где достать шёлк – думайте сами, а вот подходящие яблоки есть у Клары в её маленьком хозяйстве сразу за городской чертой." },
    ["2746c"] = { common = "Это отлично подойдёт. Прекрасная работа. Вся остальная амуниция у меня в сумке... Слава Свету, у меня есть приятель-портной, сшивший мне шёлковую сумку. А то мне бы уже некуда было рассовывать свои вещи. Прежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать." },
    ["2842a"] = { common = "Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-шесть тысяч\" – лучший способ добраться до Гномрегана. Он уже готов. Если хочешь его испытать, ступай в Пиратскую бухту и поговори со Скути у Гнезда Крыльев Ветра. Из Кабестана туда можно добраться на лодке. Нет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!" },
    ["2842c"] = { common = "Ну, разве она не красавица? Вершина гоблинских транспортных технологий! И десяти раз не взрывалась! Ты не бойся. Больше она не взорвётся, я там всё отладил. Ну, а если тебе не повезёт, ты хотя бы умрёшь быстро и безболезненно!" },
    ["2843a"] = { common = "Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган. Может быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь. Чуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане! А теперь я настрою импульсный повторитель на твой рост и вес." },
    ["2843c"] = { common = "Готово! Когда соберёшься с духом, просто ступи на площадку." },
    ["2904a"] = { common = "Керноби стонет Э-э... Что случилось? Последнее, что я помню, это как меня похитили дворфы Чёрного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам. Вытащи меня отсюда! Сделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдёшь в Пиратскую бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Чёрного Железа тоже как-то связаны с работой над супер-роботом. Идём!" },
    ["2904c"] = { common = "Ты достоин награды за то, что вернул Керноби целым и невредимым. Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." },
    ["2922a"] = { common = "Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объём памяти просто огромен, но всё все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану. Может, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню её." },
    ["2922c"] = { common = "О, какое счастье! Спасибо! Я немедленно начну разбираться с поломкой! Бедный мой Техбот! Потерпи, я тебя вылечу. Так, куда же я засунул свой гидропневмогайковерт..." },
    ["2923a"] = { common = "Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан. Очень жаль. Однако, быть может, его ещё возможно починить. Поговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи." },
    ["2923c"] = { common = "Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?" },
    ["2926a"] = { common = "С самого дня нашего бегства из города Гноарном думает только о том, как выставить троггов из Гномрегана и очистить город от заражения. У нас с Раззлом есть некоторые идеи на этот счёт, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы ещё не знаем, сработает ли наш замысел – надо всё как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облучёнными троггами в Гномрегане. Это зелёная светящаяся субстанция. Наполни ею этот фиал и принеси мне!" },
    ["2926c"] = { common = "Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!" },
    ["2927a"] = { male = "Вы ведь не думаете, что я всегда был лысым? Нет, сударь! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всём Азероте. *Гноарн потрясает в воздухе кулаком.* Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!! Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнёром Раззлом как раз пытаются решить эту проблему.", female = "Вы ведь не думаете, что я всегда был лысым? Нет, сударыня! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всём Азероте. *Гноарн потрясает в воздухе кулаком.* Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!! Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнёром Раззлом как раз пытаются решить эту проблему." },
    ["2927c"] = { common = "Я думал, что утрата волос нашим выдающимся главой убьёт его, так нет, выжил! Я стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть! И тогда он обрушился на троггов! *Оззи ёжится.*" },
    ["2928a"] = { common = "Это ужасно. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог. Что нам точно нужно – так это детали. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище. Я хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить." },
    ["2928c"] = { common = "Это отлично подойдёт. Считайте, что одна автогиробуроройка отремонтирована. Осталось ещё триста девяносто восемь." },
    ["2962a"] = { common = "Этого образца не только недостаточно для опытов, он ещё и загрязнён. Нам нужно более сильное зелёное свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придётся отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придётся сделать несколько попыток, пока вы не принесёте достаточное количество образцов." },
    ["2962c"] = { common = "*Оззи рассматривает вас.* Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!" },
    ["2983a"] = { male = "Много времени прошло с тех пор, как ты прошёл последнее испытание. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты готов заплатить за это знание. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!", female = "Много времени прошло с тех пор, как ты прошла последнее испытание. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты готова заплатить за это знание. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!" },
    ["2983c"] = { male = "Что, тебя Сварт прислал, да? Ну, на Сварта положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Сварт прислал, да? Ну, на Сварта положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["2984a"] = { male = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готов платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!", female = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готова платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" },
    ["2984c"] = { male = "Что, тебя Нарм прислал, да? Ну, на Нарма положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Нарм прислал, да? Ну, на Нарма положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["2985a"] = { male = "Похоже, ты готов к новому испытанию. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Похоже, ты готова к новому испытанию. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["2985c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["2986a"] = { male = "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["2986c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["2997a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестёр – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя. Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе." },
    ["2997c"] = { common = "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." },
    ["2998a"] = { male = "Приветствую тебя, брат мой. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать. На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время. Ищи его в Соборе Света: там он проводит большую часть времени.", female = "Приветствую тебя, сестра моя. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать. На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время. Ищи его в Соборе Света: там он проводит большую часть времени." },
    ["2998c"] = { common = "Как красив Штормград, не правда ли?.. Твой визит в это время более чем уместен." },
    ["2999a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестёр – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается." },
    ["2999c"] = { common = "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." },
    ["3000a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас. YТы можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии." },
    ["3000c"] = { common = "Приветствую и добро пожаловать." },
    ["3065a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово." },
    ["3065c"] = { male = "Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!", female = "Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готова продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" },
    ["3082a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." },
    ["3082c"] = { male = "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен'шан не забудет о тебе. Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждёт большое будущее – помни это! Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готов.", female = "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен'шан не забудет о тебе. Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждёт большое будущее – помни это! Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готова." },
    ["3083a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." },
    ["3083c"] = { male = "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится. Когда почувствуешь, что готов — приходи ко мне, и я подумаю, чему научить тебя дальше. А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву. Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь.", female = "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится. Когда почувствуешь, что готова — приходи ко мне, и я подумаю, чему научить тебя дальше. А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву. Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь." },
    ["3084a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." },
    ["3084c"] = { common = "Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия. Наша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу." },
    ["3085a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Кен'джая, наставника жрецов. Он хочет с тобой поговорить." },
    ["3085c"] = { male = "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше... В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готов. И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся! Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай.", female = "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше... В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готова. И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся! Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай." },
    ["3086a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Май'ах, наставницы магов. Она хочет с тобой поговорить." },
    ["3086c"] = { male = "Да, скоро ты станешь очень могущественным! И всё это узнают... некоторые – на собственной шкуре! Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее. Когда решишь, что готов учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!", female = "Да, скоро ты станешь очень могущественной! И всё это узнают... некоторые – на собственной шкуре! Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее. Когда решишь, что готова учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!" },
    ["3087a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." },
    ["3087c"] = { common = "Когда мы закончим беседу, поговори с остальными обитателями долины. Они будут просить тебя что-нибудь сделать для них – и каждое такое задание будет для тебя проверкой на прочность. Наберёшься мудрости и опыта – приходи к Джен'шан, она научит тебя новым приёмам и навыкам. Возвращайся к Джен'шан как можно чаще." },
    ["3088a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." },
    ["3088c"] = { male = "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готов, и мы посмотрим, чему можно тебя научить.", female = "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готова, и мы посмотрим, чему можно тебя научить." },
    ["3089a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." },
    ["3089c"] = { male = "Ты станешь тем, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готов.", female = "Ты станешь той, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готова." },
    ["3090a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Я лично стараюсь не иметь дела с чернокнижниками, однако ты его всё-таки прочитай, когда время будет. Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить." },
    ["3090c"] = { common = "Теперь и ты в наших рядах! Но не обманывайся. Да, ты имеешь доступ к могуществу, которому многие завидуют, но это не означает, что к тебе будут относиться с почтением. Тралл пускает нас в Оргриммар, ведь мы его сородичи – а иначе мы стали бы такими же жалкими, как люди, что держали его в рабстве. И всё же будь осторожен. Да, в твоих руках могущество, но если будешь глуп, – погибнешь. Понадобятся новые заклинания – приходи ко мне." },
    ["3091a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоём месте я бы прочитал её поскорее." },
    ["3091c"] = { male = "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе. Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готов, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!", female = "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе. Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готова, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!" },
    ["3092a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоём месте я бы прочитал её поскорее." },
    ["3092c"] = { common = "А моя задача — подготовить тебя, обучив основам нашего ремесла: как приручать питомца, как метко стрелять из ружья и многим другим навыкам, которые тебе пригодятся. Охотники — важная часть нашей традиции и истории. Помни об этом: ты — неотъемлемая часть племени. Если будешь служить народу с честью, тебя будут уважать и почитать." },
    ["3093a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы. На твоём месте я бы прочитал её поскорее." },
    ["3093c"] = { male = "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильным... чуть более подготовленным. Твой дух будет пылать подобно Неугасимому пламени. А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь.", female = "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильной... чуть более подготовленной. Твой дух будет пылать подобно Неугасимому пламени. А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь." },
    ["3094a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта. На твоём месте я бы прочитал её поскорее." },
    ["3094c"] = { male = "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готов. Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению.", female = "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готова. Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению." },
    ["3095a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3095c"] = { male = "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты был достойным бойцом. А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сам со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.", female = "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты была достойной воительницей. А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сама со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом." },
    ["3096a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3096c"] = { common = "Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю всё возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков." },
    ["3097a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3097c"] = { male = "Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокажённые будут звать тебя Господином. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придёт время, ты был готов. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.", female = "Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокажённые будут звать тебя Госпожой. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придёт время, ты была готова. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время." },
    ["3098a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3098c"] = { common = "Тебе стоит возвращаться ко мне почаще, если ты хочешь обрести достаточно сил для уничтожения наших недругов. Законы магии по-прежнему относятся и к тебе. Ты узнаешь, что скверна следует за тобой по пятам, аки тать в ночи. Ты узнаешь, что её прикосновение сродни пагубной страсти. Она будет льнуть к тебе, как трепетный любовник. И всё же ты можешь избежать её. Скверна обретёт власть над тобой, только если ты ей это позволишь. А сейчас иди... возвращайся, когда силы твои возрастут." },
    ["3099a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3099c"] = { common = "Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовёт нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять своё. Я буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю." },
    ["3100a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Ллана, местного наставника воинов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3100c"] = { common = "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение. Я тут в любое время дня и ночи. Рыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться. Удачи!" },
    ["3101a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать брата Самуэля, местного наставника паладинов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3101c"] = { male = "Тебе следует усвоить ещё пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги. Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовым, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, герой!", female = "Тебе следует усвоить ещё пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги. Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовой, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, героиня!" },
    ["3102a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Джорика, одного из наших местных наставников. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3102c"] = { common = "Многим очень нужны наши умения. Искатели приключений, ШРУ... ха, даже Братство Справедливости не прочь заслать пару-другую шпионов в Штормград. Но не забывай: ты сама себе хозяйка. И не давай никому втягивать тебя в то, что тебе не по нраву! Кроме того, у нас все козыри... по крайней мере, пока не кончена игра. Смекаешь? Короче, я хотел всего лишь представиться и дать тебе понять, что если тебе понадобится обучение, я всегда здесь. Приходи в любое время." },
    ["3103a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Анетты, местной наставницы жрецов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3103c"] = { common = "Как только ты наберёшься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями. А пока ступай с милосердием в сердце, и пусть мудрость ведёт тебя. Помни, мир станет лучше, только если мы сами исцелим его." },
    ["3104a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Келдена, местного наставника магов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3104c"] = { male = "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готов принять свою судьбу? Готов бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу? Не скрою, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее.", female = "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готова принять свою судьбу? Готова бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу? Не скрою, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее." },
    ["3105a"] = { common = "Меня просили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём печать Друзиллы, одной из наших местных наставниц. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве." },
    ["3105c"] = { common = "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя. Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть. Особенно тот, кто имеет дело с тварями из Круговерти Пустоты. Будь терпелив и благоразумен... но не давай благоразумию подавлять твои амбиции. Как только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства." },
    ["3106a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3106c"] = { common = "Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей. Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди, и даже трогги. А вообще, тебе ещё многое предстоит узнать. Я буду учить тебя воинскому мастерству. Если захочешь узнать пару новых приёмов, приходи сюда, и мы посмотрим, что я могу для тебя сделать." },
    ["3107a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3107c"] = { male = "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение. Думаю, нам обоим придётся немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далёкие странствия неподготовленным, верно?", female = "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение. Думаю, нам обоим придётся немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далёкие странствия неподготовленной, верно?" },
    ["3108a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3108c"] = { male = "Всегда нужно помнить об уважении к тому миру, в котором мы живём. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна. Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готов, приходи ко мне, и мы займёмся твоим обучением.", female = "Всегда нужно помнить об уважении к тому миру, в котором мы живём. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна. Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готова, приходи ко мне, и мы займёмся твоим обучением." },
    ["3109a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3109c"] = { male = "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик... Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет. Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится.", female = "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласна? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик... Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет. Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится." },
    ["3110a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3110c"] = { male = "Я – тот, кто будет заниматься твоим обучением. Когда будешь готов, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов. Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновался? Это тебя ни к чему не обязывает... ну, почти ни к чему...", female = "Я – тот, кто будет заниматься твоим обучением. Когда будешь готова, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов. Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновалась? Это тебя ни к чему не обязывает... ну, почти ни к чему..." },
    ["3112a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3112c"] = { common = "Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю всё возможное, чтобы ты и твои родичи смогли отвоевать свой дом. Да, вот ещё что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!" },
    ["3113a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3113c"] = { common = "Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или ещё что, приходи в любое время. Ну, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?" },
    ["3114a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3114c"] = { common = "О, да! Тайная магия... Конечно-конечно... Первое, что тебе следует усвоить, – это очень простой урок: не ищи неприятностей. Поверь, они найдут тебя сами. А если ты сбережёшь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя. Да, ещё совет: держись подальше от Гномрегана. Пока, думаю, с тебя хватит. Доброго тебе пути! Захочешь подучиться – приходи в любое время." },
    ["3115a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне. Да, вот ещё что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют." },
    ["3115c"] = { male = "Но всё это не имеет значения. Важно лишь одно — ты узрел свой собственный Святой Свет. Ты понял, откуда приходит истинная сила. Ты осознал, что иметь собственных союзников куда... разумнее. Особенных союзников. Таких, что будут повиноваться до последнего вздоха. И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям.", female = "Но всё это не имеет значения. Важно лишь одно — ты узрела свой собственный Святой Свет. Ты поняла, откуда приходит истинная сила. Ты осознала, что иметь собственных союзников куда... разумнее. Особенных союзников. Таких, что будут повиноваться до последнего вздоха. И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям." },
    ["3116a"] = { common = "Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии." },
    ["3116c"] = { common = "Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. Но всё это сейчас не в счёт. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю всё возможное, чтобы помочь тебе." },
    ["3117a"] = { common = "Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне." },
    ["3117c"] = { common = "Когда обретёшь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности. Это опасные времена, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить. Да хранит тебя Элуна, я буду ждать твоего возвращения." },
    ["3118a"] = { common = "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну." },
    ["3118c"] = { common = "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно. Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена ещё большего недоверия. Помни об этом. По мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоём обучении. Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием." },
    ["3119a"] = { common = "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде." },
    ["3119c"] = { common = "Пока что не беспокойся о мире за пределами Тельдрассила – ещё успеешь. Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит. Помогай им в том, в чём сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама." },
    ["3120a"] = { common = "Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту." },
    ["3120c"] = { common = "Отныне я буду твоим наставником. Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна. По мере обучения ты узнаешь больше о нашем сонном трансе. Но пока что приходи ко мне так часто, как сочтёшь нужным, и я обучу тебя всему, следуя традициям ночных эльфов." },
    ["3221a"] = { common = "Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали." },
    ["3221c"] = { common = "О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания." },
    ["3261a"] = { common = "Вот и закончились наши уроки. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем." },
    ["3261c"] = { common = "Приветствую тебя, юноша. Ты избрал путь охотника? Замечательно. Начнём с азов." },
    ["3281a"] = { male = "Ящеров-то ты убил, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда. Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне.", female = "Ящеров-то ты убила, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда. Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне." },
    ["3281c"] = { common = "Ага! Значит, ящеры всё же утащили его в своё логово. Трудно понять, зачем этим тварям серебро. Быть может, в байках об их уме есть зерно правды! Спасибо. Прими награду за услуги и помни, что стражи перекрёстков получили свою месячную оплату лишь благодаря тебе." },
    ["3301a"] = { common = "Одна из моих соплеменниц, Муура Рунический Тотэм, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу. Возьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место." },
    ["3301c"] = { common = "Что это? Панцирь светится изнутри, словно в нём по-прежнему теплится жизнь. Удивительно! Надо изучить его внимательнее. Спасибо. Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора." },
    ["3361a"] = { common = "Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут всё пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто ещё жив – разбрелись по Дун Морогу... Я так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали всё к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Всё, всё уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни... Путешественник из меня никудышный, так я вот тут подумал: может, ты у них заберёшь мои вещи и вернёшь их мне?" },
    ["3361c"] = { common = "Ага! Есть! Есть! Тебе удалось найти мои вещи! Я спасён!.. Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания." },
    ["3364a"] = { common = "Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то! Ты на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей ещё минут пять, а Дарнан вовсе не охлаждённую бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда. Благодарю заранее... и вот ещё что: не забудь вернуть мою кружку!" },
    ["3364c"] = { common = "Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет." },
    ["3365a"] = { common = "Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денёк нет ничего лучше глотка горячей бражки! Даже на душе теплее становится! Вот, держи; сделай доброе дело, отнеси эту кружку Нори, ладно?" },
    ["3365c"] = { common = "Спасибо! Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку. А кружки-то, между прочим, на деревьях не растут! Ну, по крайней мере, в наших краях. Тут у меня есть кое-что для тебя. Я так думаю, усердие нужно вознаграждать, верно ведь?" },
    ["3366a"] = { common = "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство. Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." },
    ["3369a"] = { common = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара. Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь. Хамуул Рунический Тотэм с Вершины Старейшин, вот кого тебе надо найти. Отправляйся на Громовой Утёс, точнее сказать не могу." },
    ["3369c"] = { male = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… *Хамуул вглядывается в осколок.* Ох... Боги… Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь.", female = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… *Хамуул вглядывается в осколок.* Ох... Боги… Спасибо, что принесла это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь." },
    ["3370a"] = { common = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара. Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь. Матренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу." },
    ["3370c"] = { male = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… *Хамуул вглядывается в осколок.* Ох... Боги… Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь.", female = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… *Хамуул вглядывается в осколок.* Ох... Боги… Спасибо, что принесла это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь." },
    ["3376a"] = { male = "путник – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим. Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты принёс мне голову их вождя! Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.", female = "путница – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим. Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты принесла мне голову их вождя! Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." },
    ["3376c"] = { male = "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому! Ты заслужил эту награду, юный герой.", female = "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому! Ты заслужил эту награду, юный героиня." },
    ["3513a"] = { common = "Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому? На севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идёт речь о ночных эльфах, именно туда его и надо отнести." },
    ["3513c"] = { male = "Та-ак... И где ты это нашёл?", female = "Та-ак... И где ты это нашла?" },
    ["3514a"] = { common = "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя. Она уже не встретится с гонцом, у которого ты нашёл этот свиток, хе-хе, но так просто им это не пройдёт. Орда не потерпит такого нахальства. Ступай в Пещеру Когтей. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли." },
    ["3514c"] = { male = "Да ты силён! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо.", female = "Да ты сильна! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо." },
    ["3519a"] = { common = "Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьёзно отравлен. Помоги мне! Пожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне. Спеши... Как голова кружится…" },
    ["3519c"] = { common = "Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчёт пауков!" },
    ["3521a"] = { common = "Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты. Мне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Ещё мне нужны лунные лилии, что растут только вокруг прудов. Последний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенётников, что отравили Иверрона." },
    ["3521c"] = { male = "Хвала Элуне – ты так быстро собрал все ингредиенты! Подожди минутку, сейчас я приготовлю противоядие.", female = "Хвала Элуне – ты так быстро собрала все ингредиенты! Подожди минутку, сейчас я приготовлю противоядие." },
    ["3522a"] = { common = "Противоядие готово. Пожалуйста, проследи, чтобы Иверрон его выпил. И запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени. Поторопись, во имя Элуны!" },
    ["3522c"] = { male = "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.* Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает. Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенётников...", female = "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.* Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает. Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистила мне дорогу через этот лес, полный мерзостных чащобных тенётников..." },
    ["3524a"] = { common = "Громадные морские твари выбрасываются на пески Тёмного Берега и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег всё чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу. Одни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из клана Серой Мглы. Не могли бы вы сходить туда и принести мне для изучения кости этой твари?" },
    ["3524c"] = { common = "Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью. Ваш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом..." },
    ["3681a"] = { male = "Я вынужден прервать твоё путешествие, путник. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения. Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов. Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.", female = "Я вынужден прервать твоё путешествие, путница. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения. Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов. Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света." },
    ["3681c"] = { male = "Добро пожаловать в Собор Света, герой.", female = "Добро пожаловать в Собор Света, героиня." },
    ["3741a"] = { common = "Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже всё кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда? Пожалуйста, достаньте нам ожерелье." },
    ["3741c"] = { male = "Спасибо, что достали мне ожерелье, господин герой... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?", female = "Спасибо, что достали мне ожерелье, госпожа героиня... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" },
    ["3765a"] = { male = "Штормград – невероятно суматошный город. Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам. Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине. Это путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, герой.", female = "Штормград – невероятно суматошный город. Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам. Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине. Это путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, героиня." },
    ["3765c"] = { common = "О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить." },
    ["3901a"] = { male = "Ты уже продемонстрировал свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением. Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивался до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне.", female = "Ты уже продемонстрировала свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением. Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивалась до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне." },
    ["3901c"] = { male = "Отличная работа. Ты показал, что достоин свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся. Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, герой.", female = "Отличная работа. Ты показала, что достойна свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стала, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся. Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, героиня." },
    ["3902a"] = { common = "Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! Нам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! А теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается." },
    ["3902c"] = { common = "Отличная работа, я так и думал, что ты не совсем бесполезное существо. А это тебе – одна из лучших вещичек среди тех, что мы собрали." },
    ["3903a"] = { male = "Ты показал себя надёжным герой. Да и тяжёлой работы не боишься, не правда ли? У меня есть подруга, Милли Осворт. У неё какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.", female = "Ты показала себя надёжной героиня. Да и тяжёлой работы не боишься, не правда ли? У меня есть подруга, Милли Осворт. У неё какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь." },
    ["3903c"] = { common = "О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу. Возможно, ты мне поможешь." },
    ["3904a"] = { common = "Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут! Прошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке. Принеси мне мой виноград, пожалуйста!" },
    ["3904c"] = { male = "Ох, спасибо тебе. Ты спас мой урожай! И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят! Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!", female = "Ох, спасибо тебе. Ты спасла мой урожай! И, надеюсь, ты показала этим бандитам, что тут им хозяйничать не позволят! Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!" },
    ["3905a"] = { common = "Теперь, когда мой урожай спасён, отнеси это уведомление о поставке винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград. Брата Нилза ты найдёшь в аббатстве, в звоннице – он там любит... дегустировать вино." },
    ["3905c"] = { common = "Так, что у нас тут... Хвала Свету! Виноград Милли спасён! Когда она сказала мне, что эти бандиты разнесли её виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула! И благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет!" },
    ["3911a"] = { common = "У меня есть работа для тех, кто не боится сунуться в глубины! Клан Чёрного Железа научился создавать чрезвычайно мощных големов. Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без неё можешь не возвращаться! По усердию и награда." },
    ["3911c"] = { common = "Замечательно! Я немедленно отправлю их курьером в Подгород! Для вас - оплата, как и было обещано." },
    ["3921a"] = { common = "Мне кажется, я сломал самофланж. Это плохо, потому что я успел рассказать о нём нескольким коллегам из Нижней шахты, и они очень заинтригованы. Надо починить его! Отнеси сломанный самофланж Венаки Бенике, который живёт на юге от заставы Мор'шан, лагеря Орды между Степями и Ясеневым лесом. Она очень умная и любопытная. Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его." },
    ["3921c"] = { common = "Что это? Самофланж, говоришь? Что такое самофланж?? А... Посмотри, как он вибрирует, когда берёшь его в руки. А внутри жужжат сложные шестерёнки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?" },
    ["3922a"] = { common = "Я готова заняться самофланжем, но для этого мне понадобятся запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча. Проще всего их достать у Нефтяного болота на востоке. Торговая Компания обычно хранит их в вёдрах с инструментами. Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся." },
    ["3922c"] = { common = "О, ты принёс их! Теперь я могу приступить к работе..." },
    ["3923a"] = { common = "Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже. Отнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало. Он работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести." },
    ["3923c"] = { common = "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях? Интересно, это говорит о смелости или о глупости?" },
    ["3924a"] = { common = "Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надёжным своим сторонникам. Я не входил в число избранных... Начальник Медноклин работает в северо-восточной части Степей, на Каменном карьере." },
    ["3924c"] = { common = "Ты принёс руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них. Я тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу..." },
    ["4021a"] = { common = "Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада! Выступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром'зар. Одолей его и принеси в доказательство кусок его знамени. Не подведи меня." },
    ["4021c"] = { common = "Получилось! Ты победил клан Колкар! Я непременно сообщу Траллу о твоих подвигах. Можешь гордиться собой, ты – достойный сын Орды." },
    ["4161a"] = { male = "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\". Изучение прошлого – важный шаг на пути героя, так что слушай внимательно всё, что я расскажу тебе. Кальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей. Это равновесие позволяло нам вершить многое. Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.", female = "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\". Изучение прошлого – важный шаг на пути героини, так что слушай внимательно всё, что я расскажу тебе. Кальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей. Это равновесие позволяло нам вершить многое. Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." },
    ["4161c"] = { common = "Всегда помни то, что я ныне показал тебе. Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена." },
    ["4402a"] = { common = "Ну и жарища у нас в Долине Испытаний! Галгар утирает пот со лба. Были бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства. Знаешь что? Принеси-ка мне десяток плодов кактуса, и я приготовлю для тебя несколько порций десерта. Пригодится в путешествиях. Плоды кактуса можно собрать с тех, что растут вокруг." },
    ["4402c"] = { common = "Замечательно! А вот и твой кактусовый десерт, как было обещано. И ещё кое-что в придачу..." },
    ["4495a"] = { common = "Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришёл – он задерживается уже на несколько часов. Признаться, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков! Послушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?" },
    ["4495c"] = { male = "Я рад, что тебе удалось найти меня. Как ты узнал, что я тут?", female = "Я рад, что тебе удалось найти меня. Как ты узнала, что я тут?" },
    ["4641a"] = { male = "Ну вот, ты и стал взрослым... достаточно взрослым, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься! Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.* Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юный герой. Горнека ты найдёшь в Логове, на западе.", female = "Ну вот, ты и стала взрослой... достаточно взрослой, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься! Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.* Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юная героиня. Горнека ты найдёшь в Логове, на западе." },
    ["4641c"] = { male = "Очередной рекрут Калтунка? Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!", female = "Очередной рекрут Калтунка? Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравая воительница Орды!" },
    ["4681a"] = { common = "Та тварь на берегу – не единственная на Тёмном Берегу. Вдоль побережья их ещё много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас. Кстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!" },
    ["4681c"] = { common = "Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьёзные шансы узнать, почему эти твари выбрасываются на отмели Тёмного Берега. Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня. Если вы наткнётесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать. Наши исследования здесь пока на начальной стадии. От имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас!" },
    ["4722a"] = { common = "Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Тёмный Берег. Плоть её уже объели мурлоки, обосновавшиеся неподалёку от останков. Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд." },
    ["4722c"] = { common = "Ещё одна находка, которую нам надо изучить. Хорошая работа! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." },
    ["4723a"] = { common = "Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Тёмном Берегу, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить её сюда. В то время как некоторая часть костей уже начисто обглодана, останков ещё достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд." },
    ["4723c"] = { common = "Ещё одна находка, которую нам надо изучить. Хорошая работа! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." },
    ["4725a"] = { common = "Ещё одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки клана Серой Мглы, питающиеся мертвечиной. Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай'Леггонд сможет что-то понять?" },
    ["4725c"] = { common = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега. Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." },
    ["4727a"] = { common = "Скелет морской черепахи лежит на песчаной отмели на севере Тёмного Берега. Мурлоки клана Серой Мглы либо не нашли её тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны." },
    ["4727c"] = { common = "Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнём изучать эти останки! Благодарю вас за ваши труды; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время." },
    ["4728a"] = { common = "Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине." },
    ["4728c"] = { common = "О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Тёмном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скромную плату от имени Храма Луны." },
    ["4730a"] = { common = "Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд." },
    ["4730c"] = { common = "Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесёт свои плоды, и мы что-то узнаем. И снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны." },
    ["4731a"] = { common = "Ещё одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая ещё частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки клана Серой Мглы сделали остов этой твари своим жилищем. Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?" },
    ["4731c"] = { common = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега. Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." },
    ["4732a"] = { common = "Вы обнаружили тело морской черепахи, выбросившейся на Тёмный Берег некоторое время назад. Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков. Однако, похоже, несколько подходящих образцов для Гвиннед Блай'Леггонд вы сможете отобрать." },
    ["4732c"] = { common = "Так вы нашли и других выбросившихся на берег тварей? Морские черепахи обычно резвились в водах у подножья Нордрассиля – до его гибели. Однако с рождением Тельдрассила этих созданий становится всё меньше и меньше. Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему. Быть может, ваша помощь поможет нам раскрыть эту тайну. Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований." },
    ["4733a"] = { common = "Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Тёмного Берега. Хотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд." },
    ["4733c"] = { common = "Габариты этого крепкозуба, о котором вы рассказываете, просто ошеломляют. Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше. В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается. Интересно, связано ли как-то это с выбрасывающимися на берег тварями? Мы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны. Благодарю вас." },
    ["4740a"] = { common = "Внимание! Назначена награда за голову мурлока, именуемого \"Глубомрак\". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Тёмного Берега! Глубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждёт смельчака у часового Глинды Нал'Шии в Аубердине. Совет Аубердина" },
    ["4740c"] = { male = "Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее. Сегодня вы послужили для наших жителей орудием справедливости. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина.", female = "Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее. Сегодня вы послужили для наших жителей орудием справедливости. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящей героини народа Аубердина." },
    ["4761a"] = { common = "При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов. Я уверен, что у него есть свои идеи по поводу источника наведённой на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!" },
    ["4761c"] = { male = "Рад нашей встрече, герой. Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.", female = "Рад нашей встрече, героиня. Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." },
    ["4762a"] = { common = "Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи. Возьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмёте пробу, вернитесь ко мне в Аубердин." },
    ["4762c"] = { common = "Я не удивлён тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится! Похоже, что нужно действовать как можно скорее, да? К востоку от нас находится Осквернённый лес; это и есть настоящий источник порчи, я в прошлом такой уже видел. Заранее могу сказать, что ваша проба подтвердит это. Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать. Когда придёт время, я надеюсь, вы сможете нам её предоставить." },
    ["4763a"] = { common = "Мы узнали, что источником порчи, наведённой на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов ещё есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы! Наполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай всё и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечёт внимание сатира... которого нужно убить!" },
    ["4763c"] = { male = "Мы только начали войну за освобождение наших лесов от порабощающих сил Скверны, но сегодняшняя битва выиграна! путник, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков.", female = "Мы только начали войну за освобождение наших лесов от порабощающих сил Скверны, но сегодняшняя битва выиграна! путница, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." },
    ["4811a"] = { common = "К востоку отсюда становится всё больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично. Я получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Тёмного Берега. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите." },
    ["4811c"] = { common = "Так значит, кристалл существует? Как интересно... В любом случае, вы хорошо справились с заданием. Отличная работа! А какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов... На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло? У меня ещё много вопросов, но нам придётся пристально изучить кристалл, чтобы добиться хоть каких-то ответов." },
    ["4812a"] = { common = "Возьмите этот пустой флакон и наполните его водой из лунного колодца в Аубердине. Её могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой. Хотя я не думаю, чтобы вам что-то угрожало, я всё же попрошу вас быть осторожнее. За горами на востоке находится Осквернённый лес, и если этот кристал как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным." },
    ["4812c"] = { common = "Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной..." },
    ["4813a"] = { common = "С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей. Задание выполнено, и всё, что вам остаётся, – это вернуться в Аубердин и доложить обо всём часовому Глинде Нал'Шие." },
    ["4813c"] = { common = "Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов. Я пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чём говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть её всерьёз. Что же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу." },
    ["4921a"] = { male = "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её. Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх. Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути. Прошу тебя, герой, узнай что-нибудь о моей жене.", female = "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её. Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх. Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути. Прошу тебя, героиня, узнай что-нибудь о моей жене." },
    ["4921c"] = { male = "Понятно. Спасибо, герой.", female = "Понятно. Спасибо, героиня." },
    ["5041a"] = { common = "Нападение на караваны лишает нас необходимых припасов. Тебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов? Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре? Народ Перекрёстка будет у тебя в неоплатном долгу." },
    ["5041c"] = { common = "Ха-ха! Спасибо! Ты нам очень помог. Ты неизменно спасаешь народ Перекрёстка и Орды. Если я могу что-нибудь для тебя сделать, обращайся." },
    ["5052a"] = { common = "Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотэмы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает* Секреты их магии мне известны. Принеси Кривозубу один кровавый осколок, и ты всё поймёшь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*" },
    ["5052c"] = { male = "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, путник. Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает Касание осколка, какое забытое ощущение, путник. Знаешь, каково это – чувствовать себя отрезанным от силы? Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает", female = "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, путница. Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает Касание осколка, какое забытое ощущение, путница. Знаешь, каково это – чувствовать себя отрезанным от силы? Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает" },
    ["5061a"] = { male = "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс. Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единым с водой. Доброго пути, юный друид. Мы ещё встретимся.", female = "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс. Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единой с водой. Доброго пути, дева-друид. Мы ещё встретимся." },
    ["5061c"] = { male = "Великолепно. Ты готов принимать водный облик, и я с радостью научу тебя. А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.", female = "Великолепно. Ты готова принимать водный облик, и я с радостью научу тебя. А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." },
    ["5261a"] = { common = "Иган Меховщик ищет охотника на волков. Это добрая новость, поскольку в последнее время в Долине Североземья звери уж чересчур расплодились. Если тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево." },
    ["5261c"] = { common = "Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?" },
    ["5321a"] = { common = "Я шёл к Заставе Мейстры, чтобы встретиться с Лиладрис Лунной Рекой, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я всё время такой сонный... Зевает И я нигде не могу найти свои вещи! Поможешь мне их отыскать? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Я пришёл оттуда... Да, и вот ещё что: я могу заснуть по дороге, так что если тебе нужно будет меня разбудить, сделай это с помощью моего рога. Он в этом сундуке." },
    ["5321c"] = { common = "О, я так рада, что Керлониан смог сюда добраться. И я уверена, что найду его спящим где-нибудь поблизости, ведь так? Спасибо вам за то, что показали ему дорогу." },
    ["5441a"] = { male = "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, путник, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку. Проклятые лентяи...", female = "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, путница, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку. Проклятые лентяи..." },
    ["5441c"] = { common = "Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!" },
    ["5481a"] = { common = "Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растёт тут и у дороги. Ты соберёшь – отнеси хозяину Холланду на кладбище в Брилл." },
    ["5481c"] = { common = "Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Тёмная Госпожа знает, – к этому делу таких простаков, как ты! Без обид. Ладно, главное, что ты здесь. Я не собираюсь тратить своё время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберёшь для меня этот проклятый погибельник?" },
    ["5482a"] = { male = "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу. Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь осторожен – в тех местах полно гноллов.", female = "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу. Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь осторожна – в тех местах полно гноллов." },
    ["5482c"] = { male = "А, мой погибельник! Превосходно! *Младший аптекарь Холланд жадно потирает ладони.* Он мне очень пригодится. Ты оказал мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда.", female = "А, мой погибельник! Превосходно! *Младший аптекарь Холланд жадно потирает ладони.* Он мне очень пригодится. Ты оказала мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда." },
    ["5541a"] = { male = "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны. Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела! не мог бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе.", female = "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны. Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела! не могла бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе." },
    ["5541c"] = { common = "Вот радость-то, ещё боеприпасы! Поставка старины Лослора, наконец, прибыла! Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда! Большое тебе спасибо. Покупатели тут заждались!" },
    ["5545a"] = { common = "У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю её отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам её забрать Я уже договорилась с заместителем судьи Рейнером насчёт зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесёшь мне восемь вязанок, я всё успею." },
    ["5545c"] = { common = "Великолепно! Благодаря тебе я сумела выполнить заказ вовремя. Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство. Спасибо – и до свидания!" },
    ["5621a"] = { male = "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты мог бы помочь одной из наших раненых часовых к югу от Доланаара. Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя. Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.", female = "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты могла бы помочь одной из наших раненых часовых к югу от Доланаара. Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя. Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне." },
    ["5621c"] = { male = "Ты хорошо послужил Элуне. Я благодарю тебя за это. Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужил своё место в наших кругах. Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии. Спасибо, и да благословит тебя великая Элуна.", female = "Ты хорошо послужила Элуне. Я благодарю тебя за это. Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужила своё место в наших кругах. Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии. Спасибо, и да благословит тебя великая Элуна." },
    ["5622a"] = { male = "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жреца Элуны. Будь осторожен, и да хранит тебя в пути Элуна!", female = "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жрицы Элуны. Будь осторожна, и да хранит тебя в пути Элуна!" },
    ["5622c"] = { common = "Я рада знать, что Шанда послала тебя найти меня. Обучение молодых жрецов, следующих пути Луны приносит мне большое удовольствие." },
    ["5623a"] = { male = "Приветствую тебя, юный жрец. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.", female = "Приветствую тебя, юная жрица. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью." },
    ["5623c"] = { common = "Я рада твоему прибытию. У нас есть, что обсудить касательно твоего будущего и твоего пути по дороге Света." },
    ["5624a"] = { common = "Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает. Но сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твоё испытание завершённым." },
    ["5624c"] = { male = "Прекрасно. Вылечив стражника ты тем самым помог городу, сделав жизнь в нём безопаснее. Рад видеть что ты уже изучил кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему... и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно.", female = "Прекрасно. Вылечив стражника ты тем самым помогла городу, сделав жизнь в нём безопаснее. Рад видеть что ты уже изучила кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему... и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." },
    ["5625a"] = { male = "Как правило, примерно в эту пору послушники вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф. Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошёл испытание. Справишься?", female = "Как правило, примерно в эту пору послушницы вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф. Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошла испытание. Справишься?" },
    ["5625c"] = { male = "Прекрасно. Вылечив стражника ты тем самым помог городу, сделав жизнь в нём безопаснее. Рад видеть что ты уже изучил кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему... и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно.", female = "Прекрасно. Вылечив стражника ты тем самым помогла городу, сделав жизнь в нём безопаснее. Рад видеть что ты уже изучила кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему... и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." },
    ["5626a"] = { male = "Эй! путник! У тебя есть свободная минутка?! Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойным, он тебе даст твои первые одеяния жреца. Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.", female = "Эй! путница! У тебя есть свободная минутка?! Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойной, он тебе даст твои первые одеяния жрицы. Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." },
    ["5626c"] = { male = "Тебя Брансток послал? Хорошо, хорошо. Ты сделал ещё один шаг навстречу Свету. Но тебе многое ещё надо усилить – силу тела... и силу воли.", female = "Тебя Брансток послал? Хорошо, хорошо. Ты сделала ещё один шаг навстречу Свету. Но тебе многое ещё надо усилить – силу тела... и силу воли." },
    ["5628a"] = { male = "Если не ошибаюсь? Рад, что ты уделил мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение! Если бы мне в молодые годы хватило духу постранствовать по миру... Тут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул.", female = "Если не ошибаюсь? Рад, что ты уделила мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение! Если бы мне в молодые годы хватило духу постранствовать по миру... Тут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул." },
    ["5628c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5629a"] = { male = "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдаётся, ты привлёк внимание наших старейшин, и они считают, что ты созрел для более великих дел. Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.", female = "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдаётся, ты привлекла внимание наших старейшин, и они считают, что ты созрела для более великих дел. Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна." },
    ["5629c"] = { male = "Хорошо, что ты вернулся. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5630a"] = { male = "Ну здравствуй, друг. Приятно видеть, что ты так далеко забрался! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплен из более крутого теста. Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашёл жрицу Алатею в храме Луны в Дарнассе. Должно быть, это важно так что возвращайся туда как можно скорее.", female = "Ну здравствуй, подруга. Приятно видеть, что ты так далеко забралась! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплена из более крутого теста. Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашла жрицу Алатею в храме Луны в Дарнассе. Должно быть, это важно так что возвращайся туда как можно скорее." },
    ["5630c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5631a"] = { male = "Недавно в наших чертогах побывала одна жрица, и она искала вас, юный путник. Она сказала, что её послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет.", female = "Недавно в наших чертогах побывала одна жрица, и она искала вас, юная путница. Она сказала, что её послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет." },
    ["5631c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5632a"] = { common = "Да-да, конечно. Здравствуй. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнасе случилось что-то важное и что тебе следует как можно скорее вернуться в Храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов. В общем, возвращайся в Дарнас, как только сможешь." },
    ["5633a"] = { male = "Добро пожаловать, друг. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом. Пока ты тут странствовал в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей.", female = "Добро пожаловать, подруга. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом. Пока ты тут странствовала в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей." },
    ["5634a"] = { male = "Недавно к нам заглянул жрец, которому был нужен ты, путник. Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне. Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет.", female = "Недавно к нам заглянул жрец, которому была нужна ты, путница. Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне. Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет." },
    ["5634c"] = { common = "Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за всё, сделанное тобой." },
    ["5635a"] = { male = "Ты привлёк внимание нашего начальства. Тебя просят как можно скорее отправиться в Зал Тайн в Стальгорне. Как я понимаю, вышестоящие считают, что ты уже достаточно показал себя и готов к дальнейшему обучению. Когда доберёшься туда, отыщи верховного жреца Рохана. Он расскажет, что делать дальше. Удачи и да пребудет с тобой Свет.", female = "Ты привлекла внимание нашего начальства. Тебя просят как можно скорее отправиться в Зал Тайн в Стальгорне. Как я понимаю, вышестоящие считают, что ты уже достаточно показала себя и готова к дальнейшему обучению. Когда доберёшься туда, отыщи верховного жреца Рохана. Он расскажет, что делать дальше. Удачи и да пребудет с тобой Свет." },
    ["5635c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5636a"] = { male = "Да благословит тебя Элуна, путник. Надеюсь, Свет остаётся с тобой и защищает тебя. Недавно тебя искал один из ваших жрецов. Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховным жрецом Роханом. Похоже, ты отлично себя показал, раз привлёк такое внимание. Не задерживайся здесь, ты нужен своим.", female = "Да благословит тебя Элуна, путница. Надеюсь, Свет остаётся с тобой и защищает тебя. Недавно тебя искал один из ваших жрецов. Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховным жрецом Роханом. Похоже, ты отлично себя показала, раз привлекла такое внимание. Не задерживайся здесь, ты нужна своим." },
    ["5636c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5637a"] = { male = "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховный жрец Рохан из Зала Тайн. Либо дела очень хороши, либо очень плохи, раз он решил встретиться с тобой лично. Но я подозреваю, что ты отлично себя показал, и то, что он хочет тебя видеть, это добрый знак. Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь.", female = "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховный жрец Рохан из Зала Тайн. Либо дела очень хороши, либо очень плохи, раз он решил встретиться с тобой лично. Но я подозреваю, что ты отлично себя показала, и то, что он хочет тебя видеть, это добрый знак. Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." },
    ["5637c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5639a"] = { male = "путник! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!", female = "путница! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" },
    ["5639c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5642a"] = { common = "В Оргриммаре происходит нечто важное. Обычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утёсе. Думаю, тебе стоит как можно скорее вернуться на Аллею Духов." },
    ["5643a"] = { common = "Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем." },
    ["5644a"] = { male = "Доброго тебе дня. Вижу, ты многому научился, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным. Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки. Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов.", female = "Доброго тебе дня. Вижу, ты многому научилась, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным. Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки. Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов." },
    ["5645a"] = { male = "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, могучий мой друг, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.", female = "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, могучая моя госпожа, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." },
    ["5646a"] = { common = "Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для её племени. Возвращайся в Подгород. Твоя госпожа ждёт тебя в Квартале Воинов, чтобы рассказать ещё больше о твоём народе и его обычаях. Ступай, не медли." },
    ["5646c"] = { male = "Ты вернулся, это хорошо, и даже не слишком поздно – это совсем здорово. У нас есть много вещей, которые надо обсудить.", female = "Ты вернулась, это хорошо, и даже не слишком поздно – это совсем здорово. У нас есть много вещей, которые надо обсудить." },
    ["5647a"] = { common = "Твоя раса так сильна. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только всё ближе к разгадке вашего истинного происхождения, но и обретаете всё большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу. Недавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна." },
    ["5648a"] = { male = "Что ж, вот ты и готов к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков. Сделай это – ия сочту, что ты подтвердил свою готовность ступить на путь жреца.", female = "Что ж, вот ты и готова к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков. Сделай это – ия сочту, что ты подтвердила свою готовность ступить на путь жреца." },
    ["5648c"] = { male = "Молодец... оживил и вылечил Кор'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей. Я вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу. Хорошо сработал. Возьми это одеяние. Может быть, оно пригодится тебе, может быть нет, но ты заслужил её и я рада назвать тебя братом.", female = "Умница... оживила и вылечила Кор'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей. Я вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу. Хорошо сработала. Возьми это одеяние. Может быть, оно пригодится тебе, может быть нет, но ты заслужила её и я рада назвать тебя сестрой." },
    ["5649a"] = { male = "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне. Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готов.", female = "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне. Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готова." },
    ["5649c"] = { male = "Аа... ты пришёл к Тай'джин. Это хорошо. Тебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее. Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас. Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов. Разница кажется незначительной, но ты узнаешь и почувствуешь её. Племя рассчитывает, что ты обучишься таким вещам.", female = "Аа... ты пришла к Тай'джин. Это хорошо. Тебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее. Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас. Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов. Разница кажется незначительной, но ты узнаешь и почувствуешь её. Племя рассчитывает, что ты обучишься таким вещам." },
    ["5650a"] = { common = "Мы черпаем силу из тьмы и теней, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание. К северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне." },
    ["5650c"] = { male = "Ты прошёл мой тест. Молодец. Итак, вскоре ты сможешь погрузить на себя ещё одну ношу, возложить на себя ответственность изучать тёмные энергии, к которым не имеет доступ жрец любой другой расы. Возьми это одеяние как символ! Носи его с гордостью.", female = "Ты прошела мой тест. Умница. Итак, вскоре ты сможешь погрузить на себя ещё одну ношу, возложить на себя ответственность изучать тёмные энергии, к которым не имеет доступ жрец любой другой расы. Возьми это одеяние как символ! Носи его с гордостью." },
    ["5651a"] = { common = "Отрёкшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро вы поймёте, что очень много вещей зависит от неё – так же как и от света. Вы научитесь использовать и то и другое... с должной осторожностью. Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом. Когда будете готовы узнать больше, разыщите тёмного священника Берила в Брилле." },
    ["5651c"] = { male = "Наконец-то ты появился. Одной лишь твоё веры недостаточно, чтобы пройти испытания, ожидающие тебя. Нужна настойчивость, да и немного честолюбия не помешает.", female = "Наконец-то ты появилась. Одной лишь твоё веры недостаточно, чтобы пройти испытания, ожидающие тебя. Нужна настойчивость, да и немного честолюбия не помешает." },
    ["5654a"] = { common = "Пора тебе встретиться с Ур'кьо. Ты найдёшь его на аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени." },
    ["5655a"] = { common = "Мне нужно было удостовериться, что ты не уйдёшь слишком далеко от дома. Меня послали за тобой потому, что Ур'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай в Аллею Духов в городе орков и поговори с Ур'кьо. Он ждёт тебя." },
    ["5656a"] = { common = "Моё нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь. Уркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдёшь его на аллее Духов." },
    ["5657a"] = { male = "Домой! Возвращайся домой, юный путник! Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути. Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там.", female = "Домой! Возвращайся домой, юная путница! Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути. Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там." },
    ["5660a"] = { male = "Далеко же ты забрался, герой. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.", female = "Далеко же ты забралась, героиня. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле." },
    ["5660c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5661a"] = { common = "Ты всего лишь гость в деревне Кровавого Копыта, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь. Говорят, что ваша главная жрица велит всем Отрёкшимся прийти к ней – видно, ей есть что сказать. Ступай, поговори с Эльталисте в Квартале воинов этого вашего города, как его там..." },
    ["5661c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5662a"] = { common = "Моё почтение тебе и твоему народу. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном. Возвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других. Ступай в Квартал Воинов Подгорода и отыщи там свою госпожу." },
    ["5662c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5663a"] = { male = "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение. Если ты в самом деле считаешь себя одним из верных, возвращайся туда. Эльталисте живёт в Квартале Воинов в глубинах Подгорода.", female = "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение. Если ты в самом деле считаешь себя одной из верных, возвращайся туда. Эльталисте живёт в Квартале Воинов в глубинах Подгорода." },
    ["5663c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5673a"] = { common = "Знай, что здесь ты можешь в любое время обратиться к любому наставнику. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она даёт особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание. Так что как сможешь – возвращайся и поговори со жрицей Алатеей." },
    ["5673c"] = { common = "Элуна благословляет тебя за столь быстрое возвращение. Важное дело ожидает тебя и важные дела ждут твоего решения. Когда отдохнёшь от своего путешествия повидай меня снова. Тогда мы обсудим, как именно мы начнём... точнее продолжим, твою тренировку!" },
    ["5674a"] = { male = "Настал славный день. Ты достиг возраста, когда наши жрецы изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.", female = "Настал славный день. Ты достигла возраста, когда наши жрицы изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." },
    ["5675a"] = { male = "Не тяни время, друг. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи.", female = "Не тяни время, подруга. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи." },
    ["5677a"] = { common = "Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймёшь, о чём я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь." },
    ["5677c"] = { common = "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа. Вы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." },
    ["5678a"] = { common = "Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами. Буду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них... Ты понимаешь, о чём я говорю? Вернись в Собор Света. Верховная жрица Лорена ждёт тебя." },
    ["5678c"] = { common = "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа. Вы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." },
    ["5713a"] = { common = "Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Во время атаки я получила отравление, так что еле держусь. Я могу изготовить противоядие, но это займёт некоторое время. Хотела попросить вас защитить меня, пока я не приму противоядие. Я подсоблю вам своим луком, как смогу. Если мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать её о случившемся." },
    ["5713c"] = { male = "Вы принесли долгожданное известие, герой. Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.", female = "Вы принесли долгожданное известие, героиня. Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь." },
    ["5722a"] = { common = "В Огненной пропасти Магату интересуют не только трогги. До неё дошли слухи, что один из её слуг, некий Маур Зловещий Тотэм, будучи в пропасти, нашёл нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашёл тело Маура – если оно ещё цело – и выяснил, что же он такое нашёл, пытаясь вести переговоры с троггами. Если найдёшь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду. Да, пропасть ищи в самых тёмных закоулках Оргриммара." },
    ["5722c"] = { common = "Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки. Вы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату." },
    ["5723a"] = { common = "Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на её переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для неё эти твари – враги Орды. Она просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную пропасть и уничтожь их всех!" },
    ["5723c"] = { common = "Я рад, что ты серьёзно отнёсся к просьбе Магаты. Спасибо тебе. Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность! Может, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо." },
    ["5724a"] = { common = "Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит её – видимо, он пытался уберечь её во время нападения троггов. Высвободив сумку из его крепкой хватки, вы закидываете её себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утёс." },
    ["5724c"] = { common = "Прекрасно. Благодарю тебя. Магата сказала мне, что если ты найдёшь её сородича, то я должен отдать тебе вот это. Прошу, прими в знак благодарности." },
    ["5725a"] = { common = "Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей. Некоторым из этих даров лучше бы оказаться в руках у Тёмной Госпожи, чем у... простецов. Например, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как \"Огненный Клинок\". Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы \"позаимствовать\" их. Выполни её волю." },
    ["5725c"] = { male = "Молодец, герой. Ты оказал Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети.", female = "Молодец, героиня. Ты оказал Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." },
    ["5726a"] = { male = "Чего я не потерплю, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее. Но ты, юный искатель приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора! Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне.", female = "Чего я не потерплю, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее. Но ты, юная искательница приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора! Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." },
    ["5726c"] = { common = "Молодец! Слава духам! Быть может, именно ты – тот, кому суждено избавить меня от самых серьёзных моих опасений! Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело? Ты мне напоминаешь меня самого в молодости... Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживём грядущую бурю. Ладно, сейчас не время рассыпаться в похвалах. То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что ещё предстоит... Но начало положено хорошее." },
    ["5727a"] = { male = "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий. В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам. Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одного из своих. А потом возвращайся ко мне.", female = "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий. В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам. Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одну из своих. А потом возвращайся ко мне." },
    ["5727c"] = { male = "Великолепно, герой! Просто великолепно! Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда. Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.", female = "Великолепно, героиня! Просто великолепно! Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда. Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." },
    ["5728a"] = { male = "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить. Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь осторожен, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одним из братьев по оружию.", female = "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить. Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь осторожна, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одной из сестёр по оружию." },
    ["5728c"] = { common = "Я рад, что ты вернулся. Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты. Мне даже докладывали, что Ниру более чем взбудоражен. Похоже, мы пробили брешь в его броне. Не могу не признать, что меня это радует... Пусть небольшая, но всё же победа." },
    ["5729a"] = { common = "Думаю, теперь тебе следует попытаться войти в число приближённых Нииру. Если он действительно так взбудоражен, как мне доносят, мы убьём сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнёт доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников. Возвращайся в Расселину и поговори с ним, но не особо навязывайся." },
    ["5729c"] = { male = "Ну в чём дело?! Ах, это ты, герой... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.", female = "Ну в чём дело?! Ах, это ты, героиня... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь." },
    ["5730a"] = { male = "Теперь ты один из моих лейтенантов! Готовься, герой. Скоро я призову тебя. Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.", female = "Теперь ты одна из моих лейтенантов! Готовься, героиня. Скоро я призову тебя. Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее." },
    ["5730c"] = { common = "Ясеневый лес? Хм. Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу. Я поручу своим агентам это проверить. А ты молодец. Пока отдыхай, занимайся другими делами. Скоро я призову тебя снова. Лок-тар Огар!" },
    ["5761a"] = { common = "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть ещё и Огненный Клинок, клан, который обосновался в Огненной пропасти и втайне смущает умы простых представителей Орды. Чтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный. Убей его. Я уверен, Вождь будет рад получить его сердце..." },
    ["5761c"] = { male = "Ага! Тебе это удалось! Тралл, конечно, будет в восторге. Я позабочусь о том, чтобы это сердце попало по назначению. Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, герой.", female = "Ага! Тебе это удалось! Тралл, конечно, будет в восторге. Я позабочусь о том, чтобы это сердце попало по назначению. Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, героиня." },
    ["5805a"] = { common = "Добро пожаловать в \"World of Warcraft\"! В знак особой благодарности за приобретение коллекционного издания \"World of Warcraft\" примите этот подарочный сертификат и передайте Мериссе Стилвелл в долине Североземья. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в \"World of Warcraft\"!" },
    ["5805c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5841a"] = { common = "Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Холодной долине. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft!" },
    ["5841c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5842a"] = { common = "Добро пожаловать в World of Warcraft! В качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Орентилу Шёпоту Ветра в Тенистой долине. Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!" },
    ["5842c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5843a"] = { common = "Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Магге в долине Испытаний. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft!" },
    ["5843c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5844a"] = { common = ".Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в лагере Нараче. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft" },
    ["5844c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5847a"] = { common = "Добро пожаловать в World of Warcraft! В качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Могильник. Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!" },
    ["5847c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5921a"] = { male = "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты встал на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юный друид.", female = "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты встала на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юная дева-друид." },
    ["5921c"] = { common = "\"Да будет так, отец Кенарий. Да будет так.\" Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы. \"Первое обличье, которое тебе следует освоить, - это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота! И так отныне будет всегда.\"" },
    ["5922a"] = { common = "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид." },
    ["5922c"] = { common = "Да будет так, отец Кенарий. Да будет так. Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы. Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда." },
    ["5923a"] = { common = "Не уделишь мне минутку внимания?.. Дошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила. Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." },
    ["5923c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5924a"] = { common = "Не уделишь мне минутку внимания?.. До моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами. Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас. Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле. Он обитает в анклаве Кенария в Дарнассе, на втором ярусе дерева Фэндрала Оленьего Шлема." },
    ["5924c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5925a"] = { common = "Не уделишь мне минутку внимания?.. Мне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила. Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." },
    ["5925c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5926a"] = { male = "Извини, друг... Дошло до меня, что Тюрак Рунический Тотэм желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя. Он живёт в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин.", female = "Извини, девушка... Дошло до меня, что Тюрак Рунический Тотэм желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя. Он живёт в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5926c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5927a"] = { male = "Извини, друг… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин.", female = "Извини, подруга… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5927c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5928a"] = { common = "Прости меня, друг мой… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5928c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5929a"] = { male = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки.", female = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." },
    ["5929c"] = { common = "Дендрит делает ещё один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается. \"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"" },
    ["5930a"] = { male = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки.", female = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." },
    ["5930c"] = { common = "Дендрит делает ещё один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается. Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя." },
    ["5931a"] = { common = "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живёт в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия. Ступай же, дитя. Мы ещё встретимся." },
    ["5931c"] = { common = "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной. Дух Великого Медведя был частью Азерота с самого его возникновения. Мы полагаемся на его мудрость и могущество в достижении наших целей. Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." },
    ["5932a"] = { common = "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотэм живёт в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия. Ступай же, дитя. Мы ещё встретимся." },
    ["5932c"] = { common = "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной. Дух Великого Медведя был частью Азерота с самого его возникновения. Мы, Таурены, внимательно прослушиваемся его мудрости и могуществу в достижении наших целей. Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." },
    ["6001a"] = { male = "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как один из друидов-медведей, должен овладеть. Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силами тела и духа, необходимыми друиду!", female = "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как одна из друидов-медведей, должен овладеть. Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силами тела и духа, необходимыми друиду!" },
    ["6001c"] = { male = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе и вижу, что ты перенял мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!", female = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе и вижу, что ты переняла мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" },
    ["6002a"] = { male = "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты должен овладеть, как один из друидов-медведей. Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силой тела и духа, необходимыми друиду!", female = "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты должна овладеть, как одна из друидов-медведей. Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силой тела и духа, необходимыми друиду!" },
    ["6002c"] = { common = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" },
    ["6061a"] = { common = "Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь всё ближе Матери-Земле. Приручив же зверя и сделав его своим помощником, мы делаем ещё один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога." },
    ["6061c"] = { male = "Я уже знаю, мать-земля сказала мне, что ты справился со своей задачей.", female = "Я уже знаю, мать-земля сказала мне, что ты справилась со своей задачей." },
    ["6062a"] = { male = "Умение подчинять природу своей воле – великое искусство. Ты охотник, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу. Обрести власть над животным – дело не простое, тут требуется решимость. Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне.", female = "Умение подчинять природу своей воле – великое искусство. Ты охотница, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу. Обрести власть над животным – дело не простое, тут требуется решимость. Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." },
    ["6062c"] = { common = "Молодец! Думаю, тебе уже можно поручить задачу посложнее..." },
    ["6063a"] = { male = "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Её следует почитать как нечто, без чего само твоё существование было бы невозможным. Ты должен доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника. Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника. Приручи его и поупражняйся в своём охотничьем искусстве.", female = "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Её следует почитать как нечто, без чего само твоё существование было бы невозможным. Ты должна доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника. Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника. Приручи его и поупражняйся в своём охотничьем искусстве." },
    ["6063c"] = { male = "Превосходно! Ты довольно способный ученик.", female = "Превосходно! Ты довольно способная ученица." },
    ["6064a"] = { male = "Привет, парень! Стало быть, хочешь узнать, как завести себе питомца? Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз. А пока займёмся тем, что, так интересует тебя в данный момент – питомцем! Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.", female = "Привет, подруга! Стало быть, хочешь узнать, как завести себе питомца? Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз. А пока займёмся тем, что, так интересует тебя в данный момент – питомцем! Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его." },
    ["6064c"] = { common = "Я знаю, знаю, ты думаешь – ну а дальше то что, а?" },
    ["6065a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6065c"] = { male = "Да, я полагаю, что ты уже готов...", female = "Да, я полагаю, что ты уже готова..." },
